INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('452192c3-4147-4f17-89e8-745dabec9fcc', '思不見', '思不见', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["但見出門蹤，不見入門跡。","却笑山頭女，無端化爲石。"]', '["但见出门蹤，不见入门跡。","却笑山头女，無端化爲石。"]', '诗', 'shi', '', NULL, '思不見 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5326d1c-04a3-4bbd-9301-fa8132fda3e5', '貴宅', '貴宅', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["入門又到門，到門戟相對。","玉簫聲尚遠，疑似人不在。","公子厭花繁，買藥栽庭內。","望遠不上樓，牕中見天外。","此地日烹羊，無異我食菜。","自是愁人眼，見之若奢泰。"]', '["入门又到门，到门戟相对。","玉簫声尚远，疑似人不在。","公子厭花繁，買藥栽庭內。","望远不上楼，牕中见天外。","此地日烹羊，無異我食菜。","自是愁人眼，见之若奢泰。"]', '诗', 'shi', '', NULL, '貴宅 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('324764f3-9736-4c3a-bd31-1a83f9aa7eec', '下第寄知己', '下第寄知己', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["長安孟春至，枯樹花亦發。","憂人此時心，冷若松上雪。","自知才不堪，豈敢頻泣血。","所痛無罪者，明時屢遭刖。","故山秋草多，一卷成古轍。","夜來遠心起，夢見瀟湘月。","大賢冠蓋高，何事憐屑屑。","不令傷弓鳥，日暮飛向越。","聞知感激語，胸中如有物。","舉頭望青天，白日頭上沒。","歸來通濟里，開戶山鼠出。","中庭廣寂寥，但見薇與蕨。","無慮數尺軀，委作泉下骨。","唯愁攬清鏡，不見昨日髪。","願憐閨中女，晚嫁唯守節。","勿惜四座言，女巧難自說。"]', '["长安孟春至，枯樹花亦發。","憂人此时心，冷若松上雪。","自知才不堪，豈敢頻泣血。","所痛無罪者，明时屢遭刖。","故山秋草多，一卷成古轍。","夜来远心起，梦见瀟湘月。","大賢冠蓋高，何事怜屑屑。","不令傷弓鸟，日暮飞向越。","闻知感激語，胸中如有物。","舉头望青天，白日头上沒。","归来通濟里，开戶山鼠出。","中庭廣寂寥，但见薇與蕨。","無慮數尺軀，委作泉下骨。","唯愁攬清镜，不见昨日髪。","願怜閨中女，晚嫁唯守節。","勿惜四座言，女巧难自说。"]', '诗', 'shi', '', NULL, '下第寄知己 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef02926e-8d11-4e30-8720-450e8fa3668d', '吳宮宴', '吳宮宴', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["吳宮城闕高，龍鳳遙相倚。","四面鏗鼓鐘，中央列羅綺。","春風時一來，蘭麝聞數里。","三度明月落，青娥醉不起。","江頭銕劍鳴，玉座成荒壘。","適來歌舞處，未知身是鬼。"]', '["吳宮城闕高，龙鳳遙相倚。","四面鏗鼓鐘，中央列羅綺。","春风时一来，蘭麝闻數里。","三度明月落，青娥醉不起。","江头銕劍鳴，玉座成荒壘。","適来歌舞处，未知身是鬼。"]', '诗', 'shi', '', NULL, '吳宮宴 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e95d93-c708-49ba-a7a6-9221cad5e3be', '長相思', '长相思', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["翦妾身上巾，贈郎傷妾神。","郎車不暫停，妾貌寧長春。","青天無停雪，滄海無停津。","遣妾空牀夢，夜夜隨車輪。"]', '["翦妾身上巾，贈郎傷妾神。","郎车不暫停，妾貌寧长春。","青天無停雪，滄海無停津。","遣妾空牀梦，夜夜隨车輪。"]', '诗', 'shi', '', NULL, '長相思 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237d6fd8-620f-4a65-b8c9-bc6a5afbba3e', '長城下', '长城下', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["遠水猶歸壑，征人合憶鄉。","泣多盈袖血，吟苦滿頭霜。","楚國連天浪，衡門到海荒。","何當生燕羽，時得近雕梁。"]', '["远水猶归壑，征人合憶乡。","泣多盈袖血，吟苦满头霜。","楚国連天浪，衡门到海荒。","何當生燕羽，时得近雕梁。"]', '诗', 'shi', '', NULL, '長城下 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c74bc100-e525-4aaa-8157-1825c540e887', '成名後獻恩門', '成名後獻恩门', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["爲物稍有香，心遭蠹虫嚙。","平人登太行，萬萬車輪折。","一辭桂嶺猨，九泣東門月。","年年孟春時，看花不如雪。","僻居城南隅，顏子須泣血。","沈埋若九泉，誰肯開口說。","辛勤學機杼，坐對秋燈滅。","織錦花不常，見之盡云拙。","自憐孤生竹，出土便有節。","每聽浮競言，喉中似無舌。","忽然風雷至，驚起池中物。","拔上青雲巔，輕如一毫髪。","瓏瓏金鎖甲，稍稍城烏絕。","名字如鳥飛，數日便到越。","幽蘭生雖晚，幽香亦難歇。","何以保此身，終身事無缺。"]', '["爲物稍有香，心遭蠹虫嚙。","平人登太行，万万车輪折。","一辞桂嶺猨，九泣东门月。","年年孟春时，看花不如雪。","僻居城南隅，顏子須泣血。","沈埋若九泉，誰肯开口说。","辛勤学機杼，坐对秋灯滅。","织錦花不常，见之尽云拙。","自怜孤生竹，出土便有節。","每听浮競言，喉中似無舌。","忽然风雷至，驚起池中物。","拔上青云巔，轻如一毫髪。","瓏瓏金鎖甲，稍稍城烏絕。","名字如鸟飞，數日便到越。","幽蘭生雖晚，幽香亦难歇。","何以保此身，終身事無缺。"]', '诗', 'shi', '', NULL, '成名後獻恩門 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d129a7c0-5998-4c4f-bb36-462981c86c3d', '贈道師', '贈道師', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["舉世皆問人，唯師獨求己。","一馬無四蹄，頃刻行千里。","應笑北原上，丘墳亂如蟻。"]', '["舉世皆问人，唯師独求己。","一马無四蹄，頃刻行千里。","應笑北原上，丘墳亂如蟻。"]', '诗', 'shi', '', NULL, '贈道師 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec3a6ca-627c-4404-89e2-c3b2ed761ae4', '入關', '入关', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["衡門亦無路，何況入西秦。","灸病不得穴，徒爲採艾人。"]', '["衡门亦無路，何況入西秦。","灸病不得穴，徒爲採艾人。"]', '诗', 'shi', '', NULL, '入關 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c61417-2b6c-4cc4-ae33-8d4e2a16d721', '聽劉尊師彈琴', '听劉尊師彈琴', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["曾於清海獨聞蟬，又向空庭夜聽泉。","不似齋堂人靜處，秋聲長在七條弦。"]', '["曾於清海独闻蟬，又向空庭夜听泉。","不似斋堂人静处，秋声长在七條弦。"]', '诗', 'shi', '', NULL, '聽劉尊師彈琴 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd70c9ee-2527-43d0-89f6-a32bd4a3aa03', '題山居', '題山居', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["掃葉煎茶摘葉書，心閑無夢夜窗虛。","只應光武恩波晚，豈是嚴君戀釣魚。"]', '["掃葉煎茶摘葉书，心闲無梦夜窗虛。","只應光武恩波晚，豈是嚴君戀釣鱼。"]', '诗', 'shi', '', NULL, '題山居 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75c8172b-2a0f-4dae-a71e-759beaa13207', '關試前送進士姚潛下第歸南陽', '关試前送進士姚潛下第归南陽', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["馬嘶殘日沒殘霞，二月東風便到家。","莫羨長安占春者，明年始見故園花。"]', '["马嘶殘日沒殘霞，二月东风便到家。","莫羨长安占春者，明年始见故园花。"]', '诗', 'shi', '', NULL, '關試前送進士姚潛下第歸南陽 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e21b24b3-dfad-42be-892b-2ab9e5a40a1b', '滻川寄進士劉駕', '滻川寄進士劉駕', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["我家不背水，君身不向越。","自是相憶苦，忽如經年別。","山家草木寒，石上有殘雪。","美人望不見，迢迢雲中月。"]', '["我家不背水，君身不向越。","自是相憶苦，忽如經年別。","山家草木寒，石上有殘雪。","美人望不见，迢迢云中月。"]', '诗', 'shi', '', NULL, '滻川寄進士劉駕 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb3e6ce9-a0ed-4fde-bc98-20c297fc9ffa', '翠孤至渚宮寄座主相公', '翠孤至渚宮寄座主相公', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["萬里一孤舟，春行夏方到。","骨肉盡單羸，沈憂滿懷抱。","羈孤相對泣，性命不相保。","開戶山鼠驚，蟲聲亂秋草。","白菌緣屋生，黃蒿擁籬倒。","對此起長嗟，芳年亦須老。","恩門爲宰相，出入用天道。","忽於摧落間，收得青松操。","全家到江陵，屋虛風浩浩。","中腸自相伐，日夕如寇盜。","其下有孤姪，其上有孀嫂。","黃糧賤於土，一飯常不飽。","天斜日光薄，地濕蟲呌噪。","惟恐道忽消，形容益枯槁。","古人於黃雀，豈望白環報。","奉荅恩地恩，何慙以誠告。"]', '["万里一孤舟，春行夏方到。","骨肉尽單羸，沈憂满懷抱。","羈孤相对泣，性命不相保。","开戶山鼠驚，蟲声亂秋草。","白菌緣屋生，黄蒿擁籬倒。","对此起长嗟，芳年亦須老。","恩门爲宰相，出入用天道。","忽於摧落间，收得青松操。","全家到江陵，屋虛风浩浩。","中腸自相伐，日夕如寇盜。","其下有孤姪，其上有孀嫂。","黄糧賤於土，一飯常不飽。","天斜日光薄，地濕蟲呌噪。","惟恐道忽消，形容益枯槁。","古人於黄雀，豈望白环報。","奉荅恩地恩，何慙以誠告。"]', '诗', 'shi', '', NULL, '翠孤至渚宮寄座主相公 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e0bb32-de2b-4b23-a024-d97a8cabb41d', '早秋宿田舍', '早秋宿田舍', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["澗草疎疎螢火光，山月朗朗楓樹長。","南村犢子夜聲急，應是欄邊新有霜。"]', '["澗草疎疎螢火光，山月朗朗楓樹长。","南村犢子夜声急，應是欄邊新有霜。"]', '诗', 'shi', '', NULL, '早秋宿田舍 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea788b92-605b-4aad-8288-6413166ef2a1', '旅次岳陽寄京中親故', '旅次岳陽寄京中親故', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["君山南面浪連天，一客愁心兩處懸。","身逐片帆歸楚澤，魂隨流水向秦川。","月回浦北千尋雪，樹出湖東幾點煙。","更欲登樓向西望，北風催上洞庭船。"]', '["君山南面浪連天，一客愁心兩处懸。","身逐片帆归楚澤，魂隨流水向秦川。","月回浦北千尋雪，樹出湖东幾点煙。","更欲登楼向西望，北风催上洞庭船。"]', '诗', 'shi', '', NULL, '旅次岳陽寄京中親故 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9bb4b3e-bf8e-4fb8-a9cd-a6f7dba76100', '題舒鄉', '題舒乡', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["功名若及鴟夷子，必擬將舟泛洞庭。","柳色湖光好相待，我心非醉亦非醒。"]', '["功名若及鴟夷子，必擬將舟泛洞庭。","柳色湖光好相待，我心非醉亦非醒。"]', '诗', 'shi', '', NULL, '題舒鄉 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f6f6502-bd7f-4e24-b6a5-b5aaf60da6ed', '碧尋宴上有懷知己', '碧尋宴上有懷知己', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["荻花蘆葉滿溪流，一簇笙歌在水樓。","金管曲長人盡醉，玉簪恩重獨生愁。","女蘿力弱難逢地，桐樹心孤易感秋。","莫怪當歡却惆悵，全家欲上五湖舟。"]', '["荻花蘆葉满溪流，一簇笙歌在水楼。","金管曲长人尽醉，玉簪恩重独生愁。","女蘿力弱难逢地，桐樹心孤易感秋。","莫怪當歡却惆悵，全家欲上五湖舟。"]', '诗', 'shi', '', NULL, '碧尋宴上有懷知己 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213afecd-246c-4787-bdb4-1101de9acec5', '從天平節度使遊平流園', '從天平節度使游平流园', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["池塘靜於寺，俗事不到眼。","下馬如在山，令人忽疎散。","明公有高思，到此遂長返。","乘興挈一壺，折荷以爲盞。","入竹藤似虵，侵牆水成蘚。","幽鳥不識人，時來拂冠冕。","沿流路若窮，及行路猶遠。","洞中已云夕，洞口天未晚。","自憐不羈者，寫物心常簡。","飜愁此興多，引得嵇康嬾。"]', '["池塘静於寺，俗事不到眼。","下马如在山，令人忽疎散。","明公有高思，到此遂长返。","乘兴挈一壺，折荷以爲盞。","入竹藤似虵，侵牆水成蘚。","幽鸟不識人，时来拂冠冕。","沿流路若窮，及行路猶远。","洞中已云夕，洞口天未晚。","自怜不羈者，寫物心常簡。","飜愁此兴多，引得嵇康嬾。"]', '诗', 'shi', '', NULL, '從天平節度使遊平流園 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb056fbb-6fd2-4a5d-a4df-38cf4a90f587', '故人寄茶', '故人寄茶', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["劍外九華英，緘題下玉京。","開時微月上，碾處亂泉聲。","半夜招僧至，孤吟對月烹。","碧沈霞脚碎，香泛乳花輕。","六腑睡神去，數朝詩思清。","月餘不敢費，留伴肘書行。"]', '["劍外九华英，緘題下玉京。","开时微月上，碾处亂泉声。","半夜招僧至，孤吟对月烹。","碧沈霞脚碎，香泛乳花轻。","六腑睡神去，數朝诗思清。","月餘不敢費，留伴肘书行。"]', '诗', 'shi', '', NULL, '故人寄茶 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2cd4b01-b82d-4f18-9c55-5f5f79b4e82c', '東武吟', '东武吟', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["心如山上虎，身若倉中鼠。","惆悵倚市門，無人與之語。","夜宴李將軍，欲望心相許。","何曾聽我言，貪謔邯鄲女。","獨上黃金臺，淒涼淚如雨。"]', '["心如山上虎，身若倉中鼠。","惆悵倚市门，無人與之語。","夜宴李將軍，欲望心相許。","何曾听我言，貪謔邯鄲女。","独上黄金台，淒涼泪如雨。"]', '诗', 'shi', '', NULL, '東武吟 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659904fd-5a08-470d-8963-1180f95540cc', '薊北門行', '薊北门行', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["長河凍如石，征人夜中戍。","但恐筋力盡，敢憚將軍遇。","古來死未歇，白骨礙官路。","豈無一有功，可以高其墓。","親戚牽衣泣，悲號自相顧。","死者雖無言，那堪生者悟。","不如無手足，得見齒髪暮。","乃知七尺軀，却是速死具。"]', '["长河凍如石，征人夜中戍。","但恐筋力尽，敢憚將軍遇。","古来死未歇，白骨礙官路。","豈無一有功，可以高其墓。","親戚牽衣泣，悲號自相顧。","死者雖無言，那堪生者悟。","不如無手足，得见齒髪暮。","乃知七尺軀，却是速死具。"]', '诗', 'shi', '', NULL, '薊北門行 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51522634-af76-486e-af3b-38eb1f3d4137', '金井怨', '金井怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["西風吹急景，美人照金井。","不見面上花，却恨井中影。"]', '["西风吹急景，美人照金井。","不见面上花，却恨井中影。"]', '诗', 'shi', '', NULL, '金井怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8c77652-83ef-4e15-ac5b-0a746012a098', '姑蘇臺', '姑蘇台', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["南宮酒未銷，又宴姑蘇臺。","美人和淚去，半夜閶門開。","相對正歌舞，笑中聞鼓鼙。","星散九重門，血流十二街。","一去成萬古，臺盡人不回。","時聞野田中，拾得黃金釵。"]', '["南宮酒未銷，又宴姑蘇台。","美人和泪去，半夜閶门开。","相对正歌舞，笑中闻鼓鼙。","星散九重门，血流十二街。","一去成万古，台尽人不回。","时闻野田中，拾得黄金釵。"]', '诗', 'shi', '', NULL, '姑蘇臺 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b95d2d6-592f-42b6-bd42-d58dc2bbe05c', '夜坐有懷', '夜坐有懷', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["悄悄月出樹，東南若微霜。","愁人不成寐，五月夜亦長。","佳期杳天末，骨肉不在旁。","年華且有恨，厥體難久康。","人言力耕者，歲旱亦有糧。","吾道固如此，安得苦倀倀。"]', '["悄悄月出樹，东南若微霜。","愁人不成寐，五月夜亦长。","佳期杳天末，骨肉不在旁。","年华且有恨，厥體难久康。","人言力耕者，歲旱亦有糧。","吾道固如此，安得苦倀倀。"]', '诗', 'shi', '', NULL, '夜坐有懷 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6057d85c-3a20-4225-9a40-a5abbbeab95f', '寄監察從兄', '寄監察從兄', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["我祖居鄴地，鄴人識文星。","此地星已落，兼無古時城。","古風既無根，千載難重生。","空留建安書，傳說七子名。","賤子生桂州，桂州山水清。","自覺心貌古，兼合古人情。","因爲二雅詩，出語有性靈。","持來向長安，時得長者驚。","芝草不爲瑞，還共木葉零。","恨如轍中土，終歲填不平。","吾宗戴豸冠，忽然入西京。","憐其羽翼單，撫若親弟兄。","松根已堅牢，松葉豈不榮。","言罷眼無淚，心中如酒酲。"]', '["我祖居鄴地，鄴人識文星。","此地星已落，兼無古时城。","古风既無根，千載难重生。","空留建安书，傳说七子名。","賤子生桂州，桂州山水清。","自覺心貌古，兼合古人情。","因爲二雅诗，出語有性靈。","持来向长安，时得长者驚。","芝草不爲瑞，還共木葉零。","恨如轍中土，終歲填不平。","吾宗戴豸冠，忽然入西京。","怜其羽翼單，撫若親弟兄。","松根已堅牢，松葉豈不榮。","言罷眼無泪，心中如酒酲。"]', '诗', 'shi', '', NULL, '寄監察從兄 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83caa9e0-6022-4d7d-9057-88851ec4c280', '樂府體', '乐府體', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["蓮子房房嫩，菖蒲葉葉齊。","共結池中根，不厭池中泥。"]', '["蓮子房房嫩，菖蒲葉葉齊。","共結池中根，不厭池中泥。"]', '诗', 'shi', '', NULL, '樂府體 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04f91bb5-0deb-442b-b5fe-c95c11b3c515', '棄婦', '棄婦', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["嫁來未曾出，此去長別離。","父母亦有家，羞言何以歸。","此日年且少，事姑常有儀。","見多自成醜，不待顏色衰。","何人不識寵，所嗟無自非。","將欲告此意，四鄰已相疑。"]', '["嫁来未曾出，此去长別離。","父母亦有家，羞言何以归。","此日年且少，事姑常有儀。","见多自成醜，不待顏色衰。","何人不識寵，所嗟無自非。","將欲告此意，四鄰已相疑。"]', '诗', 'shi', '', NULL, '棄婦 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5fefd3-d775-4fae-94b7-b92a3f018732', '讀李斯傳', '读李斯傳', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["一車致三轂，本圖行地速。","不知駕馭難，舉足成顛覆。","欺暗尚不然，欺明當自戮。","難將一人手，掩得天下目。","不見三尺墳，雲陽草空綠。"]', '["一车致三轂，本圖行地速。","不知駕馭难，舉足成顛覆。","欺暗尚不然，欺明當自戮。","难將一人手，掩得天下目。","不见三尺墳，云陽草空綠。"]', '诗', 'shi', '', NULL, '讀李斯傳 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6ac3d7-9e04-4c74-9726-953c3455a4e6', '文宗陵', '文宗陵', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["千年堯舜心，心成身已歿。","始隨蒼梧雲，不返蒼龍闕。","宮女衣不香，黃金賜白髮。","留此奉天下，所以無征伐。","至今汨羅水，不葬大夫骨。"]', '["千年堯舜心，心成身已歿。","始隨蒼梧云，不返蒼龙闕。","宮女衣不香，黄金賜白髮。","留此奉天下，所以無征伐。","至今汨羅水，不葬大夫骨。"]', '诗', 'shi', '', NULL, '文宗陵 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e58e50-c4d6-47f9-bc4d-a4aa2d8509f1', '偶懷', '偶懷', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["開目不見路，常如夜中行。","最賤不自勉，中塗與誰爭。","蓬爲沙所危，還向沙上生。","一年秋不熟，安得便廢耕。","顏子命未達，亦遇時人輕。"]', '["开目不见路，常如夜中行。","最賤不自勉，中塗與誰爭。","蓬爲沙所危，還向沙上生。","一年秋不熟，安得便廢耕。","顏子命未達，亦遇时人轻。"]', '诗', 'shi', '', NULL, '偶懷 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7862a36-d686-41f4-ab41-1218ec41e8fa', '代羅敷誚使君', '代羅敷誚使君', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["常言愛嵩山，別妾向東京。","朝來見人說，却知在石城。","未必菖蒲花，只向石城生。","自是使君眼，見物皆有情。","麋鹿同上山，蓮藕同在泥。","莫學天上日，朝東暮還西。"]', '["常言愛嵩山，別妾向东京。","朝来见人说，却知在石城。","未必菖蒲花，只向石城生。","自是使君眼，见物皆有情。","麋鹿同上山，蓮藕同在泥。","莫学天上日，朝东暮還西。"]', '诗', 'shi', '', NULL, '代羅敷誚使君 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba844ae-3349-45f1-81ba-435377b926a5', '怨歌行', '怨歌行', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["丈夫好弓劍，行坐說金吾。","喜聞有行役，結束不待車。","官田贈倡婦，留妾待舅姑。","舅姑皆已死，庭花半是蕪。","中妹尋適人，生女亦嫁夫。","何曾寄消息，他處却有書。","嚴風厲中野，女子心易孤。","貧賤又相負，封侯意何如。"]', '["丈夫好弓劍，行坐说金吾。","喜闻有行役，結束不待车。","官田贈倡婦，留妾待舅姑。","舅姑皆已死，庭花半是蕪。","中妹尋適人，生女亦嫁夫。","何曾寄消息，他处却有书。","嚴风厲中野，女子心易孤。","貧賤又相負，封侯意何如。"]', '诗', 'shi', '', NULL, '怨歌行 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a22763d6-eb7f-4487-a68d-dad57e5ef898', '南征怨', '南征怨', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["萬浪東不回，昭王南征早。","龍舟沒何處，獨樹江上老。","吾欲問水濱，宮殿已生草。"]', '["万浪东不回，昭王南征早。","龙舟沒何处，独樹江上老。","吾欲问水濱，宮殿已生草。"]', '诗', 'shi', '', NULL, '南征怨 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d51e68c-b647-45fd-9d4d-60f6b6134862', '和潘安仁金谷集', '和潘安仁金谷集', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["太守龍爲馬，將軍金作車。","香飄十里風，風下綠珠歌。","莫怪坐上客，歎君庭前花。","明朝此池館，不是石崇家。"]', '["太守龙爲马，將軍金作车。","香飄十里风，风下綠珠歌。","莫怪坐上客，歎君庭前花。","明朝此池館，不是石崇家。"]', '诗', 'shi', '', NULL, '和潘安仁金谷集 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ba1dd5-dcb9-4023-9242-18c0893f1e54', '不可見', '不可见', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["常聞貧賤夫，頭白終相待。","自從嫁黔婁，終歲長不在。","君夢有雙影，妾夢空四鄰。","常思勁北風，吹折雙車輪。"]', '["常闻貧賤夫，头白終相待。","自從嫁黔婁，終歲长不在。","君梦有雙影，妾梦空四鄰。","常思勁北风，吹折雙车輪。"]', '诗', 'shi', '', NULL, '不可見 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b18fa6-1a74-4a2c-9a82-515afc7c7c97', '秦後作', '秦後作', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["大道不居謙，八荒安苟得。","木中不生火，高殿禍頃刻。","誰將白帝子，踐我禮義域。","空持拔山志，欲奪天地德。","軹道人不回，壯士斷消息。","父母骨成薪，蟲蛇自相食。","鼎亂陰陽疑，戰盡鬼神力。","東郊龍見血，九土玄黃色。","鼙鼓裂二景，妖星動中國。","圓丘無日月，曠野失南北。","徒流殺人血，神器終不忒。","一馬渡空江，始知賢者賊。"]', '["大道不居謙，八荒安苟得。","木中不生火，高殿禍頃刻。","誰將白帝子，踐我禮義域。","空持拔山志，欲奪天地德。","軹道人不回，壯士斷消息。","父母骨成薪，蟲蛇自相食。","鼎亂陰陽疑，戰尽鬼神力。","东郊龙见血，九土玄黄色。","鼙鼓裂二景，妖星动中国。","圓丘無日月，曠野失南北。","徒流殺人血，神器終不忒。","一马渡空江，始知賢者賊。"]', '诗', 'shi', '', NULL, '秦後作 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d59139f6-d716-432e-9366-a8aec7877108', '薄命妾', '薄命妾', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["薄命常惻惻，出門見南北。","劉郎馬蹄疾，何處去不得？","淚珠不可收，蟲絲不可織。","知君綠桑下，更有新相識。"]', '["薄命常惻惻，出门见南北。","劉郎马蹄疾，何处去不得？","泪珠不可收，蟲絲不可织。","知君綠桑下，更有新相識。"]', '诗', 'shi', '', NULL, '薄命妾 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb2a401e-c1e8-475d-b784-8408f90836c4', '放歌行', '放歌行', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["莫唱放歌行，此歌臨楚水。","人皆惡此聲，唱者終不已。","三閭有何罪，不向枕上死。"]', '["莫唱放歌行，此歌臨楚水。","人皆惡此声，唱者終不已。","三閭有何罪，不向枕上死。"]', '诗', 'shi', '', NULL, '放歌行 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3006ce-e15b-4d76-926e-280d575bc088', '江西送人', '江西送人', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["八月江上樓，西風令人愁。","攜酒樓上別，盡見四山秋。","但愁今日知，莫作他時疑。","郎本不住此，無人泣望歸。","何水不生波，何木不改柯。","遙知明日恨，不如今日多。","將心速投人，路遠人如何。"]', '["八月江上楼，西风令人愁。","携酒楼上別，尽见四山秋。","但愁今日知，莫作他时疑。","郎本不住此，無人泣望归。","何水不生波，何木不改柯。","遙知明日恨，不如今日多。","將心速投人，路远人如何。"]', '诗', 'shi', '', NULL, '江西送人 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af8c5bf-75c5-4fed-a031-38451791bd4c', '始皇陵下作', '始皇陵下作', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["千金買魚燈，泉下照狐兔。","行人上陵過，却弔扶蘇墓。","纍纍壙中物，多於養生具。","若使山可移，應將秦國去。","舜歿雖在前，今猶未封樹。"]', '["千金買鱼灯，泉下照狐兔。","行人上陵過，却弔扶蘇墓。","纍纍壙中物，多於養生具。","若使山可移，應將秦国去。","舜歿雖在前，今猶未封樹。"]', '诗', 'shi', '', NULL, '始皇陵下作 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce227e4-72f0-41be-9bd2-570be177f1b7', '洛原西望', '洛原西望', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["築城畏不堅，城堅心自毀。","秦樹滿平原，秦人不居此。","猶爲泣路者，無力報天子。"]', '["築城畏不堅，城堅心自毀。","秦樹满平原，秦人不居此。","猶爲泣路者，無力報天子。"]', '诗', 'shi', '', NULL, '洛原西望 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49f9024b-7011-4947-ae86-7defeb5f67aa', '趙城懷古', '趙城懷古', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["邯鄲舊公子，騎馬又鳴珂。","手揮白玉鞭，不避五侯車。","閑愁春日短，沽酒入倡家。","一笑千萬金，醉中贈秦娥。","如今高原上，樹樹白楊花。"]', '["邯鄲旧公子，騎马又鳴珂。","手揮白玉鞭，不避五侯车。","闲愁春日短，沽酒入倡家。","一笑千万金，醉中贈秦娥。","如今高原上，樹樹白楊花。"]', '诗', 'shi', '', NULL, '趙城懷古 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d567c1-d798-453b-9d93-03c4b6e27cd5', '代班姬', '代班姬', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["寵極多妒容，乘車上金階。","歘然趙飛燕，不語到日西。","手把菖蒲花，君王喚不來。","常嫌鬢蟬重，乞人白玉釵。","君心無定波，咫尺流不回。","後宮門不掩，每夜黃鳥啼。","買得千金賦，花顏已如灰。"]', '["寵極多妒容，乘车上金階。","歘然趙飞燕，不語到日西。","手把菖蒲花，君王喚不来。","常嫌鬢蟬重，乞人白玉釵。","君心無定波，咫尺流不回。","後宮门不掩，每夜黄鸟啼。","買得千金賦，花顏已如灰。"]', '诗', 'shi', '', NULL, '代班姬 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58df1f9b-e999-4898-92cb-b269b97c84da', '庭草', '庭草', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["庭草根自淺，造化無遺功。","低回一寸心，不敢怨春風。"]', '["庭草根自淺，造化無遺功。","低回一寸心，不敢怨春风。"]', '诗', 'shi', '', NULL, '庭草 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d61a1c1-8ab4-493c-b778-f3c2d7b4e5a2', '過白起墓', '過白起墓', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["[夷]陵火焰滅，長平生氣低。","將軍臨老病，賜劍咸陽西。"]', '["[夷]陵火焰滅，长平生氣低。","將軍臨老病，賜劍咸陽西。"]', '诗', 'shi', '', NULL, '過白起墓 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b148ee89-cd8e-45ff-ad26-fab4cc6a8d5e', '對酒', '对酒', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["愛酒知是僻，難與性相捨。","未必獨醒人，便是不飲者。","晚歲無此物，何由住田野。"]', '["愛酒知是僻，难與性相捨。","未必独醒人，便是不饮者。","晚歲無此物，何由住田野。"]', '诗', 'shi', '', NULL, '對酒 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('422b759c-ce1f-4b20-9a7f-48df0b2f5417', '續幽憤', '續幽憤', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["繁霜作陰起，朱火乘夕發。","清晝冷無光，蘭膏坐銷歇。","惟公執天憲，身是臺中傑。","一逐楚大夫，何人爲君雪。","怱怱鬼方路，不許辭雙闕。","過門似他鄉，舉趾如遺轍。","八月黃草生，洪濤入雲熱。","危魂沒太行，客弔空骨節。","千年瘴江水，恨聲流不絕。"]', '["繁霜作陰起，朱火乘夕發。","清晝冷無光，蘭膏坐銷歇。","惟公執天憲，身是台中傑。","一逐楚大夫，何人爲君雪。","怱怱鬼方路，不許辞雙闕。","過门似他乡，舉趾如遺轍。","八月黄草生，洪濤入云熱。","危魂沒太行，客弔空骨節。","千年瘴江水，恨声流不絕。"]', '诗', 'shi', '', NULL, '續幽憤 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c5611d-3cf9-4262-b6c2-76663785c655', '古詞', '古词', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["高闕礙飛鳥，人言是君家。","經年不歸去，愛妾面上花。","妾面雖有花，妾心非女蘿。","郎妻自不重，於妾欲如何。"]', '["高闕礙飞鸟，人言是君家。","經年不归去，愛妾面上花。","妾面雖有花，妾心非女蘿。","郎妻自不重，於妾欲如何。"]', '诗', 'shi', '', NULL, '古詞 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf47740-a44c-45f3-8224-e11bcfd29dfd', '和謝豫章從宋公戲馬臺送孔令謝病', '和謝豫章從宋公戲马台送孔令謝病', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["碧樹杳云暮，朔風自西來。","佳人憶山水，置酒在高臺。","不必問流水，坐來日已西。","勸君速歸去，正及鷓鴣啼。"]', '["碧樹杳云暮，朔风自西来。","佳人憶山水，置酒在高台。","不必问流水，坐来日已西。","勸君速归去，正及鷓鴣啼。"]', '诗', 'shi', '', NULL, '和謝豫章從宋公戲馬臺送孔令謝病 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64458e92-e680-4804-99da-aebca507210b', '送進士李殷下第遊汾河', '送進士李殷下第游汾河', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["上國花照地，遣君向西征。","旁人亦有恨，況復故人情。","單車欲云去，別酒忽然醒。","如何今夜夢，半作道路程。","邊士不好禮，全家住軍城。","城中鼓角嚴，旅客常夜驚。","中有左記室，逢人眼光明。","西門未歸者，下馬如到京。","還應一開卷，爲子心不平。","慇懃說忠抱，壯志勿自輕。"]', '["上国花照地，遣君向西征。","旁人亦有恨，況复故人情。","單车欲云去，別酒忽然醒。","如何今夜梦，半作道路程。","邊士不好禮，全家住軍城。","城中鼓角嚴，旅客常夜驚。","中有左記室，逢人眼光明。","西门未归者，下马如到京。","還應一开卷，爲子心不平。","慇懃说忠抱，壯志勿自轻。"]', '诗', 'shi', '', NULL, '送進士李殷下第遊汾河 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55ae2bd6-7f22-471b-9e23-dd5d5df57061', '相思極', '相思極', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["妾顏與日空，君心與日新。","三年得一書，猶在湘之濱。","料君相輕意，知妾無至親。","況當受明禮，不令再嫁人。","願君從此日，化質爲妾身。"]', '["妾顏與日空，君心與日新。","三年得一书，猶在湘之濱。","料君相轻意，知妾無至親。","況當受明禮，不令再嫁人。","願君從此日，化質爲妾身。"]', '诗', 'shi', '', NULL, '相思極 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03cabdcf-db1c-4fb4-9d61-3a6b759849e1', '代謝玄暉新亭送范零陵', '代謝玄暉新亭送范零陵', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["楚水洪無際，滄茫接天涯。","相看不能語，獨鳥下江蘺。","蓬子悉有戀，蓬根却無期。","車輪自不住，何必怨路岐。","孟冬衣食薄，夢寐亦未遺。"]', '["楚水洪無際，滄茫接天涯。","相看不能語，独鸟下江蘺。","蓬子悉有戀，蓬根却無期。","车輪自不住，何必怨路岐。","孟冬衣食薄，梦寐亦未遺。"]', '诗', 'shi', '', NULL, '代謝玄暉新亭送范零陵 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9f4610e-7446-42fc-a7f5-ac149738b241', '山中效陶', '山中效陶', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["落第非有罪，茲山聊歸止。","山猨隔雲住，共飲山中水。","讀書時有興，坐石忘却起。","西山忽然暮，往往遺巾履。","經時一出門，兼候僮僕喜。","常被山翁笑，求名豈如此。","齒髪老未衰，何如且求己。"]', '["落第非有罪，茲山聊归止。","山猨隔云住，共饮山中水。","读书时有兴，坐石忘却起。","西山忽然暮，往往遺巾履。","經时一出门，兼候僮僕喜。","常被山翁笑，求名豈如此。","齒髪老未衰，何如且求己。"]', '诗', 'shi', '', NULL, '山中效陶 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebad722c-fbd2-497c-9124-6e6525bddecf', '城南野居寄知己', '城南野居寄知己', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["奔走未到我，在城如在村。","出門既無意，豈如常閉門。","作詩二十載，闕下名不聞。","無人爲開口，君子獨有言。","身爲苦寒士，一笑亦感恩。","慇懃中途上，勿使車無輪。"]', '["奔走未到我，在城如在村。","出门既無意，豈如常閉门。","作诗二十載，闕下名不闻。","無人爲开口，君子独有言。","身爲苦寒士，一笑亦感恩。","慇懃中途上，勿使车無輪。"]', '诗', 'shi', '', NULL, '城南野居寄知己 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab43e7f-3842-49bf-8592-7b75963a6d37', '古莫買妾行', '古莫買妾行', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["千扉不當路，未似開一門。","若遣綠珠醜，石家應尚存。"]', '["千扉不當路，未似开一门。","若遣綠珠醜，石家應尚存。"]', '诗', 'shi', '', NULL, '古莫買妾行 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3e0c3b-f55b-41c7-b443-700e9822c07e', '霽後作', '霽後作', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["新霽辨草木，晚塘明衣衿。","乳燕不歸宿，雙雙飛向林。","微照露花影，輕雲浮麥陰。","無人可招隱，盡日登山吟。"]', '["新霽辨草木，晚塘明衣衿。","乳燕不归宿，雙雙飞向林。","微照露花影，轻云浮麦陰。","無人可招隐，尽日登山吟。"]', '诗', 'shi', '', NULL, '霽後作 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d9b7e4-9dd5-403f-8e83-79726a10b48a', '田家効陶', '田家効陶', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["黑黍舂來釀酒飲，青禾刈了驅牛載。","大姑小叔常在眼，却笑長安在天外。"]', '["黑黍舂来釀酒饮，青禾刈了驱牛載。","大姑小叔常在眼，却笑长安在天外。"]', '诗', 'shi', '', NULL, '田家効陶 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1ed4f9-2be3-42fe-8437-5dc19c364b1c', '寄賈馳先輩', '寄賈驰先輩', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["游子想萬里，何必登高臺。","聞君燕女吟，如自薊北來。","長安高蓋多，健馬東西街。","盡說蒿簪古，將錢買金釵。","我祖西園事，言之獨傷懷。","如今數君子，如鳥無樹棲。","濟水一入河，便與清流乖。","聞君欲自持，勿使吾道低。"]', '["游子想万里，何必登高台。","闻君燕女吟，如自薊北来。","长安高蓋多，健马东西街。","尽说蒿簪古，將錢買金釵。","我祖西园事，言之独傷懷。","如今數君子，如鸟無樹棲。","濟水一入河，便與清流乖。","闻君欲自持，勿使吾道低。"]', '诗', 'shi', '', NULL, '寄賈馳先輩 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d334072-026f-4e51-94ee-547266ce3559', '送友人入塞', '送友人入塞', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["亂蓬無根日，送子入青塞。","蒼茫萬里秋，如見原野大。","鳥雀寒不下，山川迥相對。","一馬沒黃雲，登高望猶在。","驚風忽然起，白日黯已晦。","如何怨路長，出門天涯外。"]', '["亂蓬無根日，送子入青塞。","蒼茫万里秋，如见原野大。","鸟雀寒不下，山川迥相对。","一马沒黄云，登高望猶在。","驚风忽然起，白日黯已晦。","如何怨路长，出门天涯外。"]', '诗', 'shi', '', NULL, '送友人入塞 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0910ea0-295f-4444-9ce5-e12893ccd785', '寄陽朔友人', '寄陽朔友人', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["桂林須產千株桂，未解當天影日開。","我到月中收得種，爲君移向故園栽。"]', '["桂林須產千株桂，未解當天影日开。","我到月中收得種，爲君移向故园栽。"]', '诗', 'shi', '', NULL, '寄陽朔友人 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f703808-03cc-4233-b67f-abd51a6e5856', '題廣福巖', '題廣福巖', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["未有天地先融結，方廣高深無丈尺。","書言不盡畫難成，留與人間作奇特。"]', '["未有天地先融結，方廣高深無丈尺。","书言不尽畫难成，留與人间作奇特。"]', '诗', 'shi', '', NULL, '題廣福巖 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d8bd9e-e6f4-4b5d-9de7-80f393387e6c', '送曾德邁歸寧宜春', '送曾德邁归寧宜春', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["湘東山水有清輝，袁水詞人得意歸。","幾府爭馳毛義檄，一鄉看侍老萊衣。","筵開灞岸臨清淺，路去藍關入翠微。","想到宜陽更無事，併將歡慶奉庭闈。"]', '["湘东山水有清輝，袁水词人得意归。","幾府爭驰毛義檄，一乡看侍老萊衣。","筵开灞岸臨清淺，路去藍关入翠微。","想到宜陽更無事，併將歡慶奉庭闈。"]', '诗', 'shi', '', NULL, '送曾德邁歸寧宜春 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05969c54-0adb-46cd-a50e-77903fee841f', '送鄭谷歸宜春', '送鄭谷归宜春', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["無成歸故國，上馬亦高歌。","況是飛鳴後，殊爲喜慶多。","暑銷嵩嶽雨，涼吹洞庭波。","莫便閑吟去，須期接盛科。"]', '["無成归故国，上马亦高歌。","況是飞鳴後，殊爲喜慶多。","暑銷嵩嶽雨，涼吹洞庭波。","莫便闲吟去，須期接盛科。"]', '诗', 'shi', '', NULL, '送鄭谷歸宜春 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('165592d9-132a-4e3d-a2f2-7648bc4912a5', '老圃堂', '老圃堂', 'f6b51c59-f2f3-47f8-8d5b-38e48745f7ff', '唐', '["邵平瓜地接吾廬，穀雨乾時手自鋤。","昨日春風欺不在，就牀吹落讀殘書。"]', '["邵平瓜地接吾廬，穀雨乾时手自鋤。","昨日春风欺不在，就牀吹落读殘书。"]', '诗', 'shi', '', NULL, '老圃堂 曹鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c00b92-63f5-4b63-82d3-1c1593120bf0', '登蕪城', '登蕪城', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["昔人登此地，丘壠已前悲。","今日又非昔，春風能幾時。"]', '["昔人登此地，丘壠已前悲。","今日又非昔，春风能幾时。"]', '诗', 'shi', '', NULL, '登蕪城 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d4cee5-6784-4c85-80fe-c44b706c3c8d', '滄浪峽', '滄浪峽', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["滄浪臨古道，道上石成塵。","自有滄浪峽，誰爲無事人。"]', '["滄浪臨古道，道上石成塵。","自有滄浪峽，誰爲無事人。"]', '诗', 'shi', '', NULL, '滄浪峽 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f38ff230-45c0-4eb7-b7dc-32ca0c7595c9', '垓城', '垓城', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["百戰未言非，孤軍驚夜圍。","山河意氣盡，淚濕美人衣。"]', '["百戰未言非，孤軍驚夜圍。","山河意氣尽，泪濕美人衣。"]', '诗', 'shi', '', NULL, '垓城 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff4bb671-6a7e-45ac-b70b-7f529a5e340e', '南陂遠望', '南陂远望', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["閑門橫古塘，紅樹已驚霜。","獨立望秋草，野人耕夕陽。","孤煙起蝸舍，飛鷺下漁梁。","唯有田家事，依依似故鄉。"]', '["闲门橫古塘，紅樹已驚霜。","独立望秋草，野人耕夕陽。","孤煙起蝸舍，飞鷺下漁梁。","唯有田家事，依依似故乡。"]', '诗', 'shi', '', NULL, '南陂遠望 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a318c56a-bb7b-413a-93b1-c8fa74e0a44d', '宿玉簫宮', '宿玉簫宮', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["塵飛不到空，露濕翠微宮。","鶴影石橋月，簫聲松殿風。","綠毛辭世女，白髮入壺翁。","借問燒丹處，桃花幾遍紅。"]', '["塵飞不到空，露濕翠微宮。","鹤影石橋月，簫声松殿风。","綠毛辞世女，白髮入壺翁。","借问燒丹处，桃花幾遍紅。"]', '诗', 'shi', '', NULL, '宿玉簫宮 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff0b746f-956d-4839-b04f-6692143dab99', '晚眺徐州延福寺', '晚眺徐州延福寺', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["杉風振旅塵，晚景籍芳茵。","片水明在野，萬花深見人。","靜依歸鶴思，遠惜舊山春。","今日惜攜手，寄懷吟白蘋。"]', '["杉风振旅塵，晚景籍芳茵。","片水明在野，万花深见人。","静依归鹤思，远惜旧山春。","今日惜携手，寄懷吟白蘋。"]', '诗', 'shi', '', NULL, '晚眺徐州延福寺 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51691ff6-b2b0-41f3-a438-1ed553c05963', '宿甘棠館', '宿甘棠館', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["塵跡入門盡，悄然江海心。","水聲巫峽遠，山色洞庭深。","風桂落寒子，嵐煙凝夕陰。","前軒鶴歸處，蘿月思沈沈。"]', '["塵跡入门尽，悄然江海心。","水声巫峽远，山色洞庭深。","风桂落寒子，嵐煙凝夕陰。","前軒鹤归处，蘿月思沈沈。"]', '诗', 'shi', '', NULL, '宿甘棠館 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee654cb-7831-4f83-bac6-7b9df8a1e4ae', '和茅山高拾遺憶山中雜題五首 山泉', '和茅山高拾遺憶山中杂題五首 山泉', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["香味清機仙府回，縈紆亂石便流桮。","春風莫泛桃花去，恐引凡人入洞來。"]', '["香味清機仙府回，縈紆亂石便流桮。","春风莫泛桃花去，恐引凡人入洞来。"]', '诗', 'shi', '', NULL, '和茅山高拾遺憶山中雜題五首 山泉 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af37e371-bdf1-4ce9-8a11-8a3a5dbc9ad5', '和茅山高拾遺憶山中雜題五首 巢鶴', '和茅山高拾遺憶山中杂題五首 巢鹤', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["千萬雲間丁令威，殷勤仙骨莫先飛。","若逢茅氏傳消息，貞白先生不久歸。"]', '["千万云间丁令威，殷勤仙骨莫先飞。","若逢茅氏傳消息，貞白先生不久归。"]', '诗', 'shi', '', NULL, '和茅山高拾遺憶山中雜題五首 巢鶴 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6772214c-f5e9-490d-b036-995940eaf5aa', '和茅山高拾遺憶山中雜題五首 胡山', '和茅山高拾遺憶山中杂題五首 胡山', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["犬入五雲音信絕，鳳樓凝碧悄無聲。","焚香古洞步虛夜，露濕松花空月明。"]', '["犬入五云音信絕，鳳楼凝碧悄無声。","焚香古洞步虛夜，露濕松花空月明。"]', '诗', 'shi', '', NULL, '和茅山高拾遺憶山中雜題五首 胡山 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf35a29-fa16-42e8-b003-eeb90a810059', '和茅山高拾遺憶山中雜題五首 小樓', '和茅山高拾遺憶山中杂題五首 小楼', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["松杉風外亂山青，曲几焚香對石屏。","空憶去年春雨後，燕泥時污太玄經。"]', '["松杉风外亂山青，曲几焚香对石屏。","空憶去年春雨後，燕泥时污太玄經。"]', '诗', 'shi', '', NULL, '和茅山高拾遺憶山中雜題五首 小樓 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67021893-3b84-49c4-aab6-a1b4c385abc8', '和茅山高拾遺憶山中雜題五首 山鄰', '和茅山高拾遺憶山中杂題五首 山鄰', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["石橋春澗已歸遲，夢入仙山山不知。","柱史從來非俗吏，青牛道士莫相疑。"]', '["石橋春澗已归遲，梦入仙山山不知。","柱史從来非俗吏，青牛道士莫相疑。"]', '诗', 'shi', '', NULL, '和茅山高拾遺憶山中雜題五首 山鄰 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad155069-4162-4677-8719-bb1185d00fce', '送道士', '送道士', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["泠然御風客，與道自浮沈。","黃鶴有歸語，白雲無忌心。","藥爐經月淨，天路入壺深。"]', '["泠然御风客，與道自浮沈。","黄鹤有归語，白云無忌心。","藥爐經月淨，天路入壺深。"]', '诗', 'shi', '', NULL, '送道士 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732a95b0-510c-413f-a9ac-9114fad2c7e4', '宿山館', '宿山館', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["寂寞對衰草，地涼凝露華。","蟬鳴月中樹，風落客前花。","山館無宿伴，秋琴初別家。","自憐千萬里，筆硯寄生涯。"]', '["寂寞对衰草，地涼凝露华。","蟬鳴月中樹，风落客前花。","山館無宿伴，秋琴初別家。","自怜千万里，笔硯寄生涯。"]', '诗', 'shi', '', NULL, '宿山館 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('764f8d40-8232-4f03-a23e-4eb1162d9c9b', '入浮石山', '入浮石山', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["斜日出門去，殘花已過春。","鳥聲穿葉遠，虎跡渡溪新。","入洞幾時路，耕田何代人。","自慙非避俗，不敢問迷津。"]', '["斜日出门去，殘花已過春。","鸟声穿葉远，虎跡渡溪新。","入洞幾时路，耕田何代人。","自慙非避俗，不敢问迷津。"]', '诗', 'shi', '', NULL, '入浮石山 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('428a56ca-f04a-4362-a970-d68d59665a5b', '送人歸故園', '送人归故园', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["遠節慘言別，況予心久違。","從來憶家淚，今日送君歸。","野路正風雪，還鄉猶布衣。","里中耕稼者，應笑讀書非。"]', '["远節慘言別，況予心久違。","從来憶家泪，今日送君归。","野路正风雪，還乡猶布衣。","里中耕稼者，應笑读书非。"]', '诗', 'shi', '', NULL, '送人歸故園 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0d55f12-3584-4d12-b363-f13377b3344f', '得越中書', '得越中书', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["芳草離離思，悠悠春夢餘。","池亭千里月，煙水一封書。","詩想懷康樂，文應弔子胥。","扁舟戀南越，豈獨爲鱸魚。"]', '["芳草離離思，悠悠春梦餘。","池亭千里月，煙水一封书。","诗想懷康乐，文應弔子胥。","扁舟戀南越，豈独爲鱸鱼。"]', '诗', 'shi', '', NULL, '得越中書 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5d43c3e-dc53-4e87-9ea8-4d88b58c1cae', '秋墅', '秋墅', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["欲暮候樵者，望山空翠微。","虹隨餘雨散，鵶帶夕陽歸。","窮巷長秋草，孤村時擣衣。","誰知多病客，寂寞掩柴扉。"]', '["欲暮候樵者，望山空翠微。","虹隨餘雨散，鵶带夕陽归。","窮巷长秋草，孤村时擣衣。","誰知多病客，寂寞掩柴扉。"]', '诗', 'shi', '', NULL, '秋墅 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46355098-8657-4f78-9520-e647414a9b6a', '哭彭先生', '哭彭先生', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["谷口溪聲客自傷，那堪嗚咽弔殘陽。","空階鶴戀丹青影，秋雨苔封白石牀。","主祭孤兒初學語，無媒旅櫬未還鄉。","門人遠赴心喪夜，月滿千山舊草堂。"]', '["谷口溪声客自傷，那堪嗚咽弔殘陽。","空階鹤戀丹青影，秋雨苔封白石牀。","主祭孤兒初学語，無媒旅櫬未還乡。","门人远赴心喪夜，月满千山旧草堂。"]', '诗', 'shi', '', NULL, '哭彭先生 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6578c29d-0080-4b10-ba30-1dbb2f3fe55a', '和顧非熊先生題茅山處士閑居', '和顧非熊先生題茅山处士闲居', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["歸耕地肺絕塵喧，匣裏青萍未報恩。","濁酒自憐終日醉，古風時得野人言。","鳥啼碧樹閑臨水，花滿青山靜掩門。","唯有階前芳草色，年年惆悵憶王孫。"]', '["归耕地肺絕塵喧，匣裏青萍未報恩。","濁酒自怜終日醉，古风时得野人言。","鸟啼碧樹闲臨水，花满青山静掩门。","唯有階前芳草色，年年惆悵憶王孫。"]', '诗', 'shi', '', NULL, '和顧非熊先生題茅山處士閑居 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1ca25e-b18e-4463-b5ec-bc5f9c90c779', '長安懷古', '长安懷古', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["禍稔蕭牆終不知，生人力屈盡邊陲。","赤龍已赴東方暗，黃犬徒懷上蔡悲。","面缺崩城山寂寂，土埋冤骨草離離。","秋風解怨扶蘇死，露泣煙愁紅樹枝。"]', '["禍稔蕭牆終不知，生人力屈尽邊陲。","赤龙已赴东方暗，黄犬徒懷上蔡悲。","面缺崩城山寂寂，土埋冤骨草離離。","秋风解怨扶蘇死，露泣煙愁紅樹枝。"]', '诗', 'shi', '', NULL, '長安懷古 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f43ccde-077b-4649-9885-5de654e2ba99', '過王右丞書堂二首 一', '過王右丞书堂二首 一', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["澄潭昔臥龍，章句世爲宗。","獨步聲名在，千巖水石空。","野禽悲灌木，落日弔清風。","後學攀遺址，秋山聞草蟲。"]', '["澄潭昔臥龙，章句世爲宗。","独步声名在，千巖水石空。","野禽悲灌木，落日弔清风。","後学攀遺址，秋山闻草蟲。"]', '诗', 'shi', '', NULL, '過王右丞書堂二首 一 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e523309-797b-47ff-9912-177983673fb5', '過王右丞書堂二首 二', '過王右丞书堂二首 二', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["萬樹影參差，石牀藤半垂。","螢光雖散草，鳥跡尚臨池。","風雅傳今日，雲山想昔時。","感深蘇屬國，千載五言詩。"]', '["万樹影參差，石牀藤半垂。","螢光雖散草，鸟跡尚臨池。","风雅傳今日，云山想昔时。","感深蘇屬国，千載五言诗。"]', '诗', 'shi', '', NULL, '過王右丞書堂二首 二 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41c8c12-4c7f-42d9-b745-b6510fd08826', '孤鴈', '孤鴈', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["孤鴈暮飛急，蕭蕭天地秋。","關河正黃葉，消息斷青樓。","湘渚煙波遠，驪山風雨愁。","此時萬里道，魂夢遶滄洲。"]', '["孤鴈暮飞急，蕭蕭天地秋。","关河正黄葉，消息斷青楼。","湘渚煙波远，驪山风雨愁。","此时万里道，魂梦遶滄洲。"]', '诗', 'shi', '', NULL, '孤鴈 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3044df48-9157-42e3-ba26-22b173c89d65', '贈隱者', '贈隐者', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["盡室居幽谷，亂山爲四鄰。","霧深知有術，窗靜似無人。","鶴語松上月，花明雲裏春。","生涯更何許，尊酒與垂綸。"]', '["尽室居幽谷，亂山爲四鄰。","霧深知有術，窗静似無人。","鹤語松上月，花明云裏春。","生涯更何許，尊酒與垂綸。"]', '诗', 'shi', '', NULL, '贈隱者 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9aa0413-27a1-47de-bc93-aabf3655165c', '早春懷薛公裕', '早春懷薛公裕', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["幽獨自成愚，柴門日漸蕪。","陸機初入洛，孫楚又遊吳。","失意怨楊柳，異鄉聞鷓鴣。","相思復相望，春草滿南湖。"]', '["幽独自成愚，柴门日漸蕪。","陸機初入洛，孫楚又游吳。","失意怨楊柳，異乡闻鷓鴣。","相思复相望，春草满南湖。"]', '诗', 'shi', '', NULL, '早春懷薛公裕 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54badba5-d4ae-4421-a311-520951f1a6de', '村月', '村月', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["月午籬南道，前村半隱林。","田翁獨歸處，蕎麥露花深。"]', '["月午籬南道，前村半隐林。","田翁独归处，蕎麦露花深。"]', '诗', 'shi', '', NULL, '村月 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e18e103-c4b3-4ef3-babe-ab3b98182945', '早春', '早春', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["野樹花初發，空山獨見時。","踟躕歷陽道，鄉思滿南枝。"]', '["野樹花初發，空山独见时。","踟躕歷陽道，乡思满南枝。"]', '诗', 'shi', '', NULL, '早春 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7bfdeee-d96a-4d85-b80f-d3f847e9d312', '送友人遊吳', '送友人游吳', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["吳山青楚吟，草色異鄉心。","一酌水邊酒，數聲花下琴。","登樓舊國遠，探穴九疑深。","更想逢秋節，那堪聞夜砧。"]', '["吳山青楚吟，草色異乡心。","一酌水邊酒，數声花下琴。","登楼旧国远，探穴九疑深。","更想逢秋節，那堪闻夜砧。"]', '诗', 'shi', '', NULL, '送友人遊吳 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210de100-1572-4311-a05a-e1e58d9115fa', '贈別', '贈別', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["蘭澤傷秋色，臨風遠別期。","東城草雖綠，南浦柳無枝。","直道豈易枉，暗投誰不疑。","因君問行役，有淚濕江蘺。"]', '["蘭澤傷秋色，臨风远別期。","东城草雖綠，南浦柳無枝。","直道豈易枉，暗投誰不疑。","因君问行役，有泪濕江蘺。"]', '诗', 'shi', '', NULL, '贈別 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d4413c-87b8-4b03-9aa5-cae1db62356d', '經故人舊居', '經故人旧居', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["萬里訪遺塵，鶯聲淚濕巾。","古書無主散，廢宅與山鄰。","宿草風悲夜，荒村月弔人。","淒涼問殘柳，今日爲誰春。"]', '["万里訪遺塵，鶯声泪濕巾。","古书無主散，廢宅與山鄰。","宿草风悲夜，荒村月弔人。","淒涼问殘柳，今日爲誰春。"]', '诗', 'shi', '', NULL, '經故人舊居 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb03ecdc-7906-496d-8ce1-145e70d52627', '隨邊使過五原', '隨邊使過五原', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["偶逐星車犯虜塵，故鄉常恐到無因。","五原西去陽關廢，日漫平沙不見人。"]', '["偶逐星车犯虜塵，故乡常恐到無因。","五原西去陽关廢，日漫平沙不见人。"]', '诗', 'shi', '', NULL, '隨邊使過五原 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('387175f8-82d3-4590-ba08-86d56440f020', '春懷寄秣陵知友', '春懷寄秣陵知友', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["廬江城外柳堪攀，萬里行人尚未還。","借問景陽臺下客，謝家誰更臥東山。"]', '["廬江城外柳堪攀，万里行人尚未還。","借问景陽台下客，謝家誰更臥东山。"]', '诗', 'shi', '', NULL, '春懷寄秣陵知友 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e7991b-66c5-4c5d-8a80-03991b22b337', '宋州月夜感懷', '宋州月夜感懷', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["鴈池衰草露霑衣，河水東流萬事微。","寂寞青陵臺上月，秋風滿樹鵲南飛。"]', '["鴈池衰草露霑衣，河水东流万事微。","寂寞青陵台上月，秋风满樹鵲南飞。"]', '诗', 'shi', '', NULL, '宋州月夜感懷 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfe4266e-2a85-4118-bb52-d4ffb5734b64', '吳宮', '吳宮', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["荒臺荆棘多，忠諫竟如何。","細草迷宮巷，閑花悞綺羅。","前溪徒自綠，子夜不聞歌。","悵望清江暮，悠悠東去波。"]', '["荒台荆棘多，忠諫竟如何。","細草迷宮巷，闲花悞綺羅。","前溪徒自綠，子夜不闻歌。","悵望清江暮，悠悠东去波。"]', '诗', 'shi', '', NULL, '吳宮 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05d5900-1103-49c8-99e2-52a7cb8d64f6', '春遊望仙谷', '春游望仙谷', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["清無車馬塵，深洞百花春。","雞犬疑霑藥，耕桑似避秦。","登山採樵路，臨水浣紗人。","若得心無事，移家便卜鄰。"]', '["清無车马塵，深洞百花春。","雞犬疑霑藥，耕桑似避秦。","登山採樵路，臨水浣紗人。","若得心無事，移家便卜鄰。"]', '诗', 'shi', '', NULL, '春遊望仙谷 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc03cca9-a731-446d-86fb-e3f29c2a59e7', '聖女祠', '聖女祠', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["石屏苔色涼，流水遶祠堂。","巢鵲疑天漢，潭花似鏡妝。","神來雲雨合，神去蕙蘭香。","不復聞雙佩，山門空夕陽。"]', '["石屏苔色涼，流水遶祠堂。","巢鵲疑天漢，潭花似镜妝。","神来云雨合，神去蕙蘭香。","不复闻雙佩，山门空夕陽。"]', '诗', 'shi', '', NULL, '聖女祠 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f211bfd-f0d2-4856-9c22-6ae0da212fb8', '宿范水', '宿范水', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["行人倦遊宦，秋草宿湖邊。","露濕芙蓉渡，月明漁網船。","寒機深竹裏，遠浪到門前。","何處思鄉甚，歌聲聞採蓮。"]', '["行人倦游宦，秋草宿湖邊。","露濕芙蓉渡，月明漁網船。","寒機深竹裏，远浪到门前。","何处思乡甚，歌声闻採蓮。"]', '诗', 'shi', '', NULL, '宿范水 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ff9d653-e25b-4768-bf03-272309414280', '送顧陶校書歸錢塘', '送顧陶校书归錢塘', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["清苦月偏知，南歸瘦馬遲。","橐輕緣換酒，髪白爲吟詩。","水色西陵渡，松聲伍相祠。","聖朝思直諫，不是挂冠時。"]', '["清苦月偏知，南归瘦马遲。","橐轻緣換酒，髪白爲吟诗。","水色西陵渡，松声伍相祠。","聖朝思直諫，不是挂冠时。"]', '诗', 'shi', '', NULL, '送顧陶校書歸錢塘 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aace010-a5b3-4fad-8335-bf2d350b954c', '題雲陽高少府衙齋', '題云陽高少府衙斋', 'd151f319-946c-45db-94db-e8a20871a1f8', '唐', '["大隱能兼濟，軒窗逐勝開。","遠含雲水思，深得棟梁材。","吏散山逾靜，庭閑鳥自來。","更憐幽砌色，秋雨長莓苔。"]', '["大隐能兼濟，軒窗逐勝开。","远含云水思，深得棟梁材。","吏散山逾静，庭闲鸟自来。","更怜幽砌色，秋雨长莓苔。"]', '诗', 'shi', '', NULL, '題雲陽高少府衙齋 儲嗣宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c66bf95-23a4-413d-93c7-e513af0f8356', '早春山行', '早春山行', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["江草暖初綠，雁行皆北飛。","異鄉那久客，野鳥尚思歸。","十載過如夢，素心應已違。","行行家漸遠，更苦得書稀。"]', '["江草暖初綠，雁行皆北飞。","異乡那久客，野鸟尚思归。","十載過如梦，素心應已違。","行行家漸远，更苦得书稀。"]', '诗', 'shi', '', NULL, '早春山行 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e97a7ac-d782-4b1a-be5d-19f4e7254885', '宿友生林居因懷賈區', '宿友生林居因懷賈區', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["繞屋樹森森，多棲紫閣禽。","暫過當永夜，微得話前心。","入楚行應遠，經湘恨必深。","那堪對寒燭，更賦別離吟。"]', '["繞屋樹森森，多棲紫閣禽。","暫過當永夜，微得話前心。","入楚行應远，經湘恨必深。","那堪对寒燭，更賦別離吟。"]', '诗', 'shi', '', NULL, '宿友生林居因懷賈區 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77500d86-66f5-4c69-9a16-a6c015ff1316', '贈賣松人', '贈賣松人', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["入市雖求利，憐君意獨真。","劚將寒澗樹，賣與翠樓人。","瘦葉幾經雪，淡花應少春。","長安重桃李，徒染六街塵。"]', '["入市雖求利，怜君意独真。","劚將寒澗樹，賣與翠楼人。","瘦葉幾經雪，淡花應少春。","长安重桃李，徒染六街塵。"]', '诗', 'shi', '', NULL, '贈賣松人 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1ba79b-15a6-4918-b802-5a850339f895', '友人南遊不回因而有寄', '友人南游不回因而有寄', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["相思春樹綠，千里亦依依。","鄠杜月頻滿，瀟湘人未歸。","桂花風半落，煙草蝶雙飛。","一別無消息，水南車跡稀。"]', '["相思春樹綠，千里亦依依。","鄠杜月頻满，瀟湘人未归。","桂花风半落，煙草蝶雙飞。","一別無消息，水南车跡稀。"]', '诗', 'shi', '', NULL, '友人南遊不回因而有寄 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('993d3680-c8df-4d06-951f-d9ac0b1b0fd6', '送酇縣董明府之任', '送酇縣董明府之任', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["南北行已久，憐君知苦辛。","萬家同草木，三載得陽春。","東道聽遊子，夷門歌主人。","空持語相送，應怪不沾巾。"]', '["南北行已久，怜君知苦辛。","万家同草木，三載得陽春。","东道听游子，夷门歌主人。","空持語相送，應怪不沾巾。"]', '诗', 'shi', '', NULL, '送酇縣董明府之任 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b2dd1e-6064-4bec-a82c-e676358bca13', '山上樹', '山上樹', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["日暖上山路，鳥啼知已春。","忽逢幽隱處，如見獨醒人。","石冷開常晚，風多落亦頻。","樵夫應不識，歲久伐爲薪。"]', '["日暖上山路，鸟啼知已春。","忽逢幽隐处，如见独醒人。","石冷开常晚，风多落亦頻。","樵夫應不識，歲久伐爲薪。"]', '诗', 'shi', '', NULL, '山上樹 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e17e65-563a-444a-8425-585b85c1a690', '長信宮二首 一', '长信宮二首 一', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["簟涼秋氣初，長信恨何如。","拂黛月生指，解鬟雲滿梳。","一從悲畫扇，幾度泣前魚。","坐聽南宮樂，涼風搖翠裾。"]', '["簟涼秋氣初，长信恨何如。","拂黛月生指，解鬟云满梳。","一從悲畫扇，幾度泣前鱼。","坐听南宮乐，涼风搖翠裾。"]', '诗', 'shi', '', NULL, '長信宮二首 一 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17ac577-70aa-4c87-a92e-33449e28e2e4', '長信宮二首 二', '长信宮二首 二', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["一失輦前恩，綺羅生暗塵。","惟應深夜月，獨伴向隅人。","長信翠蛾老，昭陽紅粉新。","君心似秋節，不使草長春。"]', '["一失輦前恩，綺羅生暗塵。","惟應深夜月，独伴向隅人。","长信翠蛾老，昭陽紅粉新。","君心似秋節，不使草长春。"]', '诗', 'shi', '', NULL, '長信宮二首 二 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e55b522-700b-450a-b06b-2a0154760960', '洛陽道', '洛陽道', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["浮世若浮雲，千回故復新。","旋添青草塚，更有白頭人。","歲暮容將老，雪晴山欲春。","行行車與馬，不盡洛陽[塵]。"]', '["浮世若浮云，千回故复新。","旋添青草塚，更有白头人。","歲暮容將老，雪晴山欲春。","行行车與马，不尽洛陽[塵]。"]', '诗', 'shi', '', NULL, '洛陽道 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87313651-f5ef-4a96-b735-33e041492482', '東門路', '东门路', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["東門車馬路，此路在浮沈。","白日若不落，紅塵應更深。","從來名利地，皆起是非心。","所以青青草，年年生漢陰。"]', '["东门车马路，此路在浮沈。","白日若不落，紅塵應更深。","從来名利地，皆起是非心。","所以青青草，年年生漢陰。"]', '诗', 'shi', '', NULL, '東門路 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c210115-e684-45e9-a22a-03134280ab2a', '江樓春望', '江楼春望', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["樓下長江路，舟車晝不閑。","鳥聲非故國，春色是他山。","一望雲復水，幾重河與關。","愁心隨落日，萬里各西還。"]', '["楼下长江路，舟车晝不闲。","鸟声非故国，春色是他山。","一望云复水，幾重河與关。","愁心隨落日，万里各西還。"]', '诗', 'shi', '', NULL, '江樓春望 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062843e1-5ecb-4cd6-a345-5c3df2c723bc', '洛中晴望', '洛中晴望', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["九陌盡風塵，囂囂晝復昏。","古今人不斷，南北路長存。","葉落上陽樹，草衰金谷園。","亂鴉歸未已，殘日半前軒。"]', '["九陌尽风塵，囂囂晝复昏。","古今人不斷，南北路长存。","葉落上陽樹，草衰金谷园。","亂鴉归未已，殘日半前軒。"]', '诗', 'shi', '', NULL, '洛中晴望 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af61ba07-a8a5-4490-8690-92885211bf8b', '西歸', '西归', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["不繫與舟閑，悠悠吳楚間。","羞將新白髮，却到舊青山。","一葉忽離樹，幾人同入關。","長安家尚在，秋至又西還。"]', '["不繫與舟闲，悠悠吳楚间。","羞將新白髮，却到旧青山。","一葉忽離樹，幾人同入关。","长安家尚在，秋至又西還。"]', '诗', 'shi', '', NULL, '西歸 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e631c0c-f828-4741-b846-03a43846dbb1', '南遊', '南游', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["窮秋幾日雨，處處生蒼苔。","舊國寄書後，涼天方雁來。","露繁山草濕，洲暖水花開。","去盡同行客，一帆猶未回。"]', '["窮秋幾日雨，处处生蒼苔。","旧国寄书後，涼天方雁来。","露繁山草濕，洲暖水花开。","去尽同行客，一帆猶未回。"]', '诗', 'shi', '', NULL, '南遊 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f61b869-0092-48ac-9666-788a5efd4062', '南遊有感', '南游有感', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["杜陵無厚業，不得駐車輪。","重到曾遊處，多非舊主人。","東風千嶺樹，西日一洲蘋。","又渡湘江去，湘江水復春。"]', '["杜陵無厚業，不得駐车輪。","重到曾游处，多非旧主人。","东风千嶺樹，西日一洲蘋。","又渡湘江去，湘江水复春。"]', '诗', 'shi', '', NULL, '南遊有感 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56ad06f-0556-40c9-a32b-cdd4cc2536c8', '夜泊湘江', '夜泊湘江', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["北風吹楚樹，此地獨先秋。","何事屈原恨，不隨湘水流。","涼天生片月，竟夕伴孤舟。","一作南行客，無成空白頭。"]', '["北风吹楚樹，此地独先秋。","何事屈原恨，不隨湘水流。","涼天生片月，竟夕伴孤舟。","一作南行客，無成空白头。"]', '诗', 'shi', '', NULL, '夜泊湘江 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4063941-d6b5-44fa-8314-8d21ce7c72f6', '客中', '客中', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["楚人歌竹枝，遊子淚沾衣。","異國久爲客，寒宵頻夢歸。","一封書未返，千樹葉皆飛。","南過洞庭水，更應消息稀。"]', '["楚人歌竹枝，游子泪沾衣。","異国久爲客，寒宵頻梦归。","一封书未返，千樹葉皆飞。","南過洞庭水，更應消息稀。"]', '诗', 'shi', '', NULL, '客中 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05550026-ed07-485f-8d78-30ff5efe139f', '夜尋僧不遇', '夜尋僧不遇', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["數歇度煙水，漸非塵俗間。","泉聲入秋寺，月色遍寒山。","石路幾回雪，竹房猶閉關。"]', '["數歇度煙水，漸非塵俗间。","泉声入秋寺，月色遍寒山。","石路幾回雪，竹房猶閉关。"]', '诗', 'shi', '', NULL, '夜尋僧不遇 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('377085fe-7f0d-4d15-a2bb-b549953c8756', '訪道者不遇', '訪道者不遇', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["人間惟此路，長得綠苔衣。","及戶無行跡，遊方應未歸。","平生無限事，到此盡知非。","獨倚松門久，陰雲昏翠微。"]', '["人间惟此路，长得綠苔衣。","及戶無行跡，游方應未归。","平生無限事，到此尽知非。","独倚松门久，陰云昏翠微。"]', '诗', 'shi', '', NULL, '訪道者不遇 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c77b72bd-fa5f-4cd2-a246-8a7f917a538e', '贈王隱者山居', '贈王隐者山居', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["石室掃無塵，人寰與此分。","飛來南浦樹，半是華山雲。","浮世幾多事，先生應不聞。","寒山滿西日，空照雁成羣。"]', '["石室掃無塵，人寰與此分。","飞来南浦樹，半是华山云。","浮世幾多事，先生應不闻。","寒山满西日，空照雁成羣。"]', '诗', 'shi', '', NULL, '贈王隱者山居 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64865458-b209-4602-903b-368e33557c97', '寄北客', '寄北客', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["窮邊足風慘，何處醉樓臺？","家去幾千里，月圓十二回。","寒阡隨日遠，雪路向城開。","遊子久無信，年年空雁來。"]', '["窮邊足风慘，何处醉楼台？","家去幾千里，月圓十二回。","寒阡隨日远，雪路向城开。","游子久無信，年年空雁来。"]', '诗', 'shi', '', NULL, '寄北客 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('787ee6f3-1a8b-4819-beee-66cbd3d4dda6', '寄友人', '寄友人', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["長安清渭東，遊子跡重重。","此去紅塵路，難尋君馬蹤。","昔時輕一別，漸老貴相逢。","應戀嵩陽住，嵩陽饒古松。"]', '["长安清渭东，游子跡重重。","此去紅塵路，难尋君马蹤。","昔时轻一別，漸老貴相逢。","應戀嵩陽住，嵩陽饒古松。"]', '诗', 'shi', '', NULL, '寄友人 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35dbf691-52f0-4794-8249-9a65a7c40ba0', '夜與故人別', '夜與故人別', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["白日去難駐，故人非舊容。","今宵一別後，何處更相逢？","過楚水千里，到秦山幾重。","語來天又曉，月落滿城鐘。"]', '["白日去难駐，故人非旧容。","今宵一別後，何处更相逢？","過楚水千里，到秦山幾重。","語来天又晓，月落满城鐘。"]', '诗', 'shi', '', NULL, '夜與故人別 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2e509b-439e-4f70-85c3-3873b6188c57', '別故人', '別故人', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["行子與秋葉，各隨南北風。","雖非千里別，還阻一宵同。","過盡少年日，尚如長轉蓬。","猶爲布衣客，羞入故關中。"]', '["行子與秋葉，各隨南北风。","雖非千里別，還阻一宵同。","過尽少年日，尚如长轉蓬。","猶爲布衣客，羞入故关中。"]', '诗', 'shi', '', NULL, '別故人 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6ae9cbf-9abc-4ddb-9eb6-dd963a0d64a0', '送客東歸', '送客东归', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["一聽遊子歌，秋計覺蹉跎。","四海少平地，百川無定波。","共驚年已暮，俱向客中多。","又駕征輪去，東歸事若何。"]', '["一听游子歌，秋計覺蹉跎。","四海少平地，百川無定波。","共驚年已暮，俱向客中多。","又駕征輪去，东归事若何。"]', '诗', 'shi', '', NULL, '送客東歸 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed30533d-9b96-409e-a24a-157b44f80a05', '過侯王故第', '過侯王故第', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["過此一酸辛，行人淚有痕。","獨殘新碧樹，猶擁舊朱門。","歌歇雲初散，簷空燕尚存。"]', '["過此一酸辛，行人泪有痕。","独殘新碧樹，猶擁旧朱门。","歌歇云初散，簷空燕尚存。"]', '诗', 'shi', '', NULL, '過侯王故第 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc9ff18-42a8-4070-942e-97b5491b8304', '孤雲', '孤云', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["南北各萬里，有雲心更閑。","因風離海上，伴月到人間。","洛浦少高樹，長安無舊山。","裴回不可駐，漠漠又空還。"]', '["南北各万里，有云心更闲。","因风離海上，伴月到人间。","洛浦少高樹，长安無旧山。","裴回不可駐，漠漠又空還。"]', '诗', 'shi', '', NULL, '孤雲 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4bc87d1-917a-49ce-b44a-774c2a772495', '遠水', '远水', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["悔作望南浦，望中生遠愁。","因知人易老，爲有水東流。","欲附故鄉信，不逢歸客舟。","萋萋兩岸草，又度一年秋。"]', '["悔作望南浦，望中生远愁。","因知人易老，爲有水东流。","欲附故乡信，不逢归客舟。","萋萋兩岸草，又度一年秋。"]', '诗', 'shi', '', NULL, '遠水 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12ab264-3bcb-4ff5-9a20-18a3539de09a', '詠蟬', '詠蟬', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["江頭一聲起，芳歲已難留。","聽此高林上，遙知故國秋。","應催風落葉，似勸客回舟。","不是新蟬苦，年年自有愁。"]', '["江头一声起，芳歲已难留。","听此高林上，遙知故国秋。","應催风落葉，似勸客回舟。","不是新蟬苦，年年自有愁。"]', '诗', 'shi', '', NULL, '詠蟬 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a9ac64-29ab-4736-ba5a-b6ef1c63709d', '感情', '感情', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["青山長寂寞，南望獨高歌。","四海故人盡，九原新壠多。","西沈浮世日，東注逝川波。","不使年華駐，此生能幾何。"]', '["青山长寂寞，南望独高歌。","四海故人尽，九原新壠多。","西沈浮世日，东注逝川波。","不使年华駐，此生能幾何。"]', '诗', 'shi', '', NULL, '感情 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f4b6aa-0b05-4e9b-bd72-3342943eaabf', '早春日山居寄城郭知己', '早春日山居寄城郭知己', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["陽和潛發蕩寒陰，便使川原景象新。","入戶風泉聲瀝瀝，當軒雲岫色沈沈。","殘雲帶雨輕飄雪，嫩柳含煙小綻金。","雖有眼前詩酒興，遨遊爭得稱閑心。"]', '["陽和潛發蕩寒陰，便使川原景象新。","入戶风泉声瀝瀝，當軒云岫色沈沈。","殘云带雨轻飄雪，嫩柳含煙小綻金。","雖有眼前诗酒兴，遨游爭得稱闲心。"]', '诗', 'shi', '', NULL, '早春日山居寄城郭知己 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76be7b9b-f0df-4352-b6fc-5476cdd9b86d', '勸酒', '勸酒', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["勸君金屈巵，滿酌不須辭。","花發多風雨，人生足別離。"]', '["勸君金屈巵，满酌不須辞。","花發多风雨，人生足別離。"]', '诗', 'shi', '', NULL, '勸酒 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f922efa-e0fb-4785-8b8e-2858871e463a', '感懷', '感懷', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["東風吹草色，空使客蹉跎。","不設太平險，更應遊子多。","幾傷行處淚，一曲醉中歌。","盡向青門外，東隨渭水波。"]', '["东风吹草色，空使客蹉跎。","不設太平險，更應游子多。","幾傷行处泪，一曲醉中歌。","尽向青门外，东隨渭水波。"]', '诗', 'shi', '', NULL, '感懷 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('341677a8-5309-4c40-876c-bd9b8ebf00b4', '友人亭松', '友人亭松', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["俛仰不能去，如逢舊友同。","曾因春雪散，見在華山中。","何處有明月，訪君聽遠風。","相將歸未得，各占石巖東。"]', '["俛仰不能去，如逢旧友同。","曾因春雪散，见在华山中。","何处有明月，訪君听远风。","相將归未得，各占石巖东。"]', '诗', 'shi', '', NULL, '友人亭松 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69c0403c-51ad-4c83-8897-3871bf6599cf', '遊中梁山', '游中梁山', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["僻地好泉石，何人曾陸沈。","不知青嶂外，更有白雲深。","因此見喬木，幾回思舊林。","慇懃猨與鳥，惟我獨何心。"]', '["僻地好泉石，何人曾陸沈。","不知青嶂外，更有白云深。","因此见喬木，幾回思旧林。","慇懃猨與鸟，惟我独何心。"]', '诗', 'shi', '', NULL, '遊中梁山 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5ecb93c-e460-4f49-ac31-981eacb358ec', '尋山', '尋山', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["到此絕車輪，萋萋草樹春。","青山如有利，白石亦成塵。","水闊應無路，松深不見人。","如知巢與許，千載跡猶新。"]', '["到此絕车輪，萋萋草樹春。","青山如有利，白石亦成塵。","水闊應無路，松深不见人。","如知巢與許，千載跡猶新。"]', '诗', 'shi', '', NULL, '尋山 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d86d3d3-2f4b-460c-9daa-901ad94d48a1', '宿江口', '宿江口', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["南渡人來絕，喧喧雁滿沙。","自生江上月，長有客思家。","半夜下霜岸，北風吹荻花。","自驚歸夢斷，不得到天涯。"]', '["南渡人来絕，喧喧雁满沙。","自生江上月，长有客思家。","半夜下霜岸，北风吹荻花。","自驚归梦斷，不得到天涯。"]', '诗', 'shi', '', NULL, '宿江口 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc95a4cf-7a62-4222-bfd2-ace824d91c46', '秋夜達蕭關', '秋夜達蕭关', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["擾擾浮梁路，人忙月自閑。","去年爲塞客，今夜宿蕭關。","辭國幾經歲，望鄉空見山。","不知江葉下，又作布衣還。"]', '["擾擾浮梁路，人忙月自闲。","去年爲塞客，今夜宿蕭关。","辞国幾經歲，望乡空见山。","不知江葉下，又作布衣還。"]', '诗', 'shi', '', NULL, '秋夜達蕭關 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('754d42b3-6014-4d86-952e-563b2ea215c3', '斜谷道', '斜谷道', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["亂峰連疊嶂，千里綠峨峨。","蜀國路如此，遊人車亦過。","遠煙當葉歛，驟雨逐風多。","獨憶紫芝叟，臨風歌舊歌。"]', '["亂峰連叠嶂，千里綠峨峨。","蜀国路如此，游人车亦過。","远煙當葉歛，驟雨逐风多。","独憶紫芝叟，臨风歌旧歌。"]', '诗', 'shi', '', NULL, '斜谷道 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c3305e2-bd75-4885-9f1b-bb8e7a6c9fc1', '過百牢關貽舟中者', '過百牢关貽舟中者', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["蜀國少平地，方思京洛間。","遠爲千里客，來度百牢關。","帆影清江水，鈴聲碧草山。","不因名與利，爾我各應閑。"]', '["蜀国少平地，方思京洛间。","远爲千里客，来度百牢关。","帆影清江水，鈴声碧草山。","不因名與利，爾我各應闲。"]', '诗', 'shi', '', NULL, '過百牢關貽舟中者 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a806a9-c7c3-4edd-abcf-884b670ca0f5', '客中覽鏡', '客中覽镜', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["何當開此鏡，即見髪如絲。","白日急於水，一年能幾時。","每逢芳草處，長返故園遲。","所以多爲客，蹉跎欲怨誰。"]', '["何當开此镜，即见髪如絲。","白日急於水，一年能幾时。","每逢芳草处，长返故园遲。","所以多爲客，蹉跎欲怨誰。"]', '诗', 'shi', '', NULL, '客中覽鏡 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4f44ad7-76e1-4cb6-a9e7-a9b696c43dfd', '長安逢隱者', '长安逢隐者', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["征車千里至，碾遍六街塵。","向此有營地，忽逢無事人。","昔時顏未改，浮世路多新。","且脫衣沽酒，終南山欲春。"]', '["征车千里至，碾遍六街塵。","向此有營地，忽逢無事人。","昔时顏未改，浮世路多新。","且脫衣沽酒，終南山欲春。"]', '诗', 'shi', '', NULL, '長安逢隱者 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cee9033-b776-47f3-a32d-376ca9a8b54a', '與僧話舊', '與僧話旧', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["草堂前有山，一見一相寬。","處世貴僧靜，青松因歲寒。","他山逢舊侶，盡日話長安。","所以閑行跡，千回遶藥欄。"]', '["草堂前有山，一见一相寬。","处世貴僧静，青松因歲寒。","他山逢旧侶，尽日話长安。","所以闲行跡，千回遶藥欄。"]', '诗', 'shi', '', NULL, '與僧話舊 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58d8017-26e6-4a1a-a02a-8134ca7179ee', '贈王道士', '贈王道士', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["日日市朝路，何時無苦辛。","不隨丹竈客，終作白頭人。","浮世度千載，桃源方一春。","歸來華表上，應笑北邙塵。"]', '["日日市朝路，何时無苦辛。","不隨丹竈客，終作白头人。","浮世度千載，桃源方一春。","归来华表上，應笑北邙塵。"]', '诗', 'shi', '', NULL, '贈王道士 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143d7943-75ea-46d3-8e19-cc66d5aee566', '匣中琴', '匣中琴', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["世人無正心，蟲網匣中琴。","何以經時廢，非爲娛耳音。","獨令高韻在，誰感隙塵深。","應是南風曲，聲聲不合今。"]', '["世人無正心，蟲網匣中琴。","何以經时廢，非爲娛耳音。","独令高韻在，誰感隙塵深。","應是南风曲，声声不合今。"]', '诗', 'shi', '', NULL, '匣中琴 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f3cfe0-e301-41c3-b900-05de34fd4775', '過洛陽城', '過洛陽城', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["古來利與名，俱在洛陽城。","九陌鼓初起，萬車輪已行。","周秦時幾變，伊洛水猶清。","二月中橋路，鳥啼春草生。"]', '["古来利與名，俱在洛陽城。","九陌鼓初起，万车輪已行。","周秦时幾变，伊洛水猶清。","二月中橋路，鸟啼春草生。"]', '诗', 'shi', '', NULL, '過洛陽城 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d95572e7-1166-419e-ad7c-3e14f75d722f', '望月', '望月', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["離家凡幾宵，一望一寥寥。","新魄又將滿，故鄉應漸遙。","獨臨彭蠡水，遠憶洛陽橋。","更有乘舟客，悽然亦駐橈。"]', '["離家凡幾宵，一望一寥寥。","新魄又將满，故乡應漸遙。","独臨彭蠡水，远憶洛陽橋。","更有乘舟客，悽然亦駐橈。"]', '诗', 'shi', '', NULL, '望月 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4abe7b-5b80-47f3-b3ef-4179383d40a1', '王將軍宅夜聽歌', '王將軍宅夜听歌', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["朱檻滿明月，美人歌落梅。","忽驚塵起處，疑有鳳飛來。","一曲聽初徹，幾年愁暫開。","東南正雲雨，不得見陽臺。"]', '["朱檻满明月，美人歌落梅。","忽驚塵起处，疑有鳳飞来。","一曲听初徹，幾年愁暫开。","东南正云雨，不得见陽台。"]', '诗', 'shi', '', NULL, '王將軍宅夜聽歌 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab3bbbd-f261-439c-b404-75bf5faec101', '長信宮', '长信宮', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["莫問古宮名，古宮空有城。","惟應東去水，不改舊時聲。"]', '["莫问古宮名，古宮空有城。","惟應东去水，不改旧时声。"]', '诗', 'shi', '', NULL, '長信宮 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9336eb1e-413b-4c58-b289-85d3bf38ec77', '高樓', '高楼', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["遠天明月出，照此誰家樓。","上有羅衣裳，涼風吹不休。"]', '["远天明月出，照此誰家楼。","上有羅衣裳，涼风吹不休。"]', '诗', 'shi', '', NULL, '高樓 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('793710bd-0fdf-40e4-a8e1-8ae10a9589a6', '感古', '感古', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["九折無停波，三光如轉燭。","玄珠人不識，徒愛燕趙玉。","祖龍已深惑，漢氏遠狥欲。","驪山與茂陵，相對秋草綠。"]', '["九折無停波，三光如轉燭。","玄珠人不識，徒愛燕趙玉。","祖龙已深惑，漢氏远狥欲。","驪山與茂陵，相对秋草綠。"]', '诗', 'shi', '', NULL, '感古 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b5f194c-1dec-411d-ac23-98e612da21c6', '贈王道士', '贈王道士', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["玉洞秋有花，蓬山夜無鬼。","豈知浮雲世，生死逐流水。","瑤臺歌一曲，曲盡五煙起。","悠然望虛路，玉京在海裏。","青籙秘不聞，黃鶴去不止。","願隨執輕策，往結周太子。"]', '["玉洞秋有花，蓬山夜無鬼。","豈知浮云世，生死逐流水。","瑤台歌一曲，曲尽五煙起。","悠然望虛路，玉京在海裏。","青籙秘不闻，黄鹤去不止。","願隨執轻策，往結周太子。"]', '诗', 'shi', '', NULL, '贈王道士 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccff72d5-b22e-4d0e-a377-492bebaa63a5', '古思', '古思', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["春華惜妾態，秋草念妾心。","始知井邊桐，不如堂上琴。","月落却羨鏡，花飛猶委苔。","門前長江水，一去終不回。"]', '["春华惜妾態，秋草念妾心。","始知井邊桐，不如堂上琴。","月落却羨镜，花飞猶委苔。","门前长江水，一去終不回。"]', '诗', 'shi', '', NULL, '古思 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a53dabd-7d2c-4ede-8b7e-de5ad4312e67', '獵客', '獵客', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["五陵射鵰客，走馬占春光。","下馬青樓前，華裾獨煌煌。","自言家咸京，世族如金張。","擊鐘傳鼎食，爾來八十強。","朱門爭先開，車輪滿路傍。","娥娥燕趙人，珠箔閉高堂。","清歌雜妙舞，臨歡度曲長。","朝遊園花新，夜宴池月涼。","更以馳驟多，意氣事[彊]梁。","君王正年少，終日在長楊。"]', '["五陵射鵰客，走马占春光。","下马青楼前，华裾独煌煌。","自言家咸京，世族如金張。","擊鐘傳鼎食，爾来八十強。","朱门爭先开，车輪满路傍。","娥娥燕趙人，珠箔閉高堂。","清歌杂妙舞，臨歡度曲长。","朝游园花新，夜宴池月涼。","更以驰驟多，意氣事[彊]梁。","君王正年少，終日在长楊。"]', '诗', 'shi', '', NULL, '獵客 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b00d447d-61e3-4e41-881a-c7d5086d5c52', '送進士苗縱歸紫邏山居', '送進士苗縱归紫邏山居', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["汝上多奇山，高懷愜清境。","強來干名地，冠帶不能整。","常言夢歸處，泉石寒更靜。","鶴聲夜無人，空月隨松影。","今朝拋我去，春物傷明景。","悵望相送還，微陽在東嶺。"]', '["汝上多奇山，高懷愜清境。","強来干名地，冠带不能整。","常言梦归处，泉石寒更静。","鹤声夜無人，空月隨松影。","今朝拋我去，春物傷明景。","悵望相送還，微陽在东嶺。"]', '诗', 'shi', '', NULL, '送進士苗縱歸紫邏山居 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9dbfb9-c242-4e05-9490-352407fe97da', '賣花者', '賣花者', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["少壯彼何人，種花荒苑外。","不知力田苦，却笑耕耘輩。","當春賣春色，來往經幾代。","長安甲第多，處處花堪愛。","良金不惜費，競取園中最。","一蕊纔占煙，歌聲已高會。","自言種花地，終日擁軒蓋。","農夫官役時，獨與花相對。","那令賣花者，久爲生人害。","貴粟不貴花，生人自應泰。"]', '["少壯彼何人，種花荒苑外。","不知力田苦，却笑耕耘輩。","當春賣春色，来往經幾代。","长安甲第多，处处花堪愛。","良金不惜費，競取园中最。","一蕊纔占煙，歌声已高會。","自言種花地，終日擁軒蓋。","農夫官役时，独與花相对。","那令賣花者，久爲生人害。","貴粟不貴花，生人自應泰。"]', '诗', 'shi', '', NULL, '賣花者 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa3344f0-808f-4513-8abf-8a49a0239f31', '彈琴', '彈琴', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["涼室無外響，空桑七弦分。","所彈非新聲，俗耳安肯聞。","月落未終曲，暗中泣湘君。","如傳我心苦，千里蒼梧雲。"]', '["涼室無外响，空桑七弦分。","所彈非新声，俗耳安肯闻。","月落未終曲，暗中泣湘君。","如傳我心苦，千里蒼梧云。"]', '诗', 'shi', '', NULL, '彈琴 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14276ab6-8a27-4943-bd15-b69ec7ea9b18', '古邊卒思歸', '古邊卒思归', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["有田不得耕，身臥遼陽城。","夢中稻花香，覺後戰血腥。","漢武在深殿，唯思廓寰瀛。","中原半烽火，此屋皆點行。","邊土無膏腴，閑地何必爭。","徒令執耒者，刀下死縱橫。"]', '["有田不得耕，身臥遼陽城。","梦中稻花香，覺後戰血腥。","漢武在深殿，唯思廓寰瀛。","中原半烽火，此屋皆点行。","邊土無膏腴，闲地何必爭。","徒令執耒者，刀下死縱橫。"]', '诗', 'shi', '', NULL, '古邊卒思歸 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07399eed-2d4e-41ae-825c-d35caadcc6f7', '美劉太保', '美劉太保', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["常愛魯仲連，退身得其趣。","不知鴟夷子，更入五湖去。","雲霞恣搖曳，鴻鵠無低翥。","萬里天地空，清飆在平楚。","藏名向寵節，辭疾去公務。","夜盡醉弦歌，日高臥煙樹。","豈嗤生前樂，千載自垂裕。","論道復論功，皆可黃金鑄。"]', '["常愛魯仲連，退身得其趣。","不知鴟夷子，更入五湖去。","云霞恣搖曳，鴻鵠無低翥。","万里天地空，清飆在平楚。","藏名向寵節，辞疾去公務。","夜尽醉弦歌，日高臥煙樹。","豈嗤生前乐，千載自垂裕。","論道复論功，皆可黄金鑄。"]', '诗', 'shi', '', NULL, '美劉太保 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('925af261-c6ac-46c0-a24a-ae8ff4f615f9', '蠶女', '蠶女', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["養蠶先養桑，蠶老人亦衰。","苟無園中葉，安得機上絲。","妾家非豪門，官賦日相追。","鳴梭夜達曉，猶恐不及時。","但憂蠶與桑，敢問結髮期。","東鄰女新嫁，照鏡弄蛾眉。"]', '["養蠶先養桑，蠶老人亦衰。","苟無园中葉，安得機上絲。","妾家非豪门，官賦日相追。","鳴梭夜達晓，猶恐不及时。","但憂蠶與桑，敢问結髮期。","东鄰女新嫁，照镜弄蛾眉。"]', '诗', 'shi', '', NULL, '蠶女 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2850ab41-f74d-4d9d-aff0-dabc4a1c7923', '效陶彭澤', '效陶彭澤', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["一夢倏已盡，百年如露草。","獨有南山高，不與人共老。","尊中貯靈味，無事即醉倒。","何必鳴鼓鍾，然後樂懷抱。","輕波向海疾，浮雲歸谷早。","形役良可嗟，唯能狥天道。"]', '["一梦倏已尽，百年如露草。","独有南山高，不與人共老。","尊中貯靈味，無事即醉倒。","何必鳴鼓鍾，然後乐懷抱。","轻波向海疾，浮云归谷早。","形役良可嗟，唯能狥天道。"]', '诗', 'shi', '', NULL, '效陶彭澤 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdf08d0a-1edf-4bd4-a382-0c28f5a6f948', '鋤草怨', '鋤草怨', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["種田望雨多，雨多長蓬蒿。","亦念官賦急，寧知荷鋤勞。","亭午霽日明，鄰翁醉陶陶。","鄉吏不到門，禾黍苗自高。","獨有辛苦者，屢爲州縣徭。","罷鋤田又廢，戀鄉不忍逃。","出門吏相促，鄰家滿倉穀。","鄰翁不可告，盡日向田哭。"]', '["種田望雨多，雨多长蓬蒿。","亦念官賦急，寧知荷鋤勞。","亭午霽日明，鄰翁醉陶陶。","乡吏不到门，禾黍苗自高。","独有辛苦者，屢爲州縣徭。","罷鋤田又廢，戀乡不忍逃。","出门吏相促，鄰家满倉穀。","鄰翁不可告，尽日向田哭。"]', '诗', 'shi', '', NULL, '鋤草怨 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03fc20d-f7bd-4f9c-a7c4-376629deb79d', '山中晚興寄裴侍御', '山中晚兴寄裴侍御', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["雷息疎雨散，空山夏雲晴。","南軒對林晚，籬落新蛩鳴。","白酒一樽滿，坐歌天地清。","十年身未閑，心在人間名。","永懷君親恩，久賤難退情。","安得蓬丘侶，提攜採瑤英。"]', '["雷息疎雨散，空山夏云晴。","南軒对林晚，籬落新蛩鳴。","白酒一樽满，坐歌天地清。","十年身未闲，心在人间名。","永懷君親恩，久賤难退情。","安得蓬丘侶，提携採瑤英。"]', '诗', 'shi', '', NULL, '山中晚興寄裴侍御 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28b8a470-9971-4eaa-9acf-e9feefc5aa02', '築臺', '築台', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["魏國昔強盛，宮中金玉多。","徵丁築層臺，唯恐不巍峩。","結構切星漢，躋攀橫綺羅。","朝觀細腰舞，夜聽皓齒歌。","詎念人力勞，安問黍與禾。","一朝國既傾，千仞堂亦平。","舞模衰柳影，歌留草蟲聲。","月照白露寒，蒼蒼故鄴城。","漢文有遺美，對此清飆生。"]', '["魏国昔強盛，宮中金玉多。","徵丁築層台，唯恐不巍峩。","結構切星漢，躋攀橫綺羅。","朝观細腰舞，夜听皓齒歌。","詎念人力勞，安问黍與禾。","一朝国既傾，千仞堂亦平。","舞模衰柳影，歌留草蟲声。","月照白露寒，蒼蒼故鄴城。","漢文有遺美，对此清飆生。"]', '诗', 'shi', '', NULL, '築臺 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d390439e-39c6-4d25-8e71-1f206941e71d', '道中早發', '道中早發', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["野店雞一聲，蕭蕭客車動。","西峯帶曉月，十里猶相送。","繁弦滿長道，羸馬四蹄重。","遙羨青樓人，錦衾方遠夢。","功名不我與，孤劍何所用。","行役難自休，家山憶秋洞。"]', '["野店雞一声，蕭蕭客车动。","西峯带晓月，十里猶相送。","繁弦满长道，羸马四蹄重。","遙羨青楼人，錦衾方远梦。","功名不我與，孤劍何所用。","行役难自休，家山憶秋洞。"]', '诗', 'shi', '', NULL, '道中早發 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18d967a7-1d37-4625-8e54-5516bf7f0d94', '滄浪峽', '滄浪峽', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["山下水聲深，水邊山色聚。","月照秋自清，花名春不去。","似非人間境，又近紅塵路。","乍入洞中天，更移雲外步。","我殊惺惺者，猶得滄浪趣。","可以濯吾纓，斯言誠所慕。"]', '["山下水声深，水邊山色聚。","月照秋自清，花名春不去。","似非人间境，又近紅塵路。","乍入洞中天，更移云外步。","我殊惺惺者，猶得滄浪趣。","可以濯吾纓，斯言誠所慕。"]', '诗', 'shi', '', NULL, '滄浪峽 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2327a4c2-734a-41a8-8bfa-47a99ff25862', '感螢', '感螢', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["愛爾持照書，臨書嘆吾道。","青熒一點光，曾誤幾人老。","夜久獨此心，環垣閉秋草。"]', '["愛爾持照书，臨书嘆吾道。","青熒一点光，曾誤幾人老。","夜久独此心，环垣閉秋草。"]', '诗', 'shi', '', NULL, '感螢 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408d91c7-a918-421c-8e68-22b6a50bc77e', '自渭南晚次華州', '自渭南晚次华州', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["前樓仙鼎原，西經赤水渡。","火雲入村巷，餘雨依驛樹。","我行傷去國，疲馬屢回顧。","有如無窠鳥，觸熱不得住。","峨峨華峰近，城郭生夕霧。","逆旅何人尋，行客暗中住。","却思林丘臥，自愜平生素。","勞役今若茲，羞吟招隱句。"]', '["前楼仙鼎原，西經赤水渡。","火云入村巷，餘雨依驛樹。","我行傷去国，疲马屢回顧。","有如無窠鸟，觸熱不得住。","峨峨华峰近，城郭生夕霧。","逆旅何人尋，行客暗中住。","却思林丘臥，自愜平生素。","勞役今若茲，羞吟招隐句。"]', '诗', 'shi', '', NULL, '自渭南晚次華州 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e3fc6e-0322-41b8-b586-76e6c93ee064', '近別', '近別', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["咫尺不相見，便同天一涯。","何必隔關山，乃言傷別離。","君心與我心，脈脈無由知。","誰堪近別苦，遠別猶有期。"]', '["咫尺不相见，便同天一涯。","何必隔关山，乃言傷別離。","君心與我心，脈脈無由知。","誰堪近別苦，远別猶有期。"]', '诗', 'shi', '', NULL, '近別 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97310e23-b545-4b6e-a530-a74edb94401a', '江上秋夕', '江上秋夕', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["茂陵歸路絕，誰念此淹留。","極目月沈浦，苦吟霜滿舟。","孤猨啼後夜，久客病高秋。","欲寄鄉關恨，寒江無北流。"]', '["茂陵归路絕，誰念此淹留。","極目月沈浦，苦吟霜满舟。","孤猨啼後夜，久客病高秋。","欲寄乡关恨，寒江無北流。"]', '诗', 'shi', '', NULL, '江上秋夕 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e561f18-2348-45a6-80b1-364824ff031a', '送歸客', '送归客', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["多才與命違，末路隱柴扉。","白髮何人問，青山一劍歸。","晴煙獨鳥沒，野渡亂花飛。","寂寞長亭外，依然空落暉。"]', '["多才與命違，末路隐柴扉。","白髮何人问，青山一劍归。","晴煙独鸟沒，野渡亂花飞。","寂寞长亭外，依然空落暉。"]', '诗', 'shi', '', NULL, '送歸客 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81fe9653-efb5-48c7-a8a7-f21889bd5abb', '東門晚望', '东门晚望', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["青門聊極望，何事久離羣。","芳草失歸路，故鄉空暮雲。","信回陵樹老，夢斷灞流分。","兄弟正南北，鴻聲堪獨聞。"]', '["青门聊極望，何事久離羣。","芳草失归路，故乡空暮云。","信回陵樹老，梦斷灞流分。","兄弟正南北，鴻声堪独闻。"]', '诗', 'shi', '', NULL, '東門晚望 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0056e0d-8129-47bd-a339-3ecf5bc6e0a4', '上巳日曲江有感', '上巳日曲江有感', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["萬花明曲水，車馬動秦川。","此日不得意，青春徒少年。","晴沙下鷗鷺，幽沚生蘭荃。","向晚積歸念，江湖心渺然。"]', '["万花明曲水，车马动秦川。","此日不得意，青春徒少年。","晴沙下鷗鷺，幽沚生蘭荃。","向晚積归念，江湖心渺然。"]', '诗', 'shi', '', NULL, '上巳日曲江有感 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3a336f9-70cf-42be-bda3-5868cf31cc4e', '宿壽安甘棠館', '宿壽安甘棠館', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["行人方倦役，到此似還鄉。","流水來關外，青山近洛陽。","溪雲歸洞鶴，松月半軒霜。","坐恐晨鐘動，天涯道路長。"]', '["行人方倦役，到此似還乡。","流水来关外，青山近洛陽。","溪云归洞鹤，松月半軒霜。","坐恐晨鐘动，天涯道路长。"]', '诗', 'shi', '', NULL, '宿壽安甘棠館 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dd0bb50-33ec-4f6e-bbc1-f3cf7004e248', '送友人下第東遊', '送友人下第东游', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["出門皆有託，君去獨何親。","闕下新交少，天涯舊業貧。","煙寒嶽樹暝，雪後嶺梅春。","聖代留崑玉，那令愧郄詵。"]', '["出门皆有託，君去独何親。","闕下新交少，天涯旧業貧。","煙寒嶽樹暝，雪後嶺梅春。","聖代留崑玉，那令愧郄詵。"]', '诗', 'shi', '', NULL, '送友人下第東遊 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7164b5a2-b1ac-4a35-a5e4-9104ac73507a', '山齋會別', '山斋會別', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["春草平陵路，荷衣醉別離。","將尋洛陽友，共結洞庭期。","星月半山盡，天雞出海遲。","無輕此分手，他日重相思。"]', '["春草平陵路，荷衣醉別離。","將尋洛陽友，共結洞庭期。","星月半山尽，天雞出海遲。","無轻此分手，他日重相思。"]', '诗', 'shi', '', NULL, '山齋會別 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4e05646-6b81-4a6d-89d6-027127804642', '曉過伊水寄龍門僧', '晓過伊水寄龙门僧', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["龍門樹色暗蒼蒼，伊水東流客恨長。","病馬獨嘶殘夜月，行人欲渡滿船霜。","幾家煙火依村步，何處漁歌似故鄉？","山下禪菴老師在，願將形役問空王。"]', '["龙门樹色暗蒼蒼，伊水东流客恨长。","病马独嘶殘夜月，行人欲渡满船霜。","幾家煙火依村步，何处漁歌似故乡？","山下禪菴老師在，願將形役问空王。"]', '诗', 'shi', '', NULL, '曉過伊水寄龍門僧 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d140535d-2598-4a93-ac7d-de1aeba2c9cd', '送孔恂入洛', '送孔恂入洛', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["洛陽古城秋色多，送君此去心如何。","青山欲暮惜別酒，碧草未盡傷離歌。","前朝冠帶掩金谷，舊遊花月經銅駝。","行人正苦奈分手，日落遠水生微波。"]', '["洛陽古城秋色多，送君此去心如何。","青山欲暮惜別酒，碧草未尽傷離歌。","前朝冠带掩金谷，旧游花月經銅駝。","行人正苦奈分手，日落远水生微波。"]', '诗', 'shi', '', NULL, '送孔恂入洛 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32052178-e4ac-4dc9-b6c0-4b962261632f', '觀郊禮', '观郊禮', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["鐘鼓旌旗引六飛，玉皇初著畫龍衣。","泰壇煙盡星河曉，萬國心隨彩仗歸。"]', '["鐘鼓旌旗引六飞，玉皇初著畫龙衣。","泰壇煙尽星河晓，万国心隨彩仗归。"]', '诗', 'shi', '', NULL, '觀郊禮 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47422314-a323-4b8f-b83b-76093f835055', '宮怨', '宮怨', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["柳色參差掩畫樓，曉鶯啼送滿宮愁。","年年花落無人見，空逐春泉出御溝。"]', '["柳色參差掩畫楼，晓鶯啼送满宮愁。","年年花落無人见，空逐春泉出御溝。"]', '诗', 'shi', '', NULL, '宮怨 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9964321a-16ed-4fe4-ba73-a18465c25d7e', '南徐夕眺', '南徐夕眺', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["行吟向暮天，何處不悽然？","岸影幾家柳，笛聲何處船。","樓分瓜步月，鳥入秣陵煙。","故里無人到，鄉書誰爲傳。"]', '["行吟向暮天，何处不悽然？","岸影幾家柳，笛声何处船。","楼分瓜步月，鸟入秣陵煙。","故里無人到，乡书誰爲傳。"]', '诗', 'shi', '', NULL, '南徐夕眺 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4b61949-735e-4b22-8c02-ca7fcab890aa', '題清上人', '題清上人', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["古院閉松色，入門人自閑。","罷經來宿鳥，支策對秋山。","客念蓬梗外，禪心煙霧間。","空憐濯纓處，階下水潺潺。"]', '["古院閉松色，入门人自闲。","罷經来宿鸟，支策对秋山。","客念蓬梗外，禪心煙霧间。","空怜濯纓处，階下水潺潺。"]', '诗', 'shi', '', NULL, '題清上人 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f8ca30-783d-4cf7-b000-8e460681c961', '塗中寄薛中裕', '塗中寄薛中裕', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["貧交千里外，失路更傷離。","曉淚芳草盡，夜魂明月知。","空山連野外，寒鳥下霜枝。","此景正寥落，爲君玄髪衰。"]', '["貧交千里外，失路更傷離。","晓泪芳草尽，夜魂明月知。","空山連野外，寒鸟下霜枝。","此景正寥落，爲君玄髪衰。"]', '诗', 'shi', '', NULL, '塗中寄薛中裕 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06357ff7-17ed-47dc-af95-662a1aba2e71', '白馬津阻雨', '白马津阻雨', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["津樹蕭蕭旅館空，坐看疎葉繞堦紅。","故鄉千里楚雲外，歸鴈一聲煙雨中。","漳浦病多愁易老，茂陵書在信難通。","功名儻遂身無事，終向溪頭伴釣翁。"]', '["津樹蕭蕭旅館空，坐看疎葉繞堦紅。","故乡千里楚云外，归鴈一声煙雨中。","漳浦病多愁易老，茂陵书在信难通。","功名儻遂身無事，終向溪头伴釣翁。"]', '诗', 'shi', '', NULL, '白馬津阻雨 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cdf2d9b-29c2-452b-b35b-d1232f7f3f3e', '秋日懷儲嗣宗', '秋日懷儲嗣宗', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["故人北遊久不回，塞鴈南渡聲何哀。","相思聞鴈更惆悵，却向單于臺下來。"]', '["故人北游久不回，塞鴈南渡声何哀。","相思闻鴈更惆悵，却向單于台下来。"]', '诗', 'shi', '', NULL, '秋日懷儲嗣宗 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0043d602-6f92-4761-ba75-92691019f99d', '夜聽李山人彈琴', '夜听李山人彈琴', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["瑤琴夜久弦秋清，楚客一奏湘煙生。","曲中聲盡意不盡，月照竹軒紅葉明。"]', '["瑤琴夜久弦秋清，楚客一奏湘煙生。","曲中声尽意不尽，月照竹軒紅葉明。"]', '诗', 'shi', '', NULL, '夜聽李山人彈琴 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3deaed4-56e7-47d6-9e77-1f928f5cace3', '隱者', '隐者', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["松間開一徑，秋草自相依。","終日不冠帶，空山無是非。","投綸溪鳥伴，曝藥谷雲飛。","時向鄰家去，狂歌夜醉歸。"]', '["松间开一徑，秋草自相依。","終日不冠带，空山無是非。","投綸溪鸟伴，曝藥谷云飞。","时向鄰家去，狂歌夜醉归。"]', '诗', 'shi', '', NULL, '隱者 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea99c1a-40f3-461e-8167-8b52b77acd70', '登河中鸛[雀]樓', '登河中鸛[雀]楼', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["樓中見千里，樓影入通津。","煙樹遙分陝，山河曲向秦。","興亡留白日，今古共紅塵。","鸛雀飛何處，城隅草自春。"]', '["楼中见千里，楼影入通津。","煙樹遙分陝，山河曲向秦。","兴亡留白日，今古共紅塵。","鸛雀飞何处，城隅草自春。"]', '诗', 'shi', '', NULL, '登河中鸛[雀]樓 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('450db7df-1306-47dc-b4f8-d7809129bfe2', '漾陂晚望', '漾陂晚望', '92e0f38f-bab7-4b70-9b06-c4f358a7174f', '唐', '["遠客家水國，此來如到鄉。","何人垂白髮，一葉釣殘陽。","柳暗鳥乍起，渚深蘭自芳。","因知帝城下，有路向滄浪。"]', '["远客家水国，此来如到乡。","何人垂白髮，一葉釣殘陽。","柳暗鸟乍起，渚深蘭自芳。","因知帝城下，有路向滄浪。"]', '诗', 'shi', '', NULL, '漾陂晚望 司馬扎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ff35c04-74ea-4ccf-96b6-e997b65cd299', '賀襄陽副使節判同加章綬', '賀襄陽副使節判同加章綬', '8bbeb390-8d9c-42f3-b2fe-52be0fe39cad', '唐', '["朱紫花前賀故人，兼榮此會頗關身。","同年坐上聯賓榻，宗姓亭中布錦裀。","晴日照旗紅灼爍，韶光入隊影玢璘。","芳菲解助今朝喜，嫩蘂青條滿眼新。"]', '["朱紫花前賀故人，兼榮此會頗关身。","同年坐上聯賓榻，宗姓亭中布錦裀。","晴日照旗紅灼爍，韶光入隊影玢璘。","芳菲解助今朝喜，嫩蘂青條满眼新。"]', '诗', 'shi', '', NULL, '賀襄陽副使節判同加章綬 徐商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cecb3152-105e-464a-8d92-36a546b522e3', '句', '句', '8bbeb390-8d9c-42f3-b2fe-52be0fe39cad', '唐', '["萍聚只因今日浪，荻斜都爲夜來風。"]', '["萍聚只因今日浪，荻斜都爲夜来风。"]', '诗', 'shi', '', NULL, '句 徐商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab9b9e43-8233-4259-adf8-6a7014dc94f7', '和薛逢贈別', '和薛逢贈別', 'fac1d8ef-d4d8-462b-af42-ddfc6e861abd', '唐', '["劒外綿州第一州，尊前偏喜接君留。","歌聲婉轉添長恨，管色淒涼似到秋。","但務歡娛思曉角，獨耽雲水上高樓。","莫言此去難相見，怨別徵黃是順流。"]', '["劒外綿州第一州，尊前偏喜接君留。","歌声婉轉添长恨，管色淒涼似到秋。","但務歡娛思晓角，独耽云水上高楼。","莫言此去难相见，怨別徵黄是順流。"]', '诗', 'shi', '', NULL, '和薛逢贈別 高璩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4aecab54-86f7-4f26-9ac3-28498c80f0e9', '句', '句', 'fac1d8ef-d4d8-462b-af42-ddfc6e861abd', '唐', '["公齋一到人非舊，詩板重尋墨尚新。"]', '["公斋一到人非旧，诗板重尋墨尚新。"]', '诗', 'shi', '', NULL, '句 高璩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e65a5187-14c1-4e30-97fa-3ff1b269f189', '和李尚書命妓餞崔侍御', '和李尚书命妓餞崔侍御', '87cf7a7d-5088-46da-9cb3-0a61d18f9b58', '唐', '["謝安春渚餞袁宏，千里仁風一扇清。","歌黛慘時方酩酊，不知公子重飛觥。"]', '["謝安春渚餞袁宏，千里仁风一扇清。","歌黛慘时方酩酊，不知公子重飞觥。"]', '诗', 'shi', '', NULL, '和李尚書命妓餞崔侍御 高湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d06ed5-b9e1-4e17-b2c8-b73a39f2df69', '句', '句', '87cf7a7d-5088-46da-9cb3-0a61d18f9b58', '唐', '["惟有高州是當家。"]', '["惟有高州是當家。"]', '诗', 'shi', '', NULL, '句 高湘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b48f4e-3ce8-424a-9b21-81d6d8a5bf38', '報何澤', '報何澤', 'b38e508c-34fd-4906-8a97-1a349cd75d6b', '唐', '["四十九年前及第，同年唯有老夫存。","今日殷勤訪吾子，穩將鬐鬣上龍門。"]', '["四十九年前及第，同年唯有老夫存。","今日殷勤訪吾子，穩將鬐鬣上龙门。"]', '诗', 'shi', '', NULL, '報何澤 崔安潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29a0b2d4-bcd6-4240-ad33-3e61152efae0', '題文翁石室', '題文翁石室', '69130749-ed0b-4cd5-b283-4a2579f0f44c', '唐', '["文翁石室有儀形，庠序千秋播德馨。","古柏尚留今日翠，高岷猶藹舊時青。","人心未肯拋羶蟻，弟子依前學聚螢。","更歎沱江無限水，爭流祗願到滄溟。"]', '["文翁石室有儀形，庠序千秋播德馨。","古柏尚留今日翠，高岷猶藹旧时青。","人心未肯拋羶蟻，弟子依前学聚螢。","更歎沱江無限水，爭流祗願到滄溟。"]', '诗', 'shi', '', NULL, '題文翁石室 裴鉶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9586ded-0bcc-4376-8be2-9141eb600420', '憤惋詩三首 一', '憤惋诗三首 一', '52c542fa-aee1-4615-a3fb-3f3ecfb8f41b', '唐', '["寶釵分股合無緣，魚在深淵日在天。","得意紫鸞休舞鏡，斷蹤青鳥罷銜箋。","金杯倒覆難收水，玉軫傾攲嬾續弦。","從此蘼蕪山下過，祗應將淚比黃泉。"]', '["寶釵分股合無緣，鱼在深淵日在天。","得意紫鸾休舞镜，斷蹤青鸟罷銜箋。","金杯倒覆难收水，玉軫傾攲嬾續弦。","從此蘼蕪山下過，祗應將泪比黄泉。"]', '诗', 'shi', '', NULL, '憤惋詩三首 一 劉損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fca2ab7-0e3d-4090-9cb7-401ea1c52047', '憤惋詩三首 二', '憤惋诗三首 二', '52c542fa-aee1-4615-a3fb-3f3ecfb8f41b', '唐', '["鸞辭舊伴知何止，鳳得新梧想稱心。","紅粉尚存香幕幕，白雲將散信沈沈。","已休磨琢投泥玉，嬾更經營買笑金。","願作山頭似人石，丈夫衣上淚痕深。"]', '["鸾辞旧伴知何止，鳳得新梧想稱心。","紅粉尚存香幕幕，白云將散信沈沈。","已休磨琢投泥玉，嬾更經營買笑金。","願作山头似人石，丈夫衣上泪痕深。"]', '诗', 'shi', '', NULL, '憤惋詩三首 二 劉損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a12de7-13b3-467e-8110-94d4cb276b25', '憤惋詩三首 三', '憤惋诗三首 三', '52c542fa-aee1-4615-a3fb-3f3ecfb8f41b', '唐', '["舊嘗游處徧尋看，覩物傷情死一般。","買笑樓前花已謝，畫眉窗下月空殘。","雲歸巫峽音容斷，路隔星河去住難。","莫道詩成無淚下，淚如泉滴亦須乾。"]', '["旧嘗游处徧尋看，覩物傷情死一般。","買笑楼前花已謝，畫眉窗下月空殘。","云归巫峽音容斷，路隔星河去住难。","莫道诗成無泪下，泪如泉滴亦須乾。"]', '诗', 'shi', '', NULL, '憤惋詩三首 三 劉損 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9871668d-9976-4317-ab31-64ea5aa25d79', '幼作', '幼作', '56355a6f-287b-4a28-ae04-3ab685c5d112', '唐', '["臺山初罷霧，岐海正分流。","漁浦颺來笛，鴻逵翼去舟。"]', '["台山初罷霧，岐海正分流。","漁浦颺来笛，鴻逵翼去舟。"]', '诗', 'shi', '', NULL, '幼作 鄭愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62bacd9-1b2d-42c8-8e21-00ff845411f4', '茶詩', '茶诗', '56355a6f-287b-4a28-ae04-3ab685c5d112', '唐', '["嫩芽香且靈，吾謂草中英。","夜臼和煙擣，寒爐對雪烹。","惟憂碧粉散，嘗見綠花生。"]', '["嫩芽香且靈，吾謂草中英。","夜臼和煙擣，寒爐对雪烹。","惟憂碧粉散，嘗见綠花生。"]', '诗', 'shi', '', NULL, '茶詩 鄭愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c7ee228-88eb-4cc5-a801-b849aa72c322', '郡樓望九華歌', '郡楼望九华歌', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["樓上坐見九子峰，翠雲赤日光溶溶。","有時朝昏變疎密，八峰和煙一峰出。","有時風卷天雨晴，聚立連連如弟兄。","陽烏生子偶成數，丹鳳養雛同此名。","日日遙看機已靜，未離塵躅思真境。","子明龍駕騰九垓，陵陽相對空崔嵬。","玉漿瑤草不可見，自有神仙風馬來。"]', '["楼上坐见九子峰，翠云赤日光溶溶。","有时朝昏变疎密，八峰和煙一峰出。","有时风卷天雨晴，聚立連連如弟兄。","陽烏生子偶成數，丹鳳養雛同此名。","日日遙看機已静，未離塵躅思真境。","子明龙駕腾九垓，陵陽相对空崔嵬。","玉漿瑤草不可见，自有神仙风马来。"]', '诗', 'shi', '', NULL, '郡樓望九華歌 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f524312b-9379-465b-a9ec-fb3e990f60a8', '塞下曲', '塞下曲', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["曾當一面戰，頻出九重圍。","但見爭鋒處，長須得勝歸。","雪沾旗尾落，風斷節毛稀。","豈要銘燕石，平生重武威。"]', '["曾當一面戰，頻出九重圍。","但见爭鋒处，长須得勝归。","雪沾旗尾落，风斷節毛稀。","豈要銘燕石，平生重武威。"]', '诗', 'shi', '', NULL, '塞下曲 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21aa65f5-6337-4c44-9adb-1434c662de9c', '關山月', '关山月', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["珠瓏翡翠牀，白皙侍中郎。","五日來花下，雙童問道傍。","到門車馬狹，連夜管弦長。","每笑東家子，窺他宋玉牆。"]', '["珠瓏翡翠牀，白皙侍中郎。","五日来花下，雙童问道傍。","到门车马狹，連夜管弦长。","每笑东家子，窺他宋玉牆。"]', '诗', 'shi', '', NULL, '關山月 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c833a5a-c741-4171-9cdd-a971698eb7f8', '驄馬', '驄马', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["青驪八尺高，俠客倚雄豪。","踏雪生珠汗，障泥護錦袍。","路傍看驟影，鞍底卷旋毛。","豈獨連錢貴，酬恩更代勞。"]', '["青驪八尺高，俠客倚雄豪。","踏雪生珠汗，障泥護錦袍。","路傍看驟影，鞍底卷旋毛。","豈独連錢貴，酬恩更代勞。"]', '诗', 'shi', '', NULL, '驄馬 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057eb3cc-a5e3-4f6c-b010-74c2fcf23cb2', '雉朝飛', '雉朝飞', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["五色有名翬，清晨挾兩雌。","羣羣飛自樂，步步飲相隨。","覘葉逢人處，驚媒妬寵時。","綠毛春鬬盡，強敵願君知。"]', '["五色有名翬，清晨挾兩雌。","羣羣飞自乐，步步饮相隨。","覘葉逢人处，驚媒妬寵时。","綠毛春鬬尽，強敵願君知。"]', '诗', 'shi', '', NULL, '雉朝飛 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b55ce0-77f8-4f9b-b52b-eed1c64d913c', '木芙蓉', '木芙蓉', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["本自江湖遠，常開霜露餘。","爭春候穠李，得水異紅蕖。","孤秀曾無偶，當門幸不鋤。","誰能政搖落，繁綵照堦除。"]', '["本自江湖远，常开霜露餘。","爭春候穠李，得水異紅蕖。","孤秀曾無偶，當门幸不鋤。","誰能政搖落，繁綵照堦除。"]', '诗', 'shi', '', NULL, '木芙蓉 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4482045e-3a96-4ba4-a413-df327778447f', '採蓮女', '採蓮女', 'd182ddde-7af8-401a-91f5-6e14b60d5289', '唐', '["舟中採蓮女，兩兩催妝梳。","聞早渡江去，日高來起居。"]', '["舟中採蓮女，兩兩催妝梳。","闻早渡江去，日高来起居。"]', '诗', 'shi', '', NULL, '採蓮女 霍總 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f6514c-ad10-458e-8f44-dbbc62581fac', '別僧', '別僧', 'b26b973c-964b-4b3b-8637-60824b1af9e0', '唐', '["行若獨輪車，常畏大道覆。","止若員底器，常恐他物觸。","行止既如此，安得不離俗。"]', '["行若独輪车，常畏大道覆。","止若員底器，常恐他物觸。","行止既如此，安得不離俗。"]', '诗', 'shi', '', NULL, '別僧 陳琡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e83cd7e3-9644-4051-b426-7d97af9aed04', '早春殘雪', '早春殘雪', 'eab56e8d-9f2f-45ac-856c-28a7b64ad762', '唐', '["霽日彫瓊彩，幽庭減夜寒。","梅飄餘片積，日墮晚光殘。","零落偏依桂，霏微不掩蘭。","陰林披霧縠，小沼破冰盤。","曲檻霜凝砌，疎篁玉碎竿。","已聞三徑好，猶可訪袁安。"]', '["霽日彫瓊彩，幽庭減夜寒。","梅飄餘片積，日墮晚光殘。","零落偏依桂，霏微不掩蘭。","陰林披霧縠，小沼破冰盤。","曲檻霜凝砌，疎篁玉碎竿。","已闻三徑好，猶可訪袁安。"]', '诗', 'shi', '', NULL, '早春殘雪 裴虔餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78306b9-595e-4e5e-8bbc-ef1be756d546', '柳枝詞詠篙水濺妓衣', '柳枝词詠篙水濺妓衣', 'eab56e8d-9f2f-45ac-856c-28a7b64ad762', '唐', '["半額微黃金縷衣，玉搔頭褭鳳雙飛。","從教水濺羅裙濕，還道朝來行雨歸。"]', '["半額微黄金縷衣，玉搔头褭鳳雙飞。","從教水濺羅裙濕，還道朝来行雨归。"]', '诗', 'shi', '', NULL, '柳枝詞詠篙水濺妓衣 裴虔餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d1d979-7ae2-4695-80c8-8757de740b02', '獻淮南師', '獻淮南師', '71b8fb32-2be1-45a6-863a-fde43d9574be', '唐', '["雞樹煙含瑞氣凝，鳳池波待玉山澄。","國人久倚東關望，擬築沙堤到廣陵。"]', '["雞樹煙含瑞氣凝，鳳池波待玉山澄。","国人久倚东关望，擬築沙堤到廣陵。"]', '诗', 'shi', '', NULL, '獻淮南師 李嶸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35f4accd-0acf-4735-888c-d2f9a4ec8bb6', '月', '月', '5f85f4ee-9c16-4c85-9ee6-9621d6af1809', '唐', '["嫦娥竊藥出人間，藏在蟾宮不放還。","后羿遍尋無覓處，誰知天上却容奸。"]', '["嫦娥竊藥出人间，藏在蟾宮不放還。","后羿遍尋無覓处，誰知天上却容奸。"]', '诗', 'shi', '', NULL, '月 袁郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee3055f1-8836-423b-86be-44390b228dc7', '霜', '霜', '5f85f4ee-9c16-4c85-9ee6-9621d6af1809', '唐', '["古今何事不思量，盡信鄒生感彼蒼。","但想燕山吹暖律，炎天豈不解飛霜。"]', '["古今何事不思量，尽信鄒生感彼蒼。","但想燕山吹暖律，炎天豈不解飞霜。"]', '诗', 'shi', '', NULL, '霜 袁郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39b55630-d684-4c89-bfc9-b7a88df51a26', '露', '露', '5f85f4ee-9c16-4c85-9ee6-9621d6af1809', '唐', '["湛湛騰空下碧霄，地卑濕處更偏饒。","菅茅豐草皆霑潤，不道良田有旱苗。"]', '["湛湛腾空下碧霄，地卑濕处更偏饒。","菅茅豐草皆霑潤，不道良田有旱苗。"]', '诗', 'shi', '', NULL, '露 袁郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a7e246-9c7a-46b4-8b44-fc6c27d637f6', '雲', '云', '5f85f4ee-9c16-4c85-9ee6-9621d6af1809', '唐', '["楚甸嘗聞旱魃侵，從龍應合解爲霖。","荒淫却入陽臺夢，惑亂懷襄父子心。"]', '["楚甸嘗闻旱魃侵，從龙應合解爲霖。","荒淫却入陽台梦，惑亂懷襄父子心。"]', '诗', 'shi', '', NULL, '雲 袁郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b288394-192c-472e-b86e-85f781ca94f0', '游東觀山', '游东观山', '06a11962-d9ff-42bf-b32b-152897ed9695', '唐', '["巖岫碧孱顏，靈蹤若可攀。","樓臺煙靄外，松竹翠微間。","玉液寒深洞，秋光秀遠山。"]', '["巖岫碧孱顏，靈蹤若可攀。","楼台煙靄外，松竹翠微间。","玉液寒深洞，秋光秀远山。"]', '诗', 'shi', '', NULL, '游東觀山 張叢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd9b680-d424-4485-9019-2151d92cc23b', '擲盧作', '擲盧作', '8fa97c06-d94d-49e1-8b28-9136360246af', '唐', '["八尺臺盤照面新，千金一擲鬬精神。","合是賭時須賭取，不妨回首乞閑人。"]', '["八尺台盤照面新，千金一擲鬬精神。","合是賭时須賭取，不妨回首乞闲人。"]', '诗', 'shi', '', NULL, '擲盧作 馮衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0522f7b-b41f-4bfe-9a76-e74151b12231', '戲酒妓', '戲酒妓', '8fa97c06-d94d-49e1-8b28-9136360246af', '唐', '["醉眼從伊百度斜，是他家屬是他家。","低聲向道人知也，隔坐剛拋豆蔻花。"]', '["醉眼從伊百度斜，是他家屬是他家。","低声向道人知也，隔坐剛拋豆蔻花。"]', '诗', 'shi', '', NULL, '戲酒妓 馮衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('370f1c67-24a6-4015-892a-8764ed779dfe', '老僧', '老僧', 'a50985c6-f11d-4c77-830d-68be319a2986', '唐', '["日照四山雪，老僧門未開。","凍缾黏柱礎，宿火陷爐灰。","童子病歸去，鹿麑寒入來。","齋鐘知漸近，枝鳥下生臺。"]', '["日照四山雪，老僧门未开。","凍缾黏柱礎，宿火陷爐灰。","童子病归去，鹿麑寒入来。","斋鐘知漸近，枝鸟下生台。"]', '诗', 'shi', '', NULL, '老僧 鄭綮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5109cbea-0495-4599-9ec8-236877556a0d', '題盧州郡齋', '題盧州郡斋', 'a50985c6-f11d-4c77-830d-68be319a2986', '唐', '["九衢塵裏一書生，多達逢時擁斾旌。","醉裏眼開金使字，紫旂風動耀天明。"]', '["九衢塵裏一书生，多達逢时擁斾旌。","醉裏眼开金使字，紫旂风动耀天明。"]', '诗', 'shi', '', NULL, '題盧州郡齋 鄭綮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bac87ad4-5c7e-46eb-b236-966aa4585662', '別郡後寄席中三蘭', '別郡後寄席中三蘭', 'a50985c6-f11d-4c77-830d-68be319a2986', '唐', '["淮淝兩水不相通，隔岸臨流望向東。","千顆淚珠無寄處，一時彈與渡前風。"]', '["淮淝兩水不相通，隔岸臨流望向东。","千顆泪珠無寄处，一时彈與渡前风。"]', '诗', 'shi', '', NULL, '別郡後寄席中三蘭 鄭綮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07bffb76-c688-4d8f-aec8-c4a088291cb6', '觀山燈獻徐尚書 一', '观山灯獻徐尚书 一', 'b3c4eafd-3962-45c3-8fec-ec50ec45796c', '唐', '["一峰當勝地，萬點照嚴城。","勢異崑岡發，光疑玄圃生。","焚書翻見字，舉燧不招兵。","況遇新春夜，何勞秉燭行。"]', '["一峰當勝地，万点照嚴城。","勢異崑岡發，光疑玄圃生。","焚书翻见字，舉燧不招兵。","況遇新春夜，何勞秉燭行。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 一 溫庭皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c08c65-a9da-4504-b4b0-ea7e1fc4e631', '觀山燈獻徐尚書 二', '观山灯獻徐尚书 二', 'b3c4eafd-3962-45c3-8fec-ec50ec45796c', '唐', '["九枝應並耀，午夜忽潛然。","景集青山外，螢分碧草前。","輝華侵月影，歷亂寫星躔。","望極高樓上，搖光滿綺筵。"]', '["九枝應並耀，午夜忽潛然。","景集青山外，螢分碧草前。","輝华侵月影，歷亂寫星躔。","望極高楼上，搖光满綺筵。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 二 溫庭皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8d4e30d-807a-48d0-aa19-3c21bad1d7a5', '觀山燈獻徐尚書 三', '观山灯獻徐尚书 三', 'b3c4eafd-3962-45c3-8fec-ec50ec45796c', '唐', '["春山收暝色，爝火集餘輝。","麗景饒紅焰，祥光出翠微。","白榆行自比，青桂影相依。","唯有偷光客，追游欲忘歸。"]', '["春山收暝色，爝火集餘輝。","丽景饒紅焰，祥光出翠微。","白榆行自比，青桂影相依。","唯有偷光客，追游欲忘归。"]', '诗', 'shi', '', NULL, '觀山燈獻徐尚書 三 溫庭皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12361079-c3ed-48a8-8f55-1e11dbb6f2e1', '梅', '梅', 'b3c4eafd-3962-45c3-8fec-ec50ec45796c', '唐', '["一樹寒林外，何人此地栽。","春光先自煖，陽豔暗相催。","曉覺霜添白，寒迷月借開。","餘香低惹袖，墮蘂逐流杯。","零落移新煖，飄颺上故臺。","雪繁鶯不識，風裊蝶空迴。","羌吹應愁起，征徒異渴來。","莫貪題詠興，商鼎待鹽梅。"]', '["一樹寒林外，何人此地栽。","春光先自煖，陽豔暗相催。","晓覺霜添白，寒迷月借开。","餘香低惹袖，墮蘂逐流杯。","零落移新煖，飄颺上故台。","雪繁鶯不識，风裊蝶空迴。","羌吹應愁起，征徒異渴来。","莫貪題詠兴，商鼎待鹽梅。"]', '诗', 'shi', '', NULL, '梅 溫庭皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90ef407-98fc-4c75-b0ac-90db92cd1d6d', '言懷', '言懷', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["恨乏平戎策，慙登拜將壇。","手持金鉞冷，身挂鐵衣寒。","主聖扶持易，恩深報效難。","三邊猶未靜，何敢便休官。"]', '["恨乏平戎策，慙登拜將壇。","手持金鉞冷，身挂鐵衣寒。","主聖扶持易，恩深報效难。","三邊猶未静，何敢便休官。"]', '诗', 'shi', '', NULL, '言懷 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0425c5c7-4346-494d-b6b8-06a3c8c20dd1', '寄鄠杜李遂良處士', '寄鄠杜李遂良处士', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["小隱堪忘世上情，可能休夢入重城。","池邊寫字師前輩，座右題銘律後生。","吟社客歸秦渡晚，醉鄉漁去渼陂晴。","春來不得山中信，盡日無人傍水行。"]', '["小隐堪忘世上情，可能休梦入重城。","池邊寫字師前輩，座右題銘律後生。","吟社客归秦渡晚，醉乡漁去渼陂晴。","春来不得山中信，尽日無人傍水行。"]', '诗', 'shi', '', NULL, '寄鄠杜李遂良處士 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1e6614d-8dd3-4444-82ff-6da2d8fa9806', '和王昭符進士贈洞庭趙先生', '和王昭符進士贈洞庭趙先生', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["爲愛君山景最靈，角冠秋禮一壇星。","藥將雞犬雲間試，琴許魚龍月下聽。","自要乘風隨羽客，誰同種玉驗仙經。","煙霞澹泊無人到，唯有漁翁過洞庭。"]', '["爲愛君山景最靈，角冠秋禮一壇星。","藥將雞犬云间試，琴許鱼龙月下听。","自要乘风隨羽客，誰同種玉驗仙經。","煙霞澹泊無人到，唯有漁翁過洞庭。"]', '诗', 'shi', '', NULL, '和王昭符進士贈洞庭趙先生 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39def9ab-7dc5-4ba0-a61c-691e77402189', '依韻奉酬李迪', '依韻奉酬李迪', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["柳下官資顏子居，閑情入骨若爲除。","詩成斬將奇難敵，酒熟封侯快未如。","只見絲綸終日降，不知功業是誰書。","而今共飲醇滋味，消得揶揄勢利疎。"]', '["柳下官資顏子居，闲情入骨若爲除。","诗成斬將奇难敵，酒熟封侯快未如。","只见絲綸終日降，不知功業是誰书。","而今共饮醇滋味，消得揶揄勢利疎。"]', '诗', 'shi', '', NULL, '依韻奉酬李迪 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a302a9bc-922d-49d7-a6c4-56846a636444', '留別彰德軍從事范校書', '留別彰德軍從事范校书', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["無金寄與白頭親，節概猶誇似古人。","未出塵埃真落魄，不趨權勢正因循。","桂攀明月曾觀國，蓬轉西風却問津。","匹馬東歸羨知己，燕王臺上結交新。"]', '["無金寄與白头親，節概猶誇似古人。","未出塵埃真落魄，不趨權勢正因循。","桂攀明月曾观国，蓬轉西风却问津。","匹马东归羨知己，燕王台上結交新。"]', '诗', 'shi', '', NULL, '留別彰德軍從事范校書 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11bee415-b8fe-4463-8ea8-323cca6a73a0', '途次內黃馬病寄僧舍呈諸友人', '途次內黄马病寄僧舍呈諸友人', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["官閑馬病客深秋，肯學張衡詠四愁。","紅葉寺多詩景致，白衣人盡酒交游。","依違諷刺因行得，澹泊供需不在求。","好與高陽結吟社，況無名跡達珠旒。"]', '["官闲马病客深秋，肯学張衡詠四愁。","紅葉寺多诗景致，白衣人尽酒交游。","依違諷刺因行得，澹泊供需不在求。","好與高陽結吟社，況無名跡達珠旒。"]', '诗', 'shi', '', NULL, '途次內黃馬病寄僧舍呈諸友人 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff1aa6db-1c83-4337-bde5-18230bede22d', '遣興', '遣兴', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["浮世忙忙蟻子羣，莫嗔頭上雪紛紛。","沈憂萬種與千種，行樂十分無一分。","越外險巇防俗事，就中拘檢信人文。","醉鄉日月終須覓，去作先生號白雲。"]', '["浮世忙忙蟻子羣，莫嗔头上雪紛紛。","沈憂万種與千種，行乐十分無一分。","越外險巇防俗事，就中拘檢信人文。","醉乡日月終須覓，去作先生號白云。"]', '诗', 'shi', '', NULL, '遣興 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b39fa18-666a-40d2-81e0-011d806d9eb0', '南海神祠', '南海神祠', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["滄溟八千里，今古畏波濤。","此日征南將，安然渡萬艘。"]', '["滄溟八千里，今古畏波濤。","此日征南將，安然渡万艘。"]', '诗', 'shi', '', NULL, '南海神祠 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f5350f-c2d7-459e-b2fb-9d3694bb5b91', '送春', '送春', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["水淺魚爭躍，花深鳥競啼。","春光看欲盡，判却醉如泥。"]', '["水淺鱼爭躍，花深鸟競啼。","春光看欲尽，判却醉如泥。"]', '诗', 'shi', '', NULL, '送春 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c2fe89-b18a-474a-9fe0-1e9b175bddbf', '海翻', '海翻', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["幾經人事變，又見海濤翻。","徒起如山浪，何曾洗至冤。"]', '["幾經人事变，又见海濤翻。","徒起如山浪，何曾洗至冤。"]', '诗', 'shi', '', NULL, '海翻 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aafd856c-592c-4b32-976f-e8253590db4f', '筇竹杖寄僧', '筇竹杖寄僧', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["堅輕筇竹杖，一枝有九節。","寄與沃洲人，閑步青山月。"]', '["堅轻筇竹杖，一枝有九節。","寄與沃洲人，闲步青山月。"]', '诗', 'shi', '', NULL, '筇竹杖寄僧 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f30b73a4-2d1e-47d5-b8da-bcd58918606d', '遣興', '遣兴', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["把盞非憐酒，持竿不爲魚。","唯應嵇叔夜，似我性慵疎。"]', '["把盞非怜酒，持竿不爲鱼。","唯應嵇叔夜，似我性慵疎。"]', '诗', 'shi', '', NULL, '遣興 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1070066d-2d61-49b6-a324-52bbb1fe452f', '歎征人', '歎征人', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["心堅膽壯箭頭親，十載沙場受苦辛。","力盡路傍行不得，廣張紅斾是何人。"]', '["心堅膽壯箭头親，十載沙場受苦辛。","力尽路傍行不得，廣張紅斾是何人。"]', '诗', 'shi', '', NULL, '歎征人 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad05947-e0c3-4bc8-9a95-cceaf1aa1496', '湘妃廟', '湘妃廟', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["帝舜南巡去不還，二妃幽怨水雲間。","當時珠淚垂多少，直到如今竹尚斑。"]', '["帝舜南巡去不還，二妃幽怨水云间。","當时珠泪垂多少，直到如今竹尚斑。"]', '诗', 'shi', '', NULL, '湘妃廟 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f28b2b78-a4c3-4945-9089-01d7a1397cff', '赴安南却寄台司', '赴安南却寄台司', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["曾驅萬馬上天山，風去雲回頃刻間。","今日海門南面事，莫教還似鳳林關。"]', '["曾驱万马上天山，风去云回頃刻间。","今日海门南面事，莫教還似鳳林关。"]', '诗', 'shi', '', NULL, '赴安南却寄台司 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b48d9b9-045d-41ce-941f-7c851417cf1b', '閨怨', '閨怨', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["人世悲歡不可知，夫君初破黑山歸。","如今又獻征南策，早晚催縫帶號衣。"]', '["人世悲歡不可知，夫君初破黑山归。","如今又獻征南策，早晚催縫带號衣。"]', '诗', 'shi', '', NULL, '閨怨 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9634c6e-0f21-45c0-be2e-d3f46c5c4f79', '馬嵬驛', '马嵬驛', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["玉顏雖掩馬嵬塵，冤氣和煙鎖渭津。","蟬鬢不隨鑾駕去，至今空感往來人。"]', '["玉顏雖掩马嵬塵，冤氣和煙鎖渭津。","蟬鬢不隨鑾駕去，至今空感往来人。"]', '诗', 'shi', '', NULL, '馬嵬驛 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c82f2223-4d9e-4f9d-97c3-bb2cd8e2464d', '宴犒蕃軍有感', '宴犒蕃軍有感', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["蜀地恩留馬嵬哭，煙雨濛濛春草綠。","滿眼由來是舊人，那堪更奏梁州曲。"]', '["蜀地恩留马嵬哭，煙雨濛濛春草綠。","满眼由来是旧人，那堪更奏梁州曲。"]', '诗', 'shi', '', NULL, '宴犒蕃軍有感 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786bc2fb-8f3c-4542-aaf4-ae433bb034ae', '寓懷', '寓懷', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["關山萬里恨難銷，鐵馬金鞭出塞遙。","爲問昔時青海畔，幾人歸到鳳林橋。"]', '["关山万里恨难銷，鐵马金鞭出塞遙。","爲问昔时青海畔，幾人归到鳳林橋。"]', '诗', 'shi', '', NULL, '寓懷 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee09220-97ce-4395-9070-5882289bbd77', '步虛詞', '步虛词', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["青溪道士人不識，上天下天鶴一隻。","洞門深鎖碧窗寒，滴露研朱點周易。"]', '["青溪道士人不識，上天下天鹤一隻。","洞门深鎖碧窗寒，滴露研朱点周易。"]', '诗', 'shi', '', NULL, '步虛詞 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2dd095d-cb87-4690-9ec8-0800d1b445dd', '贈歌者二首 一', '贈歌者二首 一', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["酒滿金船花滿枝，佳人立唱慘愁眉。","一聲直入青雲去，多少悲歡起此時。"]', '["酒满金船花满枝，佳人立唱慘愁眉。","一声直入青云去，多少悲歡起此时。"]', '诗', 'shi', '', NULL, '贈歌者二首 一 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9421c5a1-1fc8-41b7-a551-4f1a1662452b', '贈歌者二首 二', '贈歌者二首 二', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["公子邀歡月滿樓，雙成揭調唱伊州。","便從席上風沙起，直到陽關水盡頭。"]', '["公子邀歡月满楼，雙成揭調唱伊州。","便從席上风沙起，直到陽关水尽头。"]', '诗', 'shi', '', NULL, '贈歌者二首 二 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9db5f7-5fe3-4c6f-a8f0-6e82b026e476', '入蜀', '入蜀', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["萬水千山音信希，空勞魂夢到京畿。","漫天嶺上頻回首，不見虞封淚滿衣。"]', '["万水千山音信希，空勞魂梦到京畿。","漫天嶺上頻回首，不见虞封泪满衣。"]', '诗', 'shi', '', NULL, '入蜀 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80aa6c8-fb6e-43b5-ae01-53943e50721b', '邊城聽角', '邊城听角', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["席箕風起雁聲秋，隴水邊沙滿目愁。","三會五更欲吹盡，不知凡白幾人頭。"]', '["席箕风起雁声秋，隴水邊沙满目愁。","三會五更欲吹尽，不知凡白幾人头。"]', '诗', 'shi', '', NULL, '邊城聽角 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733e517a-10ea-4a37-a48d-d360c693ac9f', '渭川秋望寄右軍王特進', '渭川秋望寄右軍王特進', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["長川終日碧潺湲，知道天河與地連。","憑寄兩行朝闕淚，願隨流入御溝泉。"]', '["长川終日碧潺湲，知道天河與地連。","憑寄兩行朝闕泪，願隨流入御溝泉。"]', '诗', 'shi', '', NULL, '渭川秋望寄右軍王特進 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e080f93-6e4f-4afb-ba86-757dbdcbc9a8', '山亭夏日', '山亭夏日', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["綠樹陰濃夏日長，樓臺倒影入池塘。","水精簾動微風起，滿架薔薇一院香。"]', '["綠樹陰濃夏日长，楼台倒影入池塘。","水精簾动微风起，满架薔薇一院香。"]', '诗', 'shi', '', NULL, '山亭夏日 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dea6615-241c-4ec1-80bb-10feddcb70b2', '蜀路感懷', '蜀路感懷', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["蜀山蒼翠隴雲愁，鑾駕西巡陷幾州。","唯有縈回深澗水，潺湲不改舊時流。"]', '["蜀山蒼翠隴云愁，鑾駕西巡陷幾州。","唯有縈回深澗水，潺湲不改旧时流。"]', '诗', 'shi', '', NULL, '蜀路感懷 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee3519d-27ad-41a3-b39e-6ab52cfcda3a', '殘春遣興', '殘春遣兴', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["畫舸輕橈柳色新，摩訶池上醉青春。","不辭不爲青春醉，只恐鶯花也怪人。"]', '["畫舸轻橈柳色新，摩訶池上醉青春。","不辞不爲青春醉，只恐鶯花也怪人。"]', '诗', 'shi', '', NULL, '殘春遣興 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178f572a-8a1f-4fd9-b649-e924736a5c26', '春日招賓', '春日招賓', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["花枝如火酒如餳，正好狂歌醉復醒。","對酒看花何處好，延和閣下碧筠亭。"]', '["花枝如火酒如餳，正好狂歌醉复醒。","对酒看花何处好，延和閣下碧筠亭。"]', '诗', 'shi', '', NULL, '春日招賓 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47fe808-b223-4f4a-9454-05189c0bf9e2', '過天威徑', '過天威徑', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["豺狼坑盡却朝天，戰馬休嘶瘴嶺煙。","歸路嶮巇今坦蕩，一條千里直如弦。"]', '["豺狼坑尽却朝天，戰马休嘶瘴嶺煙。","归路嶮巇今坦蕩，一條千里直如弦。"]', '诗', 'shi', '', NULL, '過天威徑 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21c8b3f-5963-46fc-94d0-0038ce4146f5', '對花呈幕中', '对花呈幕中', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["海棠初發去春枝，首唱曾題七字詩。","今日能來花下飲，不辭頻把使頭旗。"]', '["海棠初發去春枝，首唱曾題七字诗。","今日能来花下饮，不辞頻把使头旗。"]', '诗', 'shi', '', NULL, '對花呈幕中 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3207970-bcb1-40ac-b261-d6c684038426', '寄題羅浮別業', '寄題羅浮別業', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["不將真性染埃塵，爲有煙霞伴此身。","帶日長江好歸信，博羅山下碧桃春。"]', '["不將真性染埃塵，爲有煙霞伴此身。","带日长江好归信，博羅山下碧桃春。"]', '诗', 'shi', '', NULL, '寄題羅浮別業 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b00723-b38f-4879-a1bd-6a27788b25fd', '塞上曲二首 一', '塞上曲二首 一', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["二年邊戍絕煙塵，一曲河灣萬恨新。","從此鳳林關外事，不知誰是苦心人。"]', '["二年邊戍絕煙塵，一曲河灣万恨新。","從此鳳林关外事，不知誰是苦心人。"]', '诗', 'shi', '', NULL, '塞上曲二首 一 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d90fd07-5124-43b3-a17f-4754f9276027', '塞上曲二首 二', '塞上曲二首 二', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["隴上征夫隴下魂，死生同恨漢將軍。","不知萬里沙場苦，空舉平安火入雲。"]', '["隴上征夫隴下魂，死生同恨漢將軍。","不知万里沙場苦，空舉平安火入云。"]', '诗', 'shi', '', NULL, '塞上曲二首 二 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c538982-162e-42fd-ac20-08498cd00110', '廣陵宴次戲簡幕賓', '廣陵宴次戲簡幕賓', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["一曲狂歌酒百分，蛾眉畫出月爭新。","將軍醉罷無餘事，亂把花枝折贈人。"]', '["一曲狂歌酒百分，蛾眉畫出月爭新。","將軍醉罷無餘事，亂把花枝折贈人。"]', '诗', 'shi', '', NULL, '廣陵宴次戲簡幕賓 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5d3e53-9a73-4553-a3d2-7ffeee15629b', '安南送曹別勑歸朝', '安南送曹別勑归朝', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["雲水蒼茫日欲收，野煙深處鷓鴣愁。","知君萬里朝天去，爲說征南已五秋。"]', '["云水蒼茫日欲收，野煙深处鷓鴣愁。","知君万里朝天去，爲说征南已五秋。"]', '诗', 'shi', '', NULL, '安南送曹別勑歸朝 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4263491d-756a-43fe-9bd9-49e76332184d', '對雪', '对雪', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["六出飛花入戶時，坐看青竹變瓊枝。","如今好上高樓望，蓋盡人間惡路岐。"]', '["六出飞花入戶时，坐看青竹变瓊枝。","如今好上高楼望，蓋尽人间惡路岐。"]', '诗', 'shi', '', NULL, '對雪 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffad3419-a294-49d8-92b0-a6adffbe1ef8', '訪隱者不遇', '訪隐者不遇', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["落花流水認天台，半醉閑吟獨自來。","惆悵仙翁何處去，滿庭紅杏碧桃開。"]', '["落花流水認天台，半醉闲吟独自来。","惆悵仙翁何处去，满庭紅杏碧桃开。"]', '诗', 'shi', '', NULL, '訪隱者不遇 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21a55c7-62db-4611-b1db-639c572d5d36', '赴西川途經虢縣作', '赴西川途經虢縣作', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["亞夫重過柳營門，路指岷峨隔暮雲。","紅額少年遮道拜，殷勤認得舊將軍。"]', '["亞夫重過柳營门，路指岷峨隔暮云。","紅額少年遮道拜，殷勤認得旧將軍。"]', '诗', 'shi', '', NULL, '赴西川途經虢縣作 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('819ac398-4284-447d-89e1-c38fc99c1122', '錦城冩望', '錦城冩望', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["蜀江波影碧悠悠，四望煙花匝郡樓。","不會人家多少錦，春來盡挂樹梢頭。"]', '["蜀江波影碧悠悠，四望煙花匝郡楼。","不會人家多少錦，春来尽挂樹梢头。"]', '诗', 'shi', '', NULL, '錦城冩望 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb3aff7-67fa-4743-b348-98f69f74f7b5', '太公廟', '太公廟', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["青山長在境長新，寂寞持竿一水濱。","及得王師身已老，不知辛苦爲何人。"]', '["青山长在境长新，寂寞持竿一水濱。","及得王師身已老，不知辛苦爲何人。"]', '诗', 'shi', '', NULL, '太公廟 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602c6246-68f9-48e8-be18-4f5b6f7c82b8', '邊方春興', '邊方春兴', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["草色青青柳色濃，玉壺頃酒滿金鐘。","笙歌嘹亮隨風去，知盡關山第幾重。"]', '["草色青青柳色濃，玉壺頃酒满金鐘。","笙歌嘹亮隨风去，知尽关山第幾重。"]', '诗', 'shi', '', NULL, '邊方春興 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d8bfc7-6231-4fe9-9f91-703c3acd0a41', '塞上寄家兄', '塞上寄家兄', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["棣萼分張信使希，幾多鄉淚濕征衣。","笳聲未斷腸先斷，萬里胡天鳥不飛。"]', '["棣萼分張信使希，幾多乡泪濕征衣。","笳声未斷腸先斷，万里胡天鸟不飞。"]', '诗', 'shi', '', NULL, '塞上寄家兄 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c67e5b2e-187a-45ce-8e13-67e6e9b69080', '寫懷二首 一', '寫懷二首 一', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["漁竿消日酒消愁，一醉忘情萬事休。","却恨韓彭興漢室，功成不向五湖遊。"]', '["漁竿消日酒消愁，一醉忘情万事休。","却恨韓彭兴漢室，功成不向五湖游。"]', '诗', 'shi', '', NULL, '寫懷二首 一 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc15ec6-54e0-4998-b3c8-fac7c8d976d4', '寫懷二首 二', '寫懷二首 二', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["花滿西園月滿池，笙歌搖曳畫船移。","如今暗與心相約，不動征旗動酒旗。"]', '["花满西园月满池，笙歌搖曳畫船移。","如今暗與心相約，不动征旗动酒旗。"]', '诗', 'shi', '', NULL, '寫懷二首 二 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d676e4-2c3e-49c7-95bf-a201e40635f8', '池上送春', '池上送春', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["持竿閑坐思沈吟，釣得江鱗出碧潯。","回首看花花欲盡，可憐寥落送春心。"]', '["持竿闲坐思沈吟，釣得江鱗出碧潯。","回首看花花欲尽，可怜寥落送春心。"]', '诗', 'shi', '', NULL, '池上送春 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('443d0a47-5fdd-4f07-9d22-ed1036e805a8', '南征敘懷', '南征敘懷', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["萬里驅兵過海門，此生今日報君恩。","回期直待烽煙靜，不遣征衣有淚痕。"]', '["万里驱兵過海门，此生今日報君恩。","回期直待烽煙静，不遣征衣有泪痕。"]', '诗', 'shi', '', NULL, '南征敘懷 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b09dcc66-784c-4ce3-9e0c-37d70f592e52', '風箏', '风箏', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["夜靜弦聲響碧空，宮商信任往來風。","依稀似曲才堪聽，又被移將別調中。"]', '["夜静弦声响碧空，宮商信任往来风。","依稀似曲才堪听，又被移將別調中。"]', '诗', 'shi', '', NULL, '風箏 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9daa29-9ca8-44c6-85e8-bb5f79503f48', '平流園席上', '平流园席上', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["畫舸搖煙水滿塘，柳絲輕軟小桃香。","却緣龍節爲縈絆，好是狂時不得狂。"]', '["畫舸搖煙水满塘，柳絲轻軟小桃香。","却緣龙節爲縈絆，好是狂时不得狂。"]', '诗', 'shi', '', NULL, '平流園席上 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54bfdbcd-641f-44a9-b587-36b78fb1527b', '聞河中王鐸加都統', '闻河中王鐸加都統', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["煉汞燒鉛四十年，至今猶在藥爐前。","不知子晉緣何事，只學吹簫便得仙。"]', '["煉汞燒鉛四十年，至今猶在藥爐前。","不知子晉緣何事，只学吹簫便得仙。"]', '诗', 'shi', '', NULL, '聞河中王鐸加都統 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cdfe035-5017-406e-ba3f-00885c146743', '句', '句', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["人間無限傷心事，不得尊前折一枝。","滿宮多少承恩者，似有容華妾也無。","滿身珠翠將何用，唯與豪家拂象牀。","何人種得西施花，千古春風開不盡。"]', '["人间無限傷心事，不得尊前折一枝。","满宮多少承恩者，似有容华妾也無。","满身珠翠將何用，唯與豪家拂象牀。","何人種得西施花，千古春风开不尽。"]', '诗', 'shi', '', NULL, '句 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d20122c-fa19-4466-83a8-1435a3d3d16b', '青樓曲', '青楼曲', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["青樓臨大道，一上一回老。","所思終不來，極目傷春草。"]', '["青楼臨大道，一上一回老。","所思終不来，極目傷春草。"]', '诗', 'shi', '', NULL, '青樓曲 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e558955-09fb-4207-8e64-06ad06f69557', '塞下曲', '塞下曲', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["紫塞曉屯兵，黃沙披甲臥。","戰鼓聲未齊，烏鳶已相賀。","燕然山上雲，半是離鄉魂。","衛霍待富貴，豈能無乾坤。"]', '["紫塞晓屯兵，黄沙披甲臥。","戰鼓声未齊，烏鳶已相賀。","燕然山上云，半是離乡魂。","衛霍待富貴，豈能無乾坤。"]', '诗', 'shi', '', NULL, '塞下曲 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('264df1a0-65ce-4b2a-99e2-0d46673957d1', '山村曉思', '山村晓思', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["開門省禾黍，鄰翁水頭住。","今朝南澗波，昨夜西川雨。","牧童披短蓑，腰笛期煙渚。","不問水邊人，騎牛傍山去。"]', '["开门省禾黍，鄰翁水头住。","今朝南澗波，昨夜西川雨。","牧童披短蓑，腰笛期煙渚。","不问水邊人，騎牛傍山去。"]', '诗', 'shi', '', NULL, '山村曉思 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2802b5a3-9262-4bd3-a787-7aef6a082930', '馬嵬驛', '马嵬驛', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["常經馬嵬驛，見說坡前客。","一從屠貴妃，生女愁傾國。","是日芙蓉花，不如秋草色。","當時嫁匹夫，不妨得頭白。"]', '["常經马嵬驛，见说坡前客。","一從屠貴妃，生女愁傾国。","是日芙蓉花，不如秋草色。","當时嫁匹夫，不妨得头白。"]', '诗', 'shi', '', NULL, '馬嵬驛 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6ece46-435b-4dcd-8d64-ff59b3de06be', '苦辛吟', '苦辛吟', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["壠上扶犂兒，手種腹長飢。","窗下拋梭女，手織身無衣。","我願燕趙姝，化爲嫫母姿。","一笑不值錢，自然家國肥。"]', '["壠上扶犂兒，手種腹长飢。","窗下拋梭女，手织身無衣。","我願燕趙姝，化爲嫫母姿。","一笑不值錢，自然家国肥。"]', '诗', 'shi', '', NULL, '苦辛吟 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21e1277-9995-4dd6-8c6b-c923aa666ce6', '野蠶', '野蠶', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["野蠶食青桑，吐絲亦成繭。","無功及生人，何異偷飽暖。","我願均爾絲，化爲寒者衣。"]', '["野蠶食青桑，吐絲亦成繭。","無功及生人，何異偷飽暖。","我願均爾絲，化爲寒者衣。"]', '诗', 'shi', '', NULL, '野蠶 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce56c3eb-f35e-421d-b586-145b7600f63f', '秦原覽古', '秦原覽古', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["耕者戮力地，龍虎曾角逐。","火德道將亨，夜逢虵母哭。","昔日望夷宮，是處尋桑穀。","漢祖竟爲龍，趙高徒指鹿。","當時行路人，已合傷心目。","漢祚又千年，秦原草還綠。"]', '["耕者戮力地，龙虎曾角逐。","火德道將亨，夜逢虵母哭。","昔日望夷宮，是处尋桑穀。","漢祖竟爲龙，趙高徒指鹿。","當时行路人，已合傷心目。","漢祚又千年，秦原草還綠。"]', '诗', 'shi', '', NULL, '秦原覽古 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0036842-0804-429f-bc72-daeaaa6709eb', '古宴曲', '古宴曲', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["雉扇合蓬萊，朝車回紫陌。","重門集嘶馬，言宴金張宅。","燕娥奉巵酒，低鬟若無力。","十戶手胼胝，鳳凰釵一隻。","高樓齊下視，日照羅衣色。","笑指負薪人，不信生中國。"]', '["雉扇合蓬萊，朝车回紫陌。","重门集嘶马，言宴金張宅。","燕娥奉巵酒，低鬟若無力。","十戶手胼胝，鳳凰釵一隻。","高楼齊下視，日照羅衣色。","笑指負薪人，不信生中国。"]', '诗', 'shi', '', NULL, '古宴曲 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f4eb8f-4364-48e9-8ff5-2f99a9803e3d', '南越謠', '南越謠', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["迢迢東南天，巨浸無津壖。","雄風卷昏霧，干戈滿樓船。","此時尉佗心，兒童待幽燕。","三寸陸賈舌，萬里漢山川。","若令交趾貨，盡生虞芮田。","天意苟如此，遐人誰肯憐。"]', '["迢迢东南天，巨浸無津壖。","雄风卷昏霧，干戈满楼船。","此时尉佗心，兒童待幽燕。","三寸陸賈舌，万里漢山川。","若令交趾貨，尽生虞芮田。","天意苟如此，遐人誰肯怜。"]', '诗', 'shi', '', NULL, '南越謠 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94269318-57e2-4c9f-841b-7e63dcb70c56', '述己歎', '述己歎', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["不長不成人，及長老逼身。","履善本求樂，及善尤苦辛。","如何幽幷兒，一箭取功勳。"]', '["不长不成人，及长老逼身。","履善本求乐，及善尤苦辛。","如何幽幷兒，一箭取功勳。"]', '诗', 'shi', '', NULL, '述己歎 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc89556d-e5f8-4b43-8243-f01c5e2bb69f', '遼陽行', '遼陽行', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["遼陽在何處，妾欲隨君去。","義合齊死生，本不誇機杼。","誰能守空閨，虛問遼陽路。"]', '["遼陽在何处，妾欲隨君去。","義合齊死生，本不誇機杼。","誰能守空閨，虛问遼陽路。"]', '诗', 'shi', '', NULL, '遼陽行 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb10c918-bd71-43a4-8adb-6f715af803d7', '旅館秋思', '旅館秋思', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["旅館坐孤寂，出門成苦吟。","何事覺歸晚，黃花秋意深。","寒蝶戀衰草，軫我離鄉心。","更見庭前樹，南枝巢宿禽。"]', '["旅館坐孤寂，出门成苦吟。","何事覺归晚，黄花秋意深。","寒蝶戀衰草，軫我離乡心。","更见庭前樹，南枝巢宿禽。"]', '诗', 'shi', '', NULL, '旅館秋思 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1358844c-25c3-4a94-9607-ae3c547a0e99', '長城', '长城', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["秦皇豈無德，蒙氏非不武。","豈將版築功，萬里遮胡虜。","團沙世所難，作壘明知苦。","死者倍堪傷，僵屍猶抱杵。","十年居上郡，四海誰爲主。","縱使骨爲塵，冤名不入土。"]', '["秦皇豈無德，蒙氏非不武。","豈將版築功，万里遮胡虜。","團沙世所难，作壘明知苦。","死者倍堪傷，僵屍猶抱杵。","十年居上郡，四海誰爲主。","縱使骨爲塵，冤名不入土。"]', '诗', 'shi', '', NULL, '長城 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff71821-a614-4df8-bb78-2be7e127770b', '田翁歎', '田翁歎', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["手植千樹桑，文杏作中梁。","頻年徭役重，盡屬富家郎。","富家田業廣，用此買金章。","昨日門前過，軒車滿垂楊。","歸來說向家，兒孫竟咨嗟。","不見千樹桑，一浦芙蓉花。"]', '["手植千樹桑，文杏作中梁。","頻年徭役重，尽屬富家郎。","富家田業廣，用此買金章。","昨日门前過，軒车满垂楊。","归来说向家，兒孫竟咨嗟。","不见千樹桑，一浦芙蓉花。"]', '诗', 'shi', '', NULL, '田翁歎 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b33fb162-b0f7-48bb-9763-cf8d78c14052', '沙場夜', '沙場夜', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["城上更聲發，城下杵聲歇。","征人燒斷蓬，對泣沙中月。","耕牛朝輓甲，戰馬夜銜鐵。","士卒浣戎衣，交河水爲血。","輕裘兩都客，洞房愁宿別。","何況遠辭家，生死猶未決。"]', '["城上更声發，城下杵声歇。","征人燒斷蓬，对泣沙中月。","耕牛朝輓甲，戰马夜銜鐵。","士卒浣戎衣，交河水爲血。","轻裘兩都客，洞房愁宿別。","何況远辞家，生死猶未決。"]', '诗', 'shi', '', NULL, '沙場夜 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc493ab-8564-48e6-9edf-e058fc9e01e1', '里中女', '里中女', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["吾聞池中魚，不識海水深。","吾聞桑下女，不識華堂陰。","貧窗苦機杼，富家鳴杵砧。","天與雙明眸，只教識蒿簪。","徒惜越娃貌，亦蘊韓娥音。","珠玉不到眼，遂無奢侈心。","豈知趙飛燕，滿髻釵黃金。"]', '["吾闻池中鱼，不識海水深。","吾闻桑下女，不識华堂陰。","貧窗苦機杼，富家鳴杵砧。","天與雙明眸，只教識蒿簪。","徒惜越娃貌，亦蘊韓娥音。","珠玉不到眼，遂無奢侈心。","豈知趙飞燕，满髻釵黄金。"]', '诗', 'shi', '', NULL, '里中女 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad228a0-cdf4-4e0c-affd-ca65e5f95e0f', '寒食', '寒食', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["二月野中芳，凡花亦能香。","素娥哭新塚，樵柯鳴柔桑。","田父引黃犬，尋狐上高岡。","墳前呼犬歸，不知頭似霜。"]', '["二月野中芳，凡花亦能香。","素娥哭新塚，樵柯鳴柔桑。","田父引黄犬，尋狐上高岡。","墳前呼犬归，不知头似霜。"]', '诗', 'shi', '', NULL, '寒食 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f492ab-32e7-4b66-8f7a-9558b15901cd', '邊遊錄戍卒言', '邊游錄戍卒言', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["二十屬盧龍，三十防沙漠。","平生愛功業，不覺從軍惡。","今來客鬢改，知學彎弓錯。","赤肉痛金瘡，他人成衛霍。","目斷望君門，君門苦寥廓。"]', '["二十屬盧龙，三十防沙漠。","平生愛功業，不覺從軍惡。","今来客鬢改，知学彎弓錯。","赤肉痛金瘡，他人成衛霍。","目斷望君门，君门苦寥廓。"]', '诗', 'shi', '', NULL, '邊遊錄戍卒言 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a95afce-e957-4bfb-b835-d3c50e317096', '古征戰', '古征戰', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["高峰凌青冥，深穴萬丈坑。","皇天自山谷，焉得人心平。","齊魯足兵甲，燕趙多娉婷。","仍聞麗水中，日日黃金生。","苟非夷齊心，豈得無戰爭。"]', '["高峰凌青冥，深穴万丈坑。","皇天自山谷，焉得人心平。","齊魯足兵甲，燕趙多娉婷。","仍闻丽水中，日日黄金生。","苟非夷齊心，豈得無戰爭。"]', '诗', 'shi', '', NULL, '古征戰 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ffc2d1-9cb9-4521-a86d-885c5a99fe0f', '山村叟', '山村叟', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["古鑿巖居人，一廛稱有產。","雖霑巾覆形，不及貴門犬。","驅牛耕白石，課女經黃繭。","歲暮霜霰濃，畫樓人飽煖。"]', '["古鑿巖居人，一廛稱有產。","雖霑巾覆形，不及貴门犬。","驱牛耕白石，課女經黄繭。","歲暮霜霰濃，畫楼人飽煖。"]', '诗', 'shi', '', NULL, '山村叟 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3146349-87b7-463f-994b-ab5fea5ca2f3', '戍客南歸', '戍客南归', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["北別黃榆塞，南歸白雲鄉。","孤舟下彭蠡，楚月沈滄浪。","爲子惜功業，滿身刀箭瘡。","莫渡汨羅水，回君忠孝腸。"]', '["北別黄榆塞，南归白云乡。","孤舟下彭蠡，楚月沈滄浪。","爲子惜功業，满身刀箭瘡。","莫渡汨羅水，回君忠孝腸。"]', '诗', 'shi', '', NULL, '戍客南歸 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fde4fc-7743-4c81-a6d7-31a1716ebe2b', '經館娃宮', '經館娃宮', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["館娃宮畔顧，國變生嬌妒。","句踐膽未嘗，夫差心已誤。","吳亡甘已矣，越勝今何處？","當時二國君，一種江邊墓。"]', '["館娃宮畔顧，国变生嬌妒。","句踐膽未嘗，夫差心已誤。","吳亡甘已矣，越勝今何处？","當时二国君，一種江邊墓。"]', '诗', 'shi', '', NULL, '經館娃宮 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810c5448-44f8-4bba-a88e-d529a5bff9bb', '村居晏起', '村居晏起', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["村舍少聞事，日高猶閉關。","起來花滿地，戴勝鳴桑間。","居安即永業，何者爲故山。","朱門與蓬戶，六十頭盡斑。"]', '["村舍少闻事，日高猶閉关。","起来花满地，戴勝鳴桑间。","居安即永業，何者爲故山。","朱门與蓬戶，六十头尽斑。"]', '诗', 'shi', '', NULL, '村居晏起 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7003512-b583-40f4-ab9b-87a9bd301747', '感懷', '感懷', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["採薇易爲山，何必登首陽。","濯纓易爲水，何必泛滄浪。","貴崇已難慕，諂笑何所長。","東堂桂欲空，猶有收螢光。"]', '["採薇易爲山，何必登首陽。","濯纓易爲水，何必泛滄浪。","貴崇已难慕，諂笑何所长。","东堂桂欲空，猶有收螢光。"]', '诗', 'shi', '', NULL, '感懷 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43b187c7-f7e5-45be-a019-bf2a24abff7d', '金谷感懷', '金谷感懷', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["黃金驕石崇，與晉爭國力。","更欲住人間，一日買不得。","行爲忠信主，身是文章宅。","四者俱不聞，空傳墮樓客。"]', '["黄金驕石崇，與晉爭国力。","更欲住人间，一日買不得。","行爲忠信主，身是文章宅。","四者俱不闻，空傳墮楼客。"]', '诗', 'shi', '', NULL, '金谷感懷 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bc1ba9b-cac7-47cd-9d46-8902d9ccec4a', '恨從軍', '恨從軍', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["不嫁白衫兒，愛君新紫衣。","早知遽相別，何用假光輝。","已聞都萬騎，又道出重圍。","一軸金裝字，致君終不歸。"]', '["不嫁白衫兒，愛君新紫衣。","早知遽相別，何用假光輝。","已闻都万騎，又道出重圍。","一軸金裝字，致君終不归。"]', '诗', 'shi', '', NULL, '恨從軍 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b693a60-bbd9-472f-9100-2b6751f69be5', '燒金曲', '燒金曲', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["天壽畏不永，燒金希長年。","積土培枯根，自謂松柏堅。","南陌試腰褭，西樓歌嬋娟。","豈知蔓草中，日日開夜泉。"]', '["天壽畏不永，燒金希长年。","積土培枯根，自謂松柏堅。","南陌試腰褭，西楼歌嬋娟。","豈知蔓草中，日日开夜泉。"]', '诗', 'shi', '', NULL, '燒金曲 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb5bcbb-529b-4ac7-affc-276e35d993eb', '子從軍', '子從軍', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["男作鄉中丁，女作鄉男婦。","南村與北里，日日見父母。","豈似從軍兒，一去便白首。","何當鑄劍戟，盡得丁男力。"]', '["男作乡中丁，女作乡男婦。","南村與北里，日日见父母。","豈似從軍兒，一去便白首。","何當鑄劍戟，尽得丁男力。"]', '诗', 'shi', '', NULL, '子從軍 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6e3b0b-7c60-4197-9866-cee1a5c67915', '越溪女', '越溪女', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["會稽山上雲，化作越溪人。","枉破吳王國，徒爲西子身。","江邊浣紗伴，黃金扼雙腕。","倏忽不相期，思傾趙飛燕。","妾家基業薄，空有如花面。","嫁盡綠窗人，獨自盤金線。"]', '["會稽山上云，化作越溪人。","枉破吳王国，徒爲西子身。","江邊浣紗伴，黄金扼雙腕。","倏忽不相期，思傾趙飞燕。","妾家基業薄，空有如花面。","嫁尽綠窗人，独自盤金線。"]', '诗', 'shi', '', NULL, '越溪女 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a833a62-ca8d-456f-9463-05d32867a616', '巫山高', '巫山高', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["何山無朝雲，彼雲亦悠揚。","何山無暮雨，彼雨亦蒼茫。","宋玉恃才者，憑虛構高唐。","自垂文賦名，荒淫歸楚襄。","峨峨十二峰，永作妖鬼鄉。"]', '["何山無朝云，彼云亦悠揚。","何山無暮雨，彼雨亦蒼茫。","宋玉恃才者，憑虛構高唐。","自垂文賦名，荒淫归楚襄。","峨峨十二峰，永作妖鬼乡。"]', '诗', 'shi', '', NULL, '巫山高 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ad0d83a-93c2-4717-b38b-737df0e7877c', '織素謠', '织素謠', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["貧女苦筋力，繰絲夜夜織。","萬梭爲一素，世重韓娥色。","五侯初買笑，建章方落籍。","一曲古涼州，六親長血食。","勸爾畫長眉，學歌飽親戚。"]', '["貧女苦筋力，繰絲夜夜织。","万梭爲一素，世重韓娥色。","五侯初買笑，建章方落籍。","一曲古涼州，六親长血食。","勸爾畫长眉，学歌飽親戚。"]', '诗', 'shi', '', NULL, '織素謠 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974282dd-e9b9-4dfa-87d7-577fd834958b', '擬古諷', '擬古諷', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["洛陽大道傍，甲第何深邃。","南畝無一廛，東園有餘地。","春溪化桃李，秋沼生荷芰。","草木本無情，此時如有爲。","旱苗當壟死，流水資嘉致。","餘心甘至愚，不會皇天意。"]', '["洛陽大道傍，甲第何深邃。","南畝無一廛，东园有餘地。","春溪化桃李，秋沼生荷芰。","草木本無情，此时如有爲。","旱苗當壟死，流水資嘉致。","餘心甘至愚，不會皇天意。"]', '诗', 'shi', '', NULL, '擬古諷 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('530aec41-f1d5-4fda-9bab-a72bf1888fb9', '贈太行開路者', '贈太行开路者', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["手斸太行山，心齊太行巔。","斸盡太行險，君心更摩天。","何如回苦辛，自鑿東臯田。"]', '["手斸太行山，心齊太行巔。","斸尽太行險，君心更摩天。","何如回苦辛，自鑿东臯田。"]', '诗', 'shi', '', NULL, '贈太行開路者 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6eea2ba-d150-48c1-a2af-cd15464b0167', '戍卒傷春', '戍卒傷春', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["連年戍邊塞，過却芳菲節。","東風氣力盡，不減陰山雪。","蕭條柳一株，南枝葉微發。","爲帶故鄉情，依依籍攀折。","晚風吹磧沙，夜淚啼鄉月。","凌煙閣上人，未必皆忠烈。"]', '["連年戍邊塞，過却芳菲節。","东风氣力尽，不減陰山雪。","蕭條柳一株，南枝葉微發。","爲带故乡情，依依籍攀折。","晚风吹磧沙，夜泪啼乡月。","凌煙閣上人，未必皆忠烈。"]', '诗', 'shi', '', NULL, '戍卒傷春 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ceb4435-be30-4af0-95ec-b02c497a41b7', '', '', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["長聞鄉人語，此家勝良賈。","骨肉化飢魂，倉中有飽鼠。","青春滿桑柘，旦夕鳴機杼。","秋風一夜來，累累聞砧杵。","西鄰有原憲，蓬蒿遶環堵。","自樂固窮心，天意在何處？","當門見堆子，已作桑田主。","安得四海中，盡爲虞芮土。"]', '["长闻乡人語，此家勝良賈。","骨肉化飢魂，倉中有飽鼠。","青春满桑柘，旦夕鳴機杼。","秋风一夜来，累累闻砧杵。","西鄰有原憲，蓬蒿遶环堵。","自乐固窮心，天意在何处？","當门见堆子，已作桑田主。","安得四海中，尽爲虞芮土。"]', '诗', 'shi', '', NULL, ' 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e9e3c2a-b93f-48de-9046-5581407a9572', '早發', '早發', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["綠野含曙光，東北雲如茜。","栖鴉林際起，落月水中見。","此身何自苦，日日凌霜霰。","流蘇帳裏人，猶在陽臺畔。"]', '["綠野含曙光，东北云如茜。","栖鴉林際起，落月水中见。","此身何自苦，日日凌霜霰。","流蘇帳裏人，猶在陽台畔。"]', '诗', 'shi', '', NULL, '早發 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4176ba2a-a170-47e3-b212-12980171fbc9', '季夏逢朝客', '季夏逢朝客', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["滻水桃李熟，杜曲芙蓉老。","九天休沐歸，腰玉垂楊道。","避路迴綺羅，迎風嘶騕褭。","豈知山谷中，日日吹瑤草。"]', '["滻水桃李熟，杜曲芙蓉老。","九天休沐归，腰玉垂楊道。","避路迴綺羅，迎风嘶騕褭。","豈知山谷中，日日吹瑤草。"]', '诗', 'shi', '', NULL, '季夏逢朝客 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb379fbb-1d17-48d7-87b4-739b43faa1f4', '隴頭水', '隴头水', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["行人何徬徨，隴頭水嗚咽。","寒沙戰鬼愁，白骨風霜切。","薄日朦朧秋，怨氣陰雲結。","殺成邊將名，名著生靈滅。"]', '["行人何徬徨，隴头水嗚咽。","寒沙戰鬼愁，白骨风霜切。","薄日朦朧秋，怨氣陰云結。","殺成邊將名，名著生靈滅。"]', '诗', 'shi', '', NULL, '隴頭水 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48806f66-7d46-4345-902a-33d66a2d5b6c', '古別離 一', '古別離 一', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["入室少情意，出門多路岐。","黃鶴有歸日，蕩子無還時。","人誰無分命，妾身何太奇。","君爲東南風，妾作西北枝。","青樓鄰里婦，終年畫長眉。","自倚對良匹，笑妾空羅幃。"]', '["入室少情意，出门多路岐。","黄鹤有归日，蕩子無還时。","人誰無分命，妾身何太奇。","君爲东南风，妾作西北枝。","青楼鄰里婦，終年畫长眉。","自倚对良匹，笑妾空羅幃。"]', '诗', 'shi', '', NULL, '古別離 一 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535ec7d2-ea81-4944-9f6d-a2614bfb8f05', '古別離 二', '古別離 二', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["郎本東家兒，妾本西家女。","對門中道間，終謂無離阻。","豈知中道間，遣作空閨主。","自是愛封侯，非關備胡虜。"]', '["郎本东家兒，妾本西家女。","对门中道间，終謂無離阻。","豈知中道间，遣作空閨主。","自是愛封侯，非关備胡虜。"]', '诗', 'shi', '', NULL, '古別離 二 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e062ef-7e73-4dfb-b00d-21f9662b0a88', '擬古意', '擬古意', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["白玉若無玷，花顏須及時。","國色久在室，良媒亦生疑。","鴉鬟未成髻，鸞鏡徒相知。","翻慙效顰者，却笑從人遲。"]', '["白玉若無玷，花顏須及时。","国色久在室，良媒亦生疑。","鴉鬟未成髻，鸾镜徒相知。","翻慙效顰者，却笑從人遲。"]', '诗', 'shi', '', NULL, '擬古意 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae3a4a1-0edf-4f3b-b76e-a77132d06fb4', '隴頭吟', '隴头吟', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["借問隴頭水，終年恨何事。","深疑嗚咽聲，中有征人淚。","自古蘊長策，況我非才智。","無計謝潺湲，一宵空不寐。"]', '["借问隴头水，終年恨何事。","深疑嗚咽声，中有征人泪。","自古蘊长策，況我非才智。","無計謝潺湲，一宵空不寐。"]', '诗', 'shi', '', NULL, '隴頭吟 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de826691-3742-4231-a773-e1f4c8b49eee', '思歸引', '思归引', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["不耕南畝田，爲愛東堂桂。","身同樹上花，一落又經歲。","交親日相薄，知己恩潛替。","日開十二門，自是無歸計。"]', '["不耕南畝田，爲愛东堂桂。","身同樹上花，一落又經歲。","交親日相薄，知己恩潛替。","日开十二门，自是無归計。"]', '诗', 'shi', '', NULL, '思歸引 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b4c915-7411-47eb-9854-be1e5e4e23e9', '秦富人', '秦富人', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["高高起華堂，遠遠引流水。","糞土視金珍，猶嫌未奢侈。","陋巷滿蓬蒿，誰憐有顏子。"]', '["高高起华堂，远远引流水。","糞土視金珍，猶嫌未奢侈。","陋巷满蓬蒿，誰怜有顏子。"]', '诗', 'shi', '', NULL, '秦富人 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98c78c2e-81ba-45dc-9d4c-6134393d5896', '對花', '对花', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["花開蝶滿枝，花落蝶還稀。","惟有舊巢燕，主人貧亦歸。"]', '["花开蝶满枝，花落蝶還稀。","惟有旧巢燕，主人貧亦归。"]', '诗', 'shi', '', NULL, '對花 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d2dfaf-a7b1-4326-a49e-825250bcae08', '宮怨', '宮怨', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["妾家望江口，少年家財厚。","臨江起珠樓，不賣文君酒。","當年樂貞獨，巢燕時爲友。","父兄未許人，畏妾事姑舅。","西牆鄰宋玉，窺見妾眉宇。","一旦及天聰，恩光生戶牖。","謂言入漢宮，富貴可長久。","君王縱有情，不奈陳皇后。","誰憐頰似桃，孰知腰勝柳。","今日在長門，從來不如醜。"]', '["妾家望江口，少年家財厚。","臨江起珠楼，不賣文君酒。","當年乐貞独，巢燕时爲友。","父兄未許人，畏妾事姑舅。","西牆鄰宋玉，窺见妾眉宇。","一旦及天聰，恩光生戶牖。","謂言入漢宮，富貴可长久。","君王縱有情，不奈陳皇后。","誰怜頰似桃，孰知腰勝柳。","今日在长门，從来不如醜。"]', '诗', 'shi', '', NULL, '宮怨 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b3869ad-76b6-4b2e-b8fb-a3caf55296c2', '登越王樓即事', '登越王楼即事', 'c3d2b481-c32b-4711-80f1-0894f3642b3a', '唐', '["危樓送遠目，信美奈鄉情。","轉岸孤舟疾，銜山落照明。","蕭條看草色，惆悵認江聲。","誰會登臨恨，從軍白髮生。"]', '["危楼送远目，信美奈乡情。","轉岸孤舟疾，銜山落照明。","蕭條看草色，惆悵認江声。","誰會登臨恨，從軍白髮生。"]', '诗', 'shi', '', NULL, '登越王樓即事 牛徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be6484b-02ec-4f07-a451-7651b94479b8', '及第後寄梁燭處士', '及第後寄梁燭处士', 'e2cf90e2-75f7-4939-8905-16fa6b991db8', '唐', '["繡轂尋芳許史家，獨將羈事達江沙。","十年辛苦一枝桂，二月豔陽千樹花。","鵬化四溟歸碧落，鶴棲三島接青霞。","同袍不得同遊翫，今對春風日又斜。"]', '["繡轂尋芳許史家，独將羈事達江沙。","十年辛苦一枝桂，二月豔陽千樹花。","鵬化四溟归碧落，鹤棲三島接青霞。","同袍不得同游翫，今对春风日又斜。"]', '诗', 'shi', '', NULL, '及第後寄梁燭處士 伊璠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11850107-8081-40f9-a114-73283fa83662', '春詩', '春诗', 'f595a6a9-07a8-438e-9f43-09ca077b2ce1', '唐', '["南國韶光早，春風送臘來。","水堤煙報柳，山寺雪驚梅。","練色鋪江晚，潮聲逐渚迴。"]', '["南国韶光早，春风送臘来。","水堤煙報柳，山寺雪驚梅。","練色鋪江晚，潮声逐渚迴。"]', '诗', 'shi', '', NULL, '春詩 蕭遘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c418e3-bc6c-428f-a4b1-937f9ca8749b', '和王侍中謁張惡子廟', '和王侍中謁張惡子廟', 'f595a6a9-07a8-438e-9f43-09ca077b2ce1', '唐', '["青骨祀吳誰讓德，紫華居越亦知名。","未聞一劒傳唐主，長擁千山護蜀城。","斬馬威稜應掃蕩，截蛟鋒刃俟昇平。","酇侯爲國親簫鼓，堂上神籌更布兵。"]', '["青骨祀吳誰讓德，紫华居越亦知名。","未闻一劒傳唐主，长擁千山護蜀城。","斬马威稜應掃蕩，截蛟鋒刃俟昇平。","酇侯爲国親簫鼓，堂上神籌更布兵。"]', '诗', 'shi', '', NULL, '和王侍中謁張惡子廟 蕭遘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fe3d88-fe52-4d0e-8431-2ff060e5c20b', '成都', '成都', 'f595a6a9-07a8-438e-9f43-09ca077b2ce1', '唐', '["月曉已開花市合，江平偏見竹簰多。","好教載取芳菲樹，剩照岷天瑟瑟波。"]', '["月晓已开花市合，江平偏见竹簰多。","好教載取芳菲樹，剩照岷天瑟瑟波。"]', '诗', 'shi', '', NULL, '成都 蕭遘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d731bc-f232-43d7-9f3e-744e8ccbff38', '句', '句', 'f595a6a9-07a8-438e-9f43-09ca077b2ce1', '唐', '["吾家九葉相，盡繼明時出。"]', '["吾家九葉相，尽繼明时出。"]', '诗', 'shi', '', NULL, '句 蕭遘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0269e415-c1de-43dc-a9a4-02c0fa36b6df', '策試夜潛紀長句於都堂西南隅 一', '策試夜潛紀长句於都堂西南隅 一', '3f44f109-c21c-48c8-a100-57621a249eab', '唐', '["褒衣博帶滿塵埃，獨自都堂納卷回。","蓬巷幾時聞吉語，棘籬何日免重來。","三條燭盡鐘初動，九轉丹成鼎未開。","殘月漸低人擾擾，不知誰是謫仙才。"]', '["褒衣博带满塵埃，独自都堂納卷回。","蓬巷幾时闻吉語，棘籬何日免重来。","三條燭尽鐘初动，九轉丹成鼎未开。","殘月漸低人擾擾，不知誰是謫仙才。"]', '诗', 'shi', '', NULL, '策試夜潛紀長句於都堂西南隅 一 韋承貽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('155f34b1-c4c0-42b4-b454-cc8e165f361c', '策試夜潛紀長句於都堂西南隅 二', '策試夜潛紀长句於都堂西南隅 二', '3f44f109-c21c-48c8-a100-57621a249eab', '唐', '["白蓮千朵照廊明，一片昇平雅頌聲。","才唱第三條燭盡，南宮風月畫難成。"]', '["白蓮千朵照廊明，一片昇平雅頌声。","才唱第三條燭尽，南宮风月畫难成。"]', '诗', 'shi', '', NULL, '策試夜潛紀長句於都堂西南隅 二 韋承貽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa92e43-576e-490e-a28d-92e2cf350447', '詔放雲南子弟還國', '詔放云南子弟還国', '3fc26910-22af-4c18-877c-a3809a49e521', '唐', '["德被陪臣子，仁垂聖主恩。","雕題辭鳳闕，丹服出金門。","有澤沾殊俗，無征及獷𤟤。","銅梁分漢土，玉壘駕鸞軒。","瘴嶺蠶叢盛，巴江越嶲垠。","萬方同感化，豈獨自南蕃。"]', '["德被陪臣子，仁垂聖主恩。","雕題辞鳳闕，丹服出金门。","有澤沾殊俗，無征及獷𤟤。","銅梁分漢土，玉壘駕鸾軒。","瘴嶺蠶叢盛，巴江越嶲垠。","万方同感化，豈独自南蕃。"]', '诗', 'shi', '', NULL, '詔放雲南子弟還國 鄭洪業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89980d8a-114b-430e-a46d-6c49a846bfff', '中秋夜思鄭延美有作', '中秋夜思鄭延美有作', '694512d1-92ac-46e5-9b98-1b99e86e3b28', '唐', '["中秋中夜月，世說慴妖精。","顧兔雲初蔽，長虵誰與勍。","未追良友翫，安用玉輪盈。","此意人誰喻，裁時穿禁城。"]', '["中秋中夜月，世说慴妖精。","顧兔云初蔽，长虵誰與勍。","未追良友翫，安用玉輪盈。","此意人誰喻，裁时穿禁城。"]', '诗', 'shi', '', NULL, '中秋夜思鄭延美有作 孫緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7152d142-0875-4275-82dd-ae794b842b01', '清曉捲簾', '清晓捲簾', 'aac02a44-d7f0-4da7-acc0-98790ff9546e', '唐', '["清曉意未愜，捲簾時一吟。","檻虛花氣密，地暖竹聲深。","秀色還朝暮，浮雲自古今。","石泉驚已躍，會可洗幽心。"]', '["清晓意未愜，捲簾时一吟。","檻虛花氣密，地暖竹声深。","秀色還朝暮，浮云自古今。","石泉驚已躍，會可洗幽心。"]', '诗', 'shi', '', NULL, '清曉捲簾 歐陽玭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7f43b4c-9110-4da1-9b5f-8301a17ac78f', '巴陵', '巴陵', 'aac02a44-d7f0-4da7-acc0-98790ff9546e', '唐', '["孤城向夕原，春入景初暄。","綠樹低官舍，青山在縣門。","樓臺疑結蜃，枕席更聞猨。","客路何曾定，棲遲欲斷魂。"]', '["孤城向夕原，春入景初暄。","綠樹低官舍，青山在縣门。","楼台疑結蜃，枕席更闻猨。","客路何曾定，棲遲欲斷魂。"]', '诗', 'shi', '', NULL, '巴陵 歐陽玭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0e4795b-9d6d-4bbf-8555-ea7b6372adee', '榆溪道上', '榆溪道上', 'aac02a44-d7f0-4da7-acc0-98790ff9546e', '唐', '["初日在斜溪，山雲片片低。","鄉愁夢裏失，馬色望中迷。","澗底淒泉氣，巖前遍綠荑。","非關秦塞去，無事候晨雞。"]', '["初日在斜溪，山云片片低。","乡愁梦裏失，马色望中迷。","澗底淒泉氣，巖前遍綠荑。","非关秦塞去，無事候晨雞。"]', '诗', 'shi', '', NULL, '榆溪道上 歐陽玭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d7b11d-ff01-4218-9d09-d7d04ddfc763', '新嶺臨眺寄連總進士', '新嶺臨眺寄連總進士', 'aac02a44-d7f0-4da7-acc0-98790ff9546e', '唐', '["關勢遙臨海，峰巒半入雲。","煙中獨鳥下，潭上雜花熏。","寄遠悲春草，登臨憶使君。","此時還極目，離思更紛紛。"]', '["关勢遙臨海，峰巒半入云。","煙中独鸟下，潭上杂花熏。","寄远悲春草，登臨憶使君。","此时還極目，離思更紛紛。"]', '诗', 'shi', '', NULL, '新嶺臨眺寄連總進士 歐陽玭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399024aa-e7c2-474f-b87f-b4f2389c586f', '幽軒', '幽軒', 'aac02a44-d7f0-4da7-acc0-98790ff9546e', '唐', '["幽軒斜映山，空澗復潺潺。","重疊巖巒趣，遙來窗戶間。","桃花飄岫幌，燕子語松關。","衣桁侵池翠，階痕露蘚斑。","臨風清瑟奏，對客白雲閑。","眷戀青春色，含毫俯碧灣。"]', '["幽軒斜映山，空澗复潺潺。","重叠巖巒趣，遙来窗戶间。","桃花飄岫幌，燕子語松关。","衣桁侵池翠，階痕露蘚斑。","臨风清瑟奏，对客白云闲。","眷戀青春色，含毫俯碧灣。"]', '诗', 'shi', '', NULL, '幽軒 歐陽玭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e4da94-1edb-406a-be15-b2f252e3a727', '社日村居', '社日村居', '77c5d63b-d6d7-402e-bf09-0c768c2780de', '唐', '["鵝湖山下稻粱肥，豚穽雞棲對掩扉。","桑拓影斜春社散，家家扶得醉人歸。"]', '["鵝湖山下稻粱肥，豚穽雞棲对掩扉。","桑拓影斜春社散，家家扶得醉人归。"]', '诗', 'shi', '', NULL, '社日村居 張演 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('023db556-73b5-4232-9168-66b400036a46', '弔孟昌圖', '弔孟昌圖', '9d3e16d2-e598-48a7-a2fa-0d42735495da', '唐', '["一章何罪死何名，投水惟君與屈平。","從此蜀江煙月夜，杜鵑應作兩般聲。"]', '["一章何罪死何名，投水惟君與屈平。","從此蜀江煙月夜，杜鵑應作兩般声。"]', '诗', 'shi', '', NULL, '弔孟昌圖 裴澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b43f852-674c-4ff7-9d2f-6c1e5f07994b', '婕妤怨', '婕妤怨', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["讒謗潛來起百憂，朝承恩寵暮仇讎。","火燒白玉非因玷，霜剪紅蘭不待秋。","花落昭陽誰共輦，月明長信獨登樓。","繁華事逐東流水，團扇悲歌萬古愁。"]', '["讒謗潛来起百憂，朝承恩寵暮仇讎。","火燒白玉非因玷，霜剪紅蘭不待秋。","花落昭陽誰共輦，月明长信独登楼。","繁华事逐东流水，團扇悲歌万古愁。"]', '诗', 'shi', '', NULL, '婕妤怨 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c351fc0-63c0-4593-9caa-ff249e4f8e18', '隴頭吟', '隴头吟', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["隴水潺湲隴樹黃，征人隴上盡思鄉。","馬嘶斜[日]朔風急，雁過寒雲邊思長。","殘月出林明劒戟，平沙隔水見牛羊。","橫行俱是封侯者，誰斬樓蘭獻未央。"]', '["隴水潺湲隴樹黄，征人隴上尽思乡。","马嘶斜[日]朔风急，雁過寒云邊思长。","殘月出林明劒戟，平沙隔水见牛羊。","橫行俱是封侯者，誰斬楼蘭獻未央。"]', '诗', 'shi', '', NULL, '隴頭吟 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce25f448-a77c-45c6-8994-85ac4ad27bf6', '關山月', '关山月', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["裴回漢月滿邊州，照盡天涯到隴頭。","影轉銀河寰海靜，光分玉塞古今愁。","笳吹遠戍孤烽滅，鴈下平沙萬里秋。","況是故園搖落夜，那堪少婦獨登樓。"]', '["裴回漢月满邊州，照尽天涯到隴头。","影轉銀河寰海静，光分玉塞古今愁。","笳吹远戍孤烽滅，鴈下平沙万里秋。","況是故园搖落夜，那堪少婦独登楼。"]', '诗', 'shi', '', NULL, '關山月 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61793401-0569-4aaa-a91d-baab41ba0a0f', '雨雪曲', '雨雪曲', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["邊聲四合殷河流，雨雪飛來遍隴頭。","鐵嶺探人迷鳥道，陰山飛將濕貂裘。","斜飄旌斾過戎帳，半雜風沙入戍樓。","一自塞垣無李蔡，何人爲解北門憂。"]', '["邊声四合殷河流，雨雪飞来遍隴头。","鐵嶺探人迷鸟道，陰山飞將濕貂裘。","斜飄旌斾過戎帳，半杂风沙入戍楼。","一自塞垣無李蔡，何人爲解北门憂。"]', '诗', 'shi', '', NULL, '雨雪曲 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a70bb17-5d6e-41d4-a93c-9be37a738ff5', '行路難', '行路难', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["行路艱難不復歌，故人榮達我蹉跎。","雙輪晚上銅臺雪，一葉春浮瘴海波。","自古要津皆若此，方今失路欲如何。","君看西漢翟丞相，鳳沼朝辭暮雀羅。"]', '["行路艱难不复歌，故人榮達我蹉跎。","雙輪晚上銅台雪，一葉春浮瘴海波。","自古要津皆若此，方今失路欲如何。","君看西漢翟丞相，鳳沼朝辞暮雀羅。"]', '诗', 'shi', '', NULL, '行路難 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4273ba94-ac01-4282-8572-4e0b5aa50acc', '折楊柳', '折楊柳', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["紫陌金隄映綺羅，游人處處動離歌。","陰移古戍迷芳草，花帶殘陽落遠波。","臺上少年吹白雪，樓中思婦歛青蛾。","殷勤攀折贈行客，此去關山雨雪多。"]', '["紫陌金隄映綺羅，游人处处动離歌。","陰移古戍迷芳草，花带殘陽落远波。","台上少年吹白雪，楼中思婦歛青蛾。","殷勤攀折贈行客，此去关山雨雪多。"]', '诗', 'shi', '', NULL, '折楊柳 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5decafa9-ebc2-4c72-a2b7-d936419925cf', '詠酒', '詠酒', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["逃暑迎春復送秋，無非綠蟻滿杯浮。","百年莫惜千回醉，一醆能消萬古愁。","幾爲芳菲眠細草，曾因雨雪上高樓。","平生名利關身者，不識狂歌到白頭。"]', '["逃暑迎春复送秋，無非綠蟻满杯浮。","百年莫惜千回醉，一醆能消万古愁。","幾爲芳菲眠細草，曾因雨雪上高楼。","平生名利关身者，不識狂歌到白头。"]', '诗', 'shi', '', NULL, '詠酒 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82971b1e-b135-4c83-a2d5-81279a019fe6', '白馬', '白马', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["渥洼龍種雪霜同，毛骨天生膽氣雄。","金埒乍調光照地，玉關初別遠嘶風。","花明錦襜垂楊下，露濕朱纓細草中。","一夜羽書催轉戰，紫髯騎出佩騂弓。"]', '["渥洼龙種雪霜同，毛骨天生膽氣雄。","金埒乍調光照地，玉关初別远嘶风。","花明錦襜垂楊下，露濕朱纓細草中。","一夜羽书催轉戰，紫髯騎出佩騂弓。"]', '诗', 'shi', '', NULL, '白馬 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('053f5663-c2ae-49a3-a34a-312e2c30d43a', '句', '句', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["海國歐鄉浙水東，暫煩良守此憑熊。"]', '["海国歐乡浙水东，暫煩良守此憑熊。"]', '诗', 'shi', '', NULL, '句 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2d44be1-edba-4e02-be87-ee3431e4723d', '中秋月', '中秋月', 'a9e038d0-ca8b-4dcc-a4c8-fbeec59b6bb5', '唐', '["古今逢此夜，共冀泬㵳明。","豈是月華別，祗應秋氣清。","影當中土正，輪對八荒平。","尋客徒留望，璿璣自有程。"]', '["古今逢此夜，共冀泬㵳明。","豈是月华別，祗應秋氣清。","影當中土正，輪对八荒平。","尋客徒留望，璿璣自有程。"]', '诗', 'shi', '', NULL, '中秋月 潘緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4848f7e-fccb-4baf-9246-c5fd420729bb', '琴', '琴', 'a9e038d0-ca8b-4dcc-a4c8-fbeec59b6bb5', '唐', '["客來鳴素琴，惆悵對遺音。","一曲起於古，幾人聽到今。","盡含風靄遠，自泛月煙深。","風續水山操，坐生方外心。"]', '["客来鳴素琴，惆悵对遺音。","一曲起於古，幾人听到今。","尽含风靄远，自泛月煙深。","风續水山操，坐生方外心。"]', '诗', 'shi', '', NULL, '琴 潘緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db665eaa-90ac-46a4-bff7-b8f8221de384', '句', '句', 'a9e038d0-ca8b-4dcc-a4c8-fbeec59b6bb5', '唐', '["篆經千古澀，影瀉一堂寒。"]', '["篆經千古澀，影瀉一堂寒。"]', '诗', 'shi', '', NULL, '句 潘緯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19f81e4f-53f0-4f5a-a978-3092d4932ec8', '九日衛使君筵上作', '九日衛使君筵上作', '0b1b4342-6b67-4e80-a04e-41e228d5d624', '唐', '["佳晨登賞喜還鄉，謝宇開筵晚興長。","滿眼黃花初泛酒，隔煙紅樹欲迎霜。","千家門戶笙歌發，十里江山白鳥翔。","共賀安人豐樂歲，幸陪珠履侍銀章。"]', '["佳晨登賞喜還乡，謝宇开筵晚兴长。","满眼黄花初泛酒，隔煙紅樹欲迎霜。","千家门戶笙歌發，十里江山白鸟翔。","共賀安人豐乐歲，幸陪珠履侍銀章。"]', '诗', 'shi', '', NULL, '九日衛使君筵上作 武瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944c059c-6ca6-4727-aab7-28b715aa7c87', '勸酒', '勸酒', '0b1b4342-6b67-4e80-a04e-41e228d5d624', '唐', '["勸君金屈巵，滿酌不須辭。","花發多風雨，人生足別離。"]', '["勸君金屈巵，满酌不須辞。","花發多风雨，人生足別離。"]', '诗', 'shi', '', NULL, '勸酒 武瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d480ad0-a499-41bf-97bb-74550eadd533', '感事', '感事', '0b1b4342-6b67-4e80-a04e-41e228d5d624', '唐', '["花開蝶滿枝，花謝蝶還稀。","惟有舊巢燕，主人貧亦歸。"]', '["花开蝶满枝，花謝蝶還稀。","惟有旧巢燕，主人貧亦归。"]', '诗', 'shi', '', NULL, '感事 武瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('544665e9-d618-4dcb-95e2-7286a387f711', '重歸宜春偶成十六韻寄朝中知己', '重归宜春偶成十六韻寄朝中知己', '6d568364-d89e-4630-b08d-56aff0f5f1dc', '唐', '["水香甘似醴，知是入袁溪。","黃竹成叢密，青蘿夾岸低。","煖流鸂鶒戲，深樹鷓鴣啼。","黃犬驚迎客，青牛困臥泥。","有村皆績紡，無地不耕犂。","鄉曲多耆舊，逢迎盡杖藜。","殷勤傾白酒，相勸有黃雞。","歸老官知忝，還鄉路不迷。","直言干忌諱，權路恥依棲。","拙學趨時態，閑思與牧齊。","稻糧饒燕雀，江海溢鳧鷖。","昔共逢離亂，今來息鼓鼙。","恩仁霑品物，教化及雕題。","上貢貞元祿，曾叨寵記批。","何須歸紫禁，便是到丹梯。","珍重長安道，從今息馬嘶。"]', '["水香甘似醴，知是入袁溪。","黄竹成叢密，青蘿夾岸低。","煖流鸂鶒戲，深樹鷓鴣啼。","黄犬驚迎客，青牛困臥泥。","有村皆績紡，無地不耕犂。","乡曲多耆旧，逢迎尽杖藜。","殷勤傾白酒，相勸有黄雞。","归老官知忝，還乡路不迷。","直言干忌諱，權路恥依棲。","拙学趨时態，闲思與牧齊。","稻糧饒燕雀，江海溢鳧鷖。","昔共逢離亂，今来息鼓鼙。","恩仁霑品物，教化及雕題。","上貢貞元祿，曾叨寵記批。","何須归紫禁，便是到丹梯。","珍重长安道，從今息马嘶。"]', '诗', 'shi', '', NULL, '重歸宜春偶成十六韻寄朝中知己 袁皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a0c1549-e870-458c-9f59-f756c5f3a563', '及第後作', '及第後作', '6d568364-d89e-4630-b08d-56aff0f5f1dc', '唐', '["金榜高懸姓字真，分明折得一枝春。","蓬瀛乍接神仙侶，江海迴思耕釣人。","九萬摶扶排羽翼，十年辛苦涉風塵。","昇平時節逢公道，不覺龍門是嶮津。"]', '["金榜高懸姓字真，分明折得一枝春。","蓬瀛乍接神仙侶，江海迴思耕釣人。","九万摶扶排羽翼，十年辛苦涉风塵。","昇平时節逢公道，不覺龙门是嶮津。"]', '诗', 'shi', '', NULL, '及第後作 袁皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2fdc14-6a44-40bd-a25a-8eadc179bb82', '重歸宜春經過萍川題梵林寺', '重归宜春經過萍川題梵林寺', '6d568364-d89e-4630-b08d-56aff0f5f1dc', '唐', '["梵林遺址在松蘿，四十年來兩度過。","濾水東奔彭蠡浪，萍川西注洞庭波。","村煙不改居人換，官路無窮行客多。","拖紫腰金成底事，凭闌惆悵欲如何。"]', '["梵林遺址在松蘿，四十年来兩度過。","濾水东奔彭蠡浪，萍川西注洞庭波。","村煙不改居人換，官路無窮行客多。","拖紫腰金成底事，凭闌惆悵欲如何。"]', '诗', 'shi', '', NULL, '重歸宜春經過萍川題梵林寺 袁皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f749761-d4a2-4f4f-af7f-96c939b771ec', '寄岳陽嚴使君', '寄岳陽嚴使君', '6d568364-d89e-4630-b08d-56aff0f5f1dc', '唐', '["得意東歸過岳陽，桂枝香惹蘂珠香。","也知暮雨生巫峽，爭奈朝雲屬楚王。","萬恨只憑期尅手，寸心唯繫別離腸。","南亭宴罷笙歌散，回首煙波路渺茫。"]', '["得意东归過岳陽，桂枝香惹蘂珠香。","也知暮雨生巫峽，爭奈朝云屬楚王。","万恨只憑期尅手，寸心唯繫別離腸。","南亭宴罷笙歌散，回首煙波路渺茫。"]', '诗', 'shi', '', NULL, '寄岳陽嚴使君 袁皓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a863ee1-7532-4b3d-8798-80dcc8dc5da4', '賦得郎官上應列宿', '賦得郎官上應列宿', '9e548c5e-ec80-4479-b440-121cc6d9e072', '唐', '["北極佇文昌，南宮曉拜郎。","紫泥乘帝澤，銀印佩天光。","緯結三台側，鉤連四輔傍。","佐商依傅說，仕漢笑馮唐。","委佩搖秋色，峨冠帶晚霜。","自然符列象，千古耀巖廊。"]', '["北極佇文昌，南宮晓拜郎。","紫泥乘帝澤，銀印佩天光。","緯結三台側，鉤連四輔傍。","佐商依傅说，仕漢笑馮唐。","委佩搖秋色，峨冠带晚霜。","自然符列象，千古耀巖廊。"]', '诗', 'shi', '', NULL, '賦得郎官上應列宿 公乘億 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23e19745-689d-43ab-a9b4-bbee518246fb', '春風扇微和', '春风扇微和', '9e548c5e-ec80-4479-b440-121cc6d9e072', '唐', '["麗日催遲景，和風扇早春。","暖浮丹鳳闕，韶媚黑龍津。","澹蕩迎仙仗，霏微送畫輪。","綠搖宮柳散，紅待禁花新。","舞席潛迴雪，歌筵暗起塵。","幸當陽候律，一顧及佳晨。"]', '["丽日催遲景，和风扇早春。","暖浮丹鳳闕，韶媚黑龙津。","澹蕩迎仙仗，霏微送畫輪。","綠搖宮柳散，紅待禁花新。","舞席潛迴雪，歌筵暗起塵。","幸當陽候律，一顧及佳晨。"]', '诗', 'shi', '', NULL, '春風扇微和 公乘億 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('365cf5e5-97f6-4c86-a2c3-0638591bec07', '賦得秋菊有佳色', '賦得秋菊有佳色', '9e548c5e-ec80-4479-b440-121cc6d9e072', '唐', '["陶令籬邊菊，秋來色轉佳。","翠攢千片葉，金剪一枝花。","蘂逐蜂鬚亂，英隨蝶翅斜。","帶香飄綠綺，和酒上烏紗。","散漫搖霜彩，嬌妍漏日華。","芳菲彭澤見，更稱在誰家。"]', '["陶令籬邊菊，秋来色轉佳。","翠攢千片葉，金剪一枝花。","蘂逐蜂鬚亂，英隨蝶翅斜。","带香飄綠綺，和酒上烏紗。","散漫搖霜彩，嬌妍漏日华。","芳菲彭澤见，更稱在誰家。"]', '诗', 'shi', '', NULL, '賦得秋菊有佳色 公乘億 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e286473f-c950-45f1-b1e0-ab2695ee3313', '賦得臨江遲來客', '賦得臨江遲来客', '9e548c5e-ec80-4479-b440-121cc6d9e072', '唐', '["江上晚沈沈，煙波一望深。","向來殊未至，何處擬相尋。","柳結重重眼，萍翻寸寸心。","暮山期共眺，寒渚待同臨。","北去魚無信，南飛雁絕音。","思君不可見，使我獨愁吟。"]', '["江上晚沈沈，煙波一望深。","向来殊未至，何处擬相尋。","柳結重重眼，萍翻寸寸心。","暮山期共眺，寒渚待同臨。","北去鱼無信，南飞雁絕音。","思君不可见，使我独愁吟。"]', '诗', 'shi', '', NULL, '賦得臨江遲來客 公乘億 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd1441f8-efa1-489c-859f-f85839fc5634', '句', '句', '9e548c5e-ec80-4479-b440-121cc6d9e072', '唐', '["十上十年皆落第，一家一半已成塵。"]', '["十上十年皆落第，一家一半已成塵。"]', '诗', 'shi', '', NULL, '句 公乘億 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db92cc3-6601-4b32-9623-51317bb04f5a', '九華山謠', '九华山謠', '8f545a25-1125-465e-a473-0345e979e3b8', '唐', '["九華崢嶸占南陸，蓮花擢本山半腹。","翠屏橫截萬里天，瀑水落深千丈玉。","雲梯石磴入杳冥，俯看四極如中庭。","丹崖壓下廬霍勢，白日隱出牛斗星。","杉松一歲抽數尺，瓊草夤緣秀層壁。","南風拂曉煙霧開，滿山葱蒨鋪鮮碧。","雷霆往往從地發，龍臥豹藏安可別。","峻極遙看戛昊蒼，挺生豈得無才傑。","神仙憚險莫敢登，馭風駕鶴循丘陵。","陽烏不見峰頂樹，大火尚結嵒中冰。","靈光爽氣曛復旭，晴天倒影西江淥。","具區彭蠡夾兩傍，正可別作一嶽當少陽。"]', '["九华崢嶸占南陸，蓮花擢本山半腹。","翠屏橫截万里天，瀑水落深千丈玉。","云梯石磴入杳冥，俯看四極如中庭。","丹崖壓下廬霍勢，白日隐出牛斗星。","杉松一歲抽數尺，瓊草夤緣秀層壁。","南风拂晓煙霧开，满山葱蒨鋪鲜碧。","雷霆往往從地發，龙臥豹藏安可別。","峻極遙看戛昊蒼，挺生豈得無才傑。","神仙憚險莫敢登，馭风駕鹤循丘陵。","陽烏不见峰頂樹，大火尚結嵒中冰。","靈光爽氣曛复旭，晴天倒影西江淥。","具區彭蠡夾兩傍，正可別作一嶽當少陽。"]', '诗', 'shi', '', NULL, '九華山謠 王季文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97044873-3b91-4956-adef-8266fc3b9cb5', '青出藍', '青出藍', '8f545a25-1125-465e-a473-0345e979e3b8', '唐', '["芳藍滋匹帛，人力半天經。","浸潤加新氣，光輝勝本青。","還同冰出水，不共草爲螢。","翻覆依襟上，偏知造化靈。"]', '["芳藍滋匹帛，人力半天經。","浸潤加新氣，光輝勝本青。","還同冰出水，不共草爲螢。","翻覆依襟上，偏知造化靈。"]', '诗', 'shi', '', NULL, '青出藍 王季文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b12421f5-9ffb-43aa-80e1-035bdb78cecb', '題青龍精舍', '題青龙精舍', '2394fa2d-adea-48e3-a85f-8bf1f2afc9db', '唐', '["壽夭雖云命，榮枯亦大偏。","不知雷氏劒，何處更衝天。"]', '["壽夭雖云命，榮枯亦大偏。","不知雷氏劒，何处更衝天。"]', '诗', 'shi', '', NULL, '題青龍精舍 盧駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3374d45f-b43e-4d85-bb20-179d6f0e605c', '感事', '感事', '7d4e4ec1-8f12-4966-9ebd-1051d03e9988', '唐', '["擊石易得火，扣人難動心。","今日朱門者，曾恨朱門深。"]', '["擊石易得火，扣人难动心。","今日朱门者，曾恨朱门深。"]', '诗', 'shi', '', NULL, '感事 王鐐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4722b13d-8c32-4d3f-a6ff-fbe903b14ed3', '退朝望終南山', '退朝望終南山', 'be013a6e-dc3f-4d7f-b2f2-4291697e28ba', '唐', '["紫宸朝罷綴鴛鸞，丹鳳樓前駐馬看。","惟有終南山色在，晴明依舊滿長安。"]', '["紫宸朝罷綴鴛鸾，丹鳳楼前駐马看。","惟有終南山色在，晴明依旧满长安。"]', '诗', 'shi', '', NULL, '退朝望終南山 李拯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b26a0d9-096e-44de-9f3f-4764c1aa445f', '月中桂樹', '月中桂樹', 'c0465bf1-f880-4859-8ce3-081b516fbe9f', '唐', '["芬馥天邊桂，扶疎在月中。","能齊大椿長，不與小山同。","皎皎舒華色，亭亭麗碧空。","虧盈寧委露，搖落不關風。","歲晚花應發，春餘質詎豐。","無因遂攀賞，徒欲望青葱。"]', '["芬馥天邊桂，扶疎在月中。","能齊大椿长，不與小山同。","皎皎舒华色，亭亭丽碧空。","虧盈寧委露，搖落不关风。","歲晚花應發，春餘質詎豐。","無因遂攀賞，徒欲望青葱。"]', '诗', 'shi', '', NULL, '月中桂樹 顧封人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6c9cda-dade-4038-9adf-fc5b46e2b4b9', '和陸魯望白菊', '和陸魯望白菊', '571fc19c-8920-4f62-bad8-32022d33fb61', '唐', '["恥共金英一例開，素芳須待早霜催。","繞籬看見成瑤圃，泛酒須迷傍玉杯。","映水好將蘋作伴，犯寒疑與雪爲媒。","夫君每尚風流事，應爲徐妃致此栽。"]', '["恥共金英一例开，素芳須待早霜催。","繞籬看见成瑤圃，泛酒須迷傍玉杯。","映水好將蘋作伴，犯寒疑與雪爲媒。","夫君每尚风流事，應爲徐妃致此栽。"]', '诗', 'shi', '', NULL, '和陸魯望白菊 司馬都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5edbbaf1-37c8-48d7-8f6c-e4e7fe392edb', '送羊振文先輩往桂陽歸覲', '送羊振文先輩往桂陽归覲', '571fc19c-8920-4f62-bad8-32022d33fb61', '唐', '["此去歡榮冠士林，離筵休恨酒杯深。","雲梯萬仞初高步，月桂餘香尚滿襟。","鳴櫂曉衝蒼靄發，落帆寒動白華吟。","君家祖德惟清苦，却笑當時問絹心。"]', '["此去歡榮冠士林，離筵休恨酒杯深。","云梯万仞初高步，月桂餘香尚满襟。","鳴櫂晓衝蒼靄發，落帆寒动白华吟。","君家祖德惟清苦，却笑當时问絹心。"]', '诗', 'shi', '', NULL, '送羊振文先輩往桂陽歸覲 司馬都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcdd39e3-519f-49b1-ba99-ba6a3990913d', '書邊事', '书邊事', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["朔野煙塵起，天軍又舉戈。","陰風向晚急，殺氣入秋多。","樹盡禽栖草，冰堅路在河。","汾陽無繼者，羌虜肯先和。"]', '["朔野煙塵起，天軍又舉戈。","陰风向晚急，殺氣入秋多。","樹尽禽栖草，冰堅路在河。","汾陽無繼者，羌虜肯先和。"]', '诗', 'shi', '', NULL, '書邊事 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62d40055-f939-4d66-ac26-b0e267a76b9a', '遠歸別墅', '远归別墅', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["馬省曾行處，連嘶渡晚河。","忽驚鄉樹出，漸識路人多。","細徑穿禾黍，頹垣壓薜蘿。","乍歸猶似客，鄰叟亦相過。"]', '["马省曾行处，連嘶渡晚河。","忽驚乡樹出，漸識路人多。","細徑穿禾黍，頹垣壓薜蘿。","乍归猶似客，鄰叟亦相過。"]', '诗', 'shi', '', NULL, '遠歸別墅 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e902cf0-c49b-4148-82f9-b64f6910ec1a', '題友人屋', '題友人屋', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["松底詩人宅，閑門遠岫孤。","數家分小徑，一水截平蕪。","竹節偶相對，鳥名多自呼。","愛君真靜者，欲去又踟躕。"]', '["松底诗人宅，闲门远岫孤。","數家分小徑，一水截平蕪。","竹節偶相对，鸟名多自呼。","愛君真静者，欲去又踟躕。"]', '诗', 'shi', '', NULL, '題友人屋 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2c8f85-b2cd-4dbb-b338-2dccb712df87', '贈同遊', '贈同游', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["此來風雨後，已覺減年華。","若待皆無事，應難更有花。","管弦臨夜急，榆柳向江斜。","且莫看歸路，同須醉酒家。"]', '["此来风雨後，已覺減年华。","若待皆無事，應难更有花。","管弦臨夜急，榆柳向江斜。","且莫看归路，同須醉酒家。"]', '诗', 'shi', '', NULL, '贈同遊 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9627a6d-5265-4cf8-a922-6f169581eb4f', '送人出塞', '送人出塞', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["北風吹雨雪，舉目已悽悽。","戰鬼秋頻哭，征鴻夜不栖。","沙平關路直，磧廣郡樓低。","此去非東魯，人多事鼓鼙。"]', '["北风吹雨雪，舉目已悽悽。","戰鬼秋頻哭，征鴻夜不栖。","沙平关路直，磧廣郡楼低。","此去非东魯，人多事鼓鼙。"]', '诗', 'shi', '', NULL, '送人出塞 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('091266bf-de09-4607-91f7-be2f18551844', '尋僧元皎因贈', '尋僧元皎因贈', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["此生迷有著，因病得尋師。","話盡山中事，歸當月上時。","高松連寺影，亞竹入窗枝。","閑憶草堂路，相逢非素期。"]', '["此生迷有著，因病得尋師。","話尽山中事，归當月上时。","高松連寺影，亞竹入窗枝。","闲憶草堂路，相逢非素期。"]', '诗', 'shi', '', NULL, '尋僧元皎因贈 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec8d9b8-6a24-4cdb-b33b-59f64312d006', '下第後蒙侍郎示意指於新先輩宣恩感謝', '下第後蒙侍郎示意指於新先輩宣恩感謝', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["才薄命如此，自嗟兼自疑。","遭逢好文日，黜落至公時。","倚玉甘無路，穿楊却未期。","更慙君侍坐，問許可言詩。"]', '["才薄命如此，自嗟兼自疑。","遭逢好文日，黜落至公时。","倚玉甘無路，穿楊却未期。","更慙君侍坐，问許可言诗。"]', '诗', 'shi', '', NULL, '下第後蒙侍郎示意指於新先輩宣恩感謝 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab528fa-4fb8-4ecc-aa06-e0a59728c768', '夜泊渭津', '夜泊渭津', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["漂漂東去客，一宿渭城邊。","遠處星垂岸，中流月滿船。","涼歸夜深簟，秋入雨餘天。","漸覺家山小，殘程尚幾年。"]', '["漂漂东去客，一宿渭城邊。","远处星垂岸，中流月满船。","涼归夜深簟，秋入雨餘天。","漸覺家山小，殘程尚幾年。"]', '诗', 'shi', '', NULL, '夜泊渭津 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab1b2a9-85c9-4e20-b5b5-849400524d83', '晚夏逢友人', '晚夏逢友人', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["一別同袍友，相思已十年。","長安多在客，久病忽聞蟬。","驟雨纔沾地，陰雲不徧天。","微涼堪話舊，移榻晚風前。"]', '["一別同袍友，相思已十年。","长安多在客，久病忽闻蟬。","驟雨纔沾地，陰云不徧天。","微涼堪話旧，移榻晚风前。"]', '诗', 'shi', '', NULL, '晚夏逢友人 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a731e1d7-bdca-4d32-8e89-0cb720a7497b', '秋中夜坐', '秋中夜坐', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["空庭吟坐久，爽氣入荷衣。","病葉先秋落，驚禽背月飛。","瘴雲晴未散，戍客老將依。","爲應金門策，多應說戰機。"]', '["空庭吟坐久，爽氣入荷衣。","病葉先秋落，驚禽背月飞。","瘴云晴未散，戍客老將依。","爲應金门策，多應说戰機。"]', '诗', 'shi', '', NULL, '秋中夜坐 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bdd7dcd-edf2-451b-baed-40552949568f', '旅遊傷春', '旅游傷春', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["酒醒鄉關遠，迢迢聽漏終。","曙分林影外，春盡雨聲中。","鳥思江村路，花殘野岸風。","十年成底事，羸馬倦西東。"]', '["酒醒乡关远，迢迢听漏終。","曙分林影外，春尽雨声中。","鸟思江村路，花殘野岸风。","十年成底事，羸马倦西东。"]', '诗', 'shi', '', NULL, '旅遊傷春 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e8de951-46c6-4912-9333-f19d48323dbf', '得遠書', '得远书', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["故人居謫宦，今日一書來。","良久驚兼喜，殷勤卷更開。","瘴雲沉去鴈，江雨促新梅。","滿紙殊鄉淚，非冤不可哀。"]', '["故人居謫宦，今日一书来。","良久驚兼喜，殷勤卷更开。","瘴云沉去鴈，江雨促新梅。","满紙殊乡泪，非冤不可哀。"]', '诗', 'shi', '', NULL, '得遠書 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba420ba2-434d-48c8-b11f-27a90aafb9ff', '贈同席', '贈同席', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["四座列吾友，滿園花照衣。","一生知幾度，後到擬先歸。","急管侵諸樂，嚴城送落暉。","當歡莫離席，離席却歡稀。"]', '["四座列吾友，满园花照衣。","一生知幾度，後到擬先归。","急管侵諸乐，嚴城送落暉。","當歡莫離席，離席却歡稀。"]', '诗', 'shi', '', NULL, '贈同席 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60aadee1-96f4-4f3f-9efd-61c72e456ee5', '贈供奉僧玄觀', '贈供奉僧玄观', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["自得曹溪法，諸經更不看。","已降禪侶久，兼作帝師難。","夜木侵簷黑，秋燈照雨寒。","如何嫌有著，一念在林巒。"]', '["自得曹溪法，諸經更不看。","已降禪侶久，兼作帝師难。","夜木侵簷黑，秋灯照雨寒。","如何嫌有著，一念在林巒。"]', '诗', 'shi', '', NULL, '贈供奉僧玄觀 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfbc244a-82e5-47ed-b833-5ee1d90d008a', '送琴客', '送琴客', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["楚客抱離思，蜀琴留恨聲。","坐來新月上，聽久覺秋生。","夜靜騷人語，天高別鶴鳴。","因君興一歎，竟夕意難平。"]', '["楚客抱離思，蜀琴留恨声。","坐来新月上，听久覺秋生。","夜静騷人語，天高別鹤鳴。","因君兴一歎，竟夕意难平。"]', '诗', 'shi', '', NULL, '送琴客 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216fdfd8-5808-4b58-a4fa-dfac986fafb2', '別謫者', '別謫者', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["此地聞猶惡，人言是所之。","一家書絕久，孤驛夢成遲。","八月三湘道，聞猿冒雨時。","不須祠楚相，臣節轉堪疑。"]', '["此地闻猶惡，人言是所之。","一家书絕久，孤驛梦成遲。","八月三湘道，闻猿冒雨时。","不須祠楚相，臣節轉堪疑。"]', '诗', 'shi', '', NULL, '別謫者 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe8280e-4730-47d2-9b17-9efcf72f81fd', '行思', '行思', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["千里豈云去，欲歸如路窮。","人間無暇日，馬上又秋風。","破月銜高岳，流星拂曉空。","此時皆在夢，行色獨怱怱。"]', '["千里豈云去，欲归如路窮。","人间無暇日，马上又秋风。","破月銜高岳，流星拂晓空。","此时皆在梦，行色独怱怱。"]', '诗', 'shi', '', NULL, '行思 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c302ddc-a33c-4d46-80fd-09fb31a48be9', '感懷題從舅宅', '感懷題從舅宅', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["郗家庭樹下，幾度醉春風。","今日花還發，當時事不同。","流言應未息，直道竟難通。","徒遣相思者，悲歌向暮空。"]', '["郗家庭樹下，幾度醉春风。","今日花還發，當时事不同。","流言應未息，直道竟难通。","徒遣相思者，悲歌向暮空。"]', '诗', 'shi', '', NULL, '感懷題從舅宅 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d625aba-40bf-4ea3-ada1-5192afae7eb5', '與友人會', '與友人會', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["蟬吟槐蘂落，的的是愁端。","病覺離家遠，貧知處事難。","真交無所隱，深語有餘歡。","未必聞歌吹，羈心得暫寬。"]', '["蟬吟槐蘂落，的的是愁端。","病覺離家远，貧知处事难。","真交無所隐，深語有餘歡。","未必闻歌吹，羈心得暫寬。"]', '诗', 'shi', '', NULL, '與友人會 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1e7f88-cc7b-4e3c-a63b-228e2d2a0efb', '贈春遊侶', '贈春游侶', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["密林多暗香，輕吹送餘芳。","啼鳥愁春盡，遊人喜日長。","浮雲橫暮色，新雨洗韶光。","欲散垂□恨，應須入醉鄉。"]', '["密林多暗香，轻吹送餘芳。","啼鸟愁春尽，游人喜日长。","浮云橫暮色，新雨洗韶光。","欲散垂□恨，應須入醉乡。"]', '诗', 'shi', '', NULL, '贈春遊侶 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c6ec18-e83b-459d-be63-b5731b81e669', '送人遊邊', '送人游邊', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["愁指蕭關外，風沙入遠程。","馬行初有跡，雨落竟無聲。","地理全歸漢，天威不在兵。","西京逢故老，暗喜復時平。"]', '["愁指蕭关外，风沙入远程。","马行初有跡，雨落竟無声。","地理全归漢，天威不在兵。","西京逢故老，暗喜复时平。"]', '诗', 'shi', '', NULL, '送人遊邊 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36784f56-32aa-485f-9150-5df6c71507c2', '寄棲白上人', '寄棲白上人', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["剪髪兼成隱，將心更屬文。","無憀對豪客，不拜謁吾君。","畫壁惟泉石，經窗半典墳。","歸林幽鳥狎，乞食病僧分。","默坐終清夜，凝思念碧雲。","相逢應未卜，余正走囂氛。"]', '["剪髪兼成隐，將心更屬文。","無憀对豪客，不拜謁吾君。","畫壁惟泉石，經窗半典墳。","归林幽鸟狎，乞食病僧分。","默坐終清夜，凝思念碧云。","相逢應未卜，余正走囂氛。"]', '诗', 'shi', '', NULL, '寄棲白上人 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed813572-9cf9-4e6e-be67-8fb00dcaa4ff', '送人入新羅使', '送人入新羅使', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["雞林君欲去，立冊付星軺。","越海程難計，征帆影自飄。","望鄉當落日，懷闕羨迴潮。","宿霧蒙青嶂，驚波蕩碧霄。","春生陽氣早，天接祖州遙。","愁約三年外，相迎上石橋。"]', '["雞林君欲去，立冊付星軺。","越海程难計，征帆影自飄。","望乡當落日，懷闕羨迴潮。","宿霧蒙青嶂，驚波蕩碧霄。","春生陽氣早，天接祖州遙。","愁約三年外，相迎上石橋。"]', '诗', 'shi', '', NULL, '送人入新羅使 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc7ef10a-3d5b-4bec-a92b-f41409144fee', '詠鐵馬鞭', '詠鐵马鞭', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["漢將臨流得鐵鞭，鄂侯名字舊雕鐫。","須爲聖代無雙物，肯逐將軍臥九泉。","汗馬不侵誅虜血，神功今見補亡篇。","時來終薦明君用，莫歎沉埋二百年。"]', '["漢將臨流得鐵鞭，鄂侯名字旧雕鐫。","須爲聖代無雙物，肯逐將軍臥九泉。","汗马不侵誅虜血，神功今见補亡篇。","时来終薦明君用，莫歎沉埋二百年。"]', '诗', 'shi', '', NULL, '詠鐵馬鞭 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9652616-3106-45ff-981d-059cbe54b2f6', '送友人', '送友人', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["舉世誰能與事期，解攜多是正歡時。","人間不遣有名利，陌上始應無別離。","晚渡待船愁立久，亂山投店獨行遲。","我今漂泊還如此，江劒相逢亦未知。"]', '["舉世誰能與事期，解携多是正歡时。","人间不遣有名利，陌上始應無別離。","晚渡待船愁立久，亂山投店独行遲。","我今漂泊還如此，江劒相逢亦未知。"]', '诗', 'shi', '', NULL, '送友人 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f15349ab-a6e5-47b9-ab3f-856871f8c575', '南潭', '南潭', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["匝岸青蕪掩古苔，面山亭樹枕潭開。","有時弦管收筵促，無數鳧鷖逆浪來。","路入龍祠羣木老，風驚漁艇一聲迴。","人傳郭惲多遊此，誰見當初泛玉杯。"]', '["匝岸青蕪掩古苔，面山亭樹枕潭开。","有时弦管收筵促，無數鳧鷖逆浪来。","路入龙祠羣木老，风驚漁艇一声迴。","人傳郭惲多游此，誰见當初泛玉杯。"]', '诗', 'shi', '', NULL, '南潭 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c748fc-6d8f-4dad-bfed-b3fdf3d8bceb', '秋夜作', '秋夜作', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["數畝池塘近杜陵，秋天寂寞夜雲凝。","芙蓉葉上三更雨，蟋蟀聲中一點燈。","跡避險巇翻失路，心歸閑澹不因僧。","既逢上國陳詩日，長守林泉亦未能。"]', '["數畝池塘近杜陵，秋天寂寞夜云凝。","芙蓉葉上三更雨，蟋蟀声中一点灯。","跡避險巇翻失路，心归闲澹不因僧。","既逢上国陳诗日，长守林泉亦未能。"]', '诗', 'shi', '', NULL, '秋夜作 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c44188a-7566-4a14-8cfb-4e1fe3dda03d', '客恨', '客恨', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["古原南北舊蕭疎，高木風多小雪餘。","半夜病吟人寢後，百年閑事酒醒初。","頻招兄弟同佳節，已有兵戈隔遠書。","肥馬王孫定相笑，不知岐路厭樵漁。"]', '["古原南北旧蕭疎，高木风多小雪餘。","半夜病吟人寢後，百年闲事酒醒初。","頻招兄弟同佳節，已有兵戈隔远书。","肥马王孫定相笑，不知岐路厭樵漁。"]', '诗', 'shi', '', NULL, '客恨 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2481eef-ccc9-446d-a7ae-c5fc31491ee2', '三月盡日', '三月尽日', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["江頭從此管弦稀，散盡遊人獨未歸。","落日已將春色去，殘花應逐夜風飛。"]', '["江头從此管弦稀，散尽游人独未归。","落日已將春色去，殘花應逐夜风飞。"]', '诗', 'shi', '', NULL, '三月盡日 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f2f6ce-da4c-46aa-9cac-4534345ad263', '綠珠詠', '綠珠詠', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["洛陽佳麗與芳華，金谷園中見百花。","誰遣當年墜樓死，無人巧笑破孫家。"]', '["洛陽佳丽與芳华，金谷园中见百花。","誰遣當年墜楼死，無人巧笑破孫家。"]', '诗', 'shi', '', NULL, '綠珠詠 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c850dded-9e51-4f4f-904f-86e3a5b4a202', '贈別', '贈別', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["又將書劒出孤舟，盡日停橈結遠愁。","莫道江波話離別，江波一去不迴流。"]', '["又將书劒出孤舟，尽日停橈結远愁。","莫道江波話離別，江波一去不迴流。"]', '诗', 'shi', '', NULL, '贈別 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69b16c8f-833b-436b-8180-bc0d658e735d', '悶書', '悶书', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["病來難處早秋天，一徑無人樹有蟬。","歸計未成書半卷，中宵多夢晝多眠。"]', '["病来难处早秋天，一徑無人樹有蟬。","归計未成书半卷，中宵多梦晝多眠。"]', '诗', 'shi', '', NULL, '悶書 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c1ab440-1691-44fa-9841-c113e7c709b8', '傷春', '傷春', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["即是春風盡，仍霑夜雨歸。","明朝更來此，兼恐落花稀。"]', '["即是春风尽，仍霑夜雨归。","明朝更来此，兼恐落花稀。"]', '诗', 'shi', '', NULL, '傷春 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cf79ffb-3579-4da7-80b2-19f5460a5d43', '登臨洮望蕭關', '登臨洮望蕭关', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["漸覺風沙暗，蕭關欲到時。","兒童能探火，婦女解縫旗。","川少銜魚鷺，林多帶箭麋。","暫來戎馬地，不敢苦吟詩。"]', '["漸覺风沙暗，蕭关欲到时。","兒童能探火，婦女解縫旗。","川少銜鱼鷺，林多带箭麋。","暫来戎马地，不敢苦吟诗。"]', '诗', 'shi', '', NULL, '登臨洮望蕭關 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1d6819-1620-493e-bc97-7375264a6b5c', '彭澤', '彭澤', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["鶴愛孤松雲愛山，宦情微祿免相關。","栽成五柳吟歸去，漉酒巾邊伴菊閑。"]', '["鹤愛孤松云愛山，宦情微祿免相关。","栽成五柳吟归去，漉酒巾邊伴菊闲。"]', '诗', 'shi', '', NULL, '彭澤 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('294976dd-9957-45d5-bab7-f9a236a99def', '杜郵館', '杜郵館', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["殺盡降兵熱血流，一心猶自逞戈矛。","功成若解求身退，豈得將軍死杜郵。"]', '["殺尽降兵熱血流，一心猶自逞戈矛。","功成若解求身退，豈得將軍死杜郵。"]', '诗', 'shi', '', NULL, '杜郵館 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad2796a-48cb-4151-9245-facf265ce53c', '細腰宮', '細腰宮', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["鼓聲連日燭連宵，貪向春風舞細腰。","爭奈君王正沈醉，秦兵江上促征橈。"]', '["鼓声連日燭連宵，貪向春风舞細腰。","爭奈君王正沈醉，秦兵江上促征橈。"]', '诗', 'shi', '', NULL, '細腰宮 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9145cdfe-c305-4a0a-aaca-e07763bc466d', '瑤臺', '瑤台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["仙夢香魂不久留，滿川雲雨滿宮愁。","直須待得荆王死，始向瑤臺一處遊。"]', '["仙梦香魂不久留，满川云雨满宮愁。","直須待得荆王死，始向瑤台一处游。"]', '诗', 'shi', '', NULL, '瑤臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('570052f4-d023-426a-bc61-78d3c2f394db', '吳坂', '吳坂', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["踡跼鹽車萬里蹄，忽逢良鑒始能嘶。","不緣伯樂稱奇骨，幾與駑駘價一齊。"]', '["踡跼鹽车万里蹄，忽逢良鑒始能嘶。","不緣伯乐稱奇骨，幾與駑駘價一齊。"]', '诗', 'shi', '', NULL, '吳坂 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf024664-f2b1-4fce-aa5d-81641efae642', '箕山', '箕山', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["薄世臨流洗耳塵，便歸雲洞任天真。","一瓢風入猶嫌鬧，何況人間萬種人。"]', '["薄世臨流洗耳塵，便归云洞任天真。","一瓢风入猶嫌鬧，何況人间万種人。"]', '诗', 'shi', '', NULL, '箕山 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3760a4f0-4a87-400e-8b6f-85e36d264eb2', '息國', '息国', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["家國興亡身獨存，玉容還受楚王恩。","銜冤只合甘先死，何待花間不肯言。"]', '["家国兴亡身独存，玉容還受楚王恩。","銜冤只合甘先死，何待花间不肯言。"]', '诗', 'shi', '', NULL, '息國 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a358dfc-47a6-49eb-95a4-e1dc11547bc3', '梁寺', '梁寺', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["立國從來爲戰功，一朝何事却談空。","臺城兵匝無人敵，閑臥高僧滿梵宮。"]', '["立国從来爲戰功，一朝何事却談空。","台城兵匝無人敵，闲臥高僧满梵宮。"]', '诗', 'shi', '', NULL, '梁寺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71e895e-ae6e-4263-af87-b77ed5975260', '南陽', '南陽', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["陸困泥蟠未適從，豈妨耕嫁隱高蹤。","若非先主垂三顧，誰識茅廬一臥龍。"]', '["陸困泥蟠未適從，豈妨耕嫁隐高蹤。","若非先主垂三顧，誰識茅廬一臥龙。"]', '诗', 'shi', '', NULL, '南陽 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3ba9235-0a95-466d-b484-2038c8cf28da', '杞梁墓', '杞梁墓', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["一呌長城萬仞摧，杞梁遺骨逐妻回。","南鄰北里皆孀婦，誰解堅心繼此來。"]', '["一呌长城万仞摧，杞梁遺骨逐妻回。","南鄰北里皆孀婦，誰解堅心繼此来。"]', '诗', 'shi', '', NULL, '杞梁墓 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd38d52c-5d2b-4333-9e62-44ed49b545bb', '夷門', '夷门', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["晉鄙兵回爲重難，秦師收斾亦西還。","今來不是無朱亥，誰降軒車問抱關。"]', '["晉鄙兵回爲重难，秦師收斾亦西還。","今来不是無朱亥，誰降軒车问抱关。"]', '诗', 'shi', '', NULL, '夷門 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50c31d00-b5ea-475a-b273-39655dcc8a4c', '汴河', '汴河', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["隋皇意欲泛龍舟，千里崑崙水別流。","還待春風錦帆暖，柳陰相送到迷樓。"]', '["隋皇意欲泛龙舟，千里崑崙水別流。","還待春风錦帆暖，柳陰相送到迷楼。"]', '诗', 'shi', '', NULL, '汴河 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c591e80b-9628-422a-a259-8c1150d6de10', '燕臺', '燕台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["禮士招賢萬古名，高臺依舊對燕城。","如今寂寞無人上，春去秋來草自生。"]', '["禮士招賢万古名，高台依旧对燕城。","如今寂寞無人上，春去秋来草自生。"]', '诗', 'shi', '', NULL, '燕臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47afeb95-375d-407a-91d0-68cdd6bc91c6', '聊城', '聊城', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["刃血攻聊已越年，竟憑儒術罷戈鋋。","田單漫逞燒牛計，一箭終輸魯仲連。"]', '["刃血攻聊已越年，竟憑儒術罷戈鋋。","田單漫逞燒牛計，一箭終輸魯仲連。"]', '诗', 'shi', '', NULL, '聊城 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959ebc64-baeb-4319-bb05-520d2350872b', '西河', '西河', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["花貌年年溺水濱，俗傳河伯娶生人。","自從明宰投巫後，直至如今鬼不神。"]', '["花貌年年溺水濱，俗傳河伯娶生人。","自從明宰投巫後，直至如今鬼不神。"]', '诗', 'shi', '', NULL, '西河 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('994d1a03-de61-4f78-a99e-b9a63de5c320', '密縣', '密縣', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["百里能將濟猛寬，飛蝗不到邑人安。","至今閭里逢災沴，猶祝當時卓長官。"]', '["百里能將濟猛寬，飞蝗不到邑人安。","至今閭里逢災沴，猶祝當时卓长官。"]', '诗', 'shi', '', NULL, '密縣 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f85094a-4ef5-4fa7-bd3e-1723c3934dc7', '昇仙橋', '昇仙橋', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["題橋貴欲露先誠，此日人皆笑率情。","應訝臨邛沽酒客，逢時還作漢公卿。"]', '["題橋貴欲露先誠，此日人皆笑率情。","應訝臨邛沽酒客，逢时還作漢公卿。"]', '诗', 'shi', '', NULL, '昇仙橋 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c5daeb-6765-4903-8d95-e04df95b11ac', '破陳', '破陳', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["獵獵朱旗映綵霞，紛紛白刃入陳家。","看看打破東平苑，猶舞庭前玉樹花。"]', '["獵獵朱旗映綵霞，紛紛白刃入陳家。","看看打破东平苑，猶舞庭前玉樹花。"]', '诗', 'shi', '', NULL, '破陳 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc23c9f1-55af-48ad-9b68-b519ee6940ea', '白頭吟', '白头吟', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["失却青絲素髪生，合歡羅帶意全輕。","古今人事皆如此，不獨文君與馬卿。"]', '["失却青絲素髪生，合歡羅带意全轻。","古今人事皆如此，不独文君與马卿。"]', '诗', 'shi', '', NULL, '白頭吟 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d591eb99-a637-411a-b918-037a79f3b523', '短歌吟', '短歌吟', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["箭飛烏兔競東西，貴賤賢愚不夢齊。","匣裏有琴樽有酒，人間便是武陵溪。"]', '["箭飞烏兔競东西，貴賤賢愚不梦齊。","匣裏有琴樽有酒，人间便是武陵溪。"]', '诗', 'shi', '', NULL, '短歌吟 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7503ebcd-fc91-41af-b637-015557bc978c', '晉河', '晉河', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["風引征帆管吹高，晉君張[宴]俟雄豪。","舟人笑指千餘客，誰是煙霄六翮毛。"]', '["风引征帆管吹高，晉君張[宴]俟雄豪。","舟人笑指千餘客，誰是煙霄六翮毛。"]', '诗', 'shi', '', NULL, '晉河 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cdf1d0c-eea2-4e6a-b101-689c55aef64b', '干將墓', '干將墓', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["橐籥冰霜萬古聞，拍灰松地見餘墳。","應緣神劒飛揚久，水水山山盡是雲。"]', '["橐籥冰霜万古闻，拍灰松地见餘墳。","應緣神劒飞揚久，水水山山尽是云。"]', '诗', 'shi', '', NULL, '干將墓 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2eb4a9-767e-4c86-a52c-6dbef1abf877', '金谷', '金谷', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["晉臣榮盛更誰過，常向階前舞翠娥。","香散豔消如一夢，但留風月伴煙蘿。"]', '["晉臣榮盛更誰過，常向階前舞翠娥。","香散豔消如一梦，但留风月伴煙蘿。"]', '诗', 'shi', '', NULL, '金谷 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94604940-162a-489e-a373-f8cd0b21cf42', '三閭廟', '三閭廟', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["爲嫌朝野盡陶陶，不覺官高怨亦高。","憔悴莫酬漁父笑，浪交千載詠離騷。"]', '["爲嫌朝野尽陶陶，不覺官高怨亦高。","憔悴莫酬漁父笑，浪交千載詠離騷。"]', '诗', 'shi', '', NULL, '三閭廟 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef03c2f4-656e-4ce8-b162-63bfe92cf1b1', '易水', '易水', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["[匕]首空磨事不成，誤留龍袂待琴聲。","斯須却作秦中鬼，青史徒標烈士名。"]', '["[匕]首空磨事不成，誤留龙袂待琴声。","斯須却作秦中鬼，青史徒標烈士名。"]', '诗', 'shi', '', NULL, '易水 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e04319aa-5570-4347-929d-a22c329a0f69', '嚴陵臺', '嚴陵台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["一釣淒涼在杳冥，故人飛詔入山扃。","終將寵辱輕軒冕，高臥五雲爲客星。"]', '["一釣淒涼在杳冥，故人飞詔入山扃。","終將寵辱轻軒冕，高臥五云爲客星。"]', '诗', 'shi', '', NULL, '嚴陵臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a2271fa-6d70-417b-8308-83984fa2c447', '淮陰', '淮陰', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["秦季賢愚混不分，只應漂母識王孫。","歸榮便累千金贈，爲報當時一飯恩。"]', '["秦季賢愚混不分，只應漂母識王孫。","归榮便累千金贈，爲報當时一飯恩。"]', '诗', 'shi', '', NULL, '淮陰 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e6dd53-f5c2-4cc7-946e-da0e778f109a', '雞鳴曲', '雞鳴曲', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["金距花冠傍舍棲，清晨相呌一聲齊。","開關自有馮生計，不必天明待汝啼。"]', '["金距花冠傍舍棲，清晨相呌一声齊。","开关自有馮生計，不必天明待汝啼。"]', '诗', 'shi', '', NULL, '雞鳴曲 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f9d225-6876-4e19-b622-055de1a9c0ad', '採桑婦', '採桑婦', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["爲報躊躇陌上郎，蠶飢日晚妾心忙。","本來若愛黃金好，不肯攜籠更採桑。"]', '["爲報躊躇陌上郎，蠶飢日晚妾心忙。","本来若愛黄金好，不肯携籠更採桑。"]', '诗', 'shi', '', NULL, '採桑婦 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7bd6a97-1713-4cfc-bb5d-0fb0c6b7cca3', '漁父', '漁父', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["棹月眠流處處通，綠蓑葦帶混元風。","靈均說盡孤高事，全與逍遙意不同。"]', '["棹月眠流处处通，綠蓑葦带混元风。","靈均说尽孤高事，全與逍遙意不同。"]', '诗', 'shi', '', NULL, '漁父 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd937db1-0c8b-4da7-ab46-6f25f53b5a4f', '越女', '越女', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["玉貌何曾爲浣沙，只圖句踐獻夫差。","蘇臺日夜唯歌舞，不覺干戈犯翠華。"]', '["玉貌何曾爲浣沙，只圖句踐獻夫差。","蘇台日夜唯歌舞，不覺干戈犯翠华。"]', '诗', 'shi', '', NULL, '越女 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c643ce83-99c6-4d8b-be7b-491051637def', '望思臺', '望思台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["不憂家國任姦臣，骨肉翻爲驀路人。","巫蠱事行冤莫雪，九層徒築見無因。"]', '["不憂家国任姦臣，骨肉翻爲驀路人。","巫蠱事行冤莫雪，九層徒築见無因。"]', '诗', 'shi', '', NULL, '望思臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d287078-2d29-45bf-b7bd-54dc4aa1822d', '比干墓', '比干墓', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["國亂時危道不行，忠賢諫死勝謀生。","一沈冤骨千年後，壠水雖平恨未平。"]', '["国亂时危道不行，忠賢諫死勝謀生。","一沈冤骨千年後，壠水雖平恨未平。"]', '诗', 'shi', '', NULL, '比干墓 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a3a784-4858-4550-8b05-ecf912727134', '郢中', '郢中', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["莫言白雪少人聽，高調都難稱俗情。","不是楚詞詢宋玉，巴歌猶掩繞梁聲。"]', '["莫言白雪少人听，高調都难稱俗情。","不是楚词詢宋玉，巴歌猶掩繞梁声。"]', '诗', 'shi', '', NULL, '郢中 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d56aa6-cb97-4ef8-9183-5dd2631526f9', '北海', '北海', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["漢臣曾此作縲囚，茹血衣毛十九秋。","鶴髪半垂龍節在，不聞青史說封侯。"]', '["漢臣曾此作縲囚，茹血衣毛十九秋。","鹤髪半垂龙節在，不闻青史说封侯。"]', '诗', 'shi', '', NULL, '北海 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc7b419-b8e4-4579-b446-38626bc8cb84', '招屈亭', '招屈亭', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["三閭溺處殺懷王，感得荆人盡縞裳。","招屈亭邊兩重恨，遠天秋色暮蒼蒼。"]', '["三閭溺处殺懷王，感得荆人尽縞裳。","招屈亭邊兩重恨，远天秋色暮蒼蒼。"]', '诗', 'shi', '', NULL, '招屈亭 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f191020-8a68-4bc1-9854-c0fc74be99e0', '屈祠', '屈祠', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["不肯迂回入醉鄉，乍吞忠梗沒滄浪。","至今祠畔猨啼月，了了猶疑恨楚王。"]', '["不肯迂回入醉乡，乍吞忠梗沒滄浪。","至今祠畔猨啼月，了了猶疑恨楚王。"]', '诗', 'shi', '', NULL, '屈祠 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d320d2-0328-44a5-9c77-a306ca9021ff', '銅雀臺', '銅雀台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["銅雀臺成玉座空，短歌長袖盡悲風。","不知仙駕歸何處，徒遣顰眉望漢宮。"]', '["銅雀台成玉座空，短歌长袖尽悲风。","不知仙駕归何处，徒遣顰眉望漢宮。"]', '诗', 'shi', '', NULL, '銅雀臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ff3034d-e93b-4c70-8f1a-90d71b8e3a2f', '斑竹祠', '斑竹祠', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["九處煙霞九處昏，一回延首一銷魂。","因憑直節流紅淚，圖得千秋見血痕。"]', '["九处煙霞九处昏，一回延首一銷魂。","因憑直節流紅泪，圖得千秋见血痕。"]', '诗', 'shi', '', NULL, '斑竹祠 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6017571a-62cb-4026-a501-1a34d3dbf49f', '題李太尉平泉莊', '題李太尉平泉莊', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["水泉花木好高眠，嵩少縱橫滿目前。","惆悵人間不平事，今朝身在海南邊。"]', '["水泉花木好高眠，嵩少縱橫满目前。","惆悵人间不平事，今朝身在海南邊。"]', '诗', 'shi', '', NULL, '題李太尉平泉莊 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa397b3-cfad-4fbc-bb38-3b2e9a2b4932', '戰城南', '戰城南', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["風沙刮地塞雲愁，平旦交鋒晚未休。","白骨又霑新戰血，青天猶列舊旄頭。"]', '["风沙刮地塞云愁，平旦交鋒晚未休。","白骨又霑新戰血，青天猶列旧旄头。"]', '诗', 'shi', '', NULL, '戰城南 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3261e9f-dea4-4289-b099-11b82b4d8b72', '延平津', '延平津', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["三尺晶熒射斗牛，豈隨凡手報冤讎。","延平一旦爲龍處，看取風雲布九州。"]', '["三尺晶熒射斗牛，豈隨凡手報冤讎。","延平一旦爲龙处，看取风云布九州。"]', '诗', 'shi', '', NULL, '延平津 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5895455a-f2d8-46c5-a3d9-6fcddd2235f8', '項亭', '項亭', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["不修仁德合文明，天道如何擬力爭。","隔岸故鄉歸不得，十年空負拔山名。"]', '["不修仁德合文明，天道如何擬力爭。","隔岸故乡归不得，十年空負拔山名。"]', '诗', 'shi', '', NULL, '項亭 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9219c42-cfc6-4351-b0d1-f585ab9da82a', '烏江', '烏江', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["兵散弓殘挫虎威，單槍匹馬突重圍。","英雄去盡羞容在，看却江東不得歸。"]', '["兵散弓殘挫虎威，單槍匹马突重圍。","英雄去尽羞容在，看却江东不得归。"]', '诗', 'shi', '', NULL, '烏江 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a76bec87-e535-4e5d-b26d-72e74c80103f', '綠珠', '綠珠', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["大抵花顏最怕秋，南家歌歇北家愁。","從來幾許如君貌，不肯如君墜玉樓。"]', '["大抵花顏最怕秋，南家歌歇北家愁。","從来幾許如君貌，不肯如君墜玉楼。"]', '诗', 'shi', '', NULL, '綠珠 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e0f5f20-6c17-4501-aff5-eecc2367ed02', '升仙橋', '升仙橋', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["漢朝卿相盡風雲，司馬題橋衆又聞。","何事不如楊得意，解搜賢哲薦明君。"]', '["漢朝卿相尽风云，司马題橋衆又闻。","何事不如楊得意，解搜賢哲薦明君。"]', '诗', 'shi', '', NULL, '升仙橋 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('419886f2-bbac-4e85-b3ee-7e8e46944c3e', '隋柳', '隋柳', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["夾浪分堤萬樹餘，爲迎龍舸到江都。","君看靖節高眠處，只向衡門種五株。"]', '["夾浪分堤万樹餘，爲迎龙舸到江都。","君看靖節高眠处，只向衡门種五株。"]', '诗', 'shi', '', NULL, '隋柳 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e0522e2-a7c4-484b-9fb5-9918c96c3521', '楊柳', '楊柳', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["亞夫營畔柳濛濛，隋主堤邊四路通。","攀折贈君還有意，翠眉輕嫩怕春風。"]', '["亞夫營畔柳濛濛，隋主堤邊四路通。","攀折贈君還有意，翠眉轻嫩怕春风。"]', '诗', 'shi', '', NULL, '楊柳 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04788171-e5ce-4eeb-a79d-45d650c4c1ba', '桐江', '桐江', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["光武重興四海寧，漢臣無不受浮榮。","嚴陵何事輕軒冕，獨向桐江釣月明。"]', '["光武重兴四海寧，漢臣無不受浮榮。","嚴陵何事轻軒冕，独向桐江釣月明。"]', '诗', 'shi', '', NULL, '桐江 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a9138b-4b55-40b9-bf8a-543991cd83c7', '招隱', '招隐', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["罷聽泉聲看鹿羣，丈夫才策合匡君。","早攜書劒離巖谷，莫待蒲輪輾白雲。"]', '["罷听泉声看鹿羣，丈夫才策合匡君。","早携书劒離巖谷，莫待蒲輪輾白云。"]', '诗', 'shi', '', NULL, '招隱 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00a2b3ef-4980-4841-bf44-149856512b39', '陳宮', '陳宮', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["椒宮荒宴竟無疑，倏忽山河盡入隋。","留得後庭亡國曲，至今猶與酒家吹。"]', '["椒宮荒宴竟無疑，倏忽山河尽入隋。","留得後庭亡国曲，至今猶與酒家吹。"]', '诗', 'shi', '', NULL, '陳宮 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4320cb2a-8e6c-400f-ab61-c208adff0651', '樊將軍廟', '樊將軍廟', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["玉輦曾經陷楚營，漢皇心怯擬休兵。","當時不得將軍力，日月須分一半明。"]', '["玉輦曾經陷楚營，漢皇心怯擬休兵。","當时不得將軍力，日月須分一半明。"]', '诗', 'shi', '', NULL, '樊將軍廟 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed04cccc-fd39-49c9-a6f8-e0cc6a247ecd', '東海', '东海', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["漾舟雪浪映花顏，徐福攜將竟不還。","同作危時避秦客，此行何似武陵灘。"]', '["漾舟雪浪映花顏，徐福携將竟不還。","同作危时避秦客，此行何似武陵灘。"]', '诗', 'shi', '', NULL, '東海 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e68e55e8-8ccf-4876-b5e8-1aa7abb6ddb4', '昭君', '昭君', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["漢家天子鎮寰瀛，塞北羌胡未罷兵。","猛將謀臣徒自貴，蛾眉一笑塞塵清。"]', '["漢家天子鎮寰瀛，塞北羌胡未罷兵。","猛將謀臣徒自貴，蛾眉一笑塞塵清。"]', '诗', 'shi', '', NULL, '昭君 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c56958-de59-44a6-b9ac-16c63ced163f', '五湖', '五湖', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["已立平吳霸越功，片帆高颺五湖風。","不知戰國官榮者，誰似陶朱得始終。"]', '["已立平吳霸越功，片帆高颺五湖风。","不知戰国官榮者，誰似陶朱得始終。"]', '诗', 'shi', '', NULL, '五湖 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e42d09-6192-4831-9f6a-490e309e9d23', '澠池', '澠池', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["西秦北趙各稱高，池上張筵列我曹。","何事君王親擊缶，相如有劒可吹毛。"]', '["西秦北趙各稱高，池上張筵列我曹。","何事君王親擊缶，相如有劒可吹毛。"]', '诗', 'shi', '', NULL, '澠池 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0931f471-e4ab-4dae-ae46-4766f309160a', '函谷關', '函谷关', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["脫禍東奔壯氣摧，馬如飛電轂如雷。","當時若不聽彈鋏，那得關門半夜開。"]', '["脫禍东奔壯氣摧，马如飞電轂如雷。","當时若不听彈鋏，那得关门半夜开。"]', '诗', 'shi', '', NULL, '函谷關 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b84be1-4b3c-4263-b155-fda62af96b04', '詠酒二首 一', '詠酒二首 一', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["九醞松醪一曲歌，本圖閑放養天和。","後人不識前賢意，破國亡家事甚多。"]', '["九醞松醪一曲歌，本圖闲放養天和。","後人不識前賢意，破国亡家事甚多。"]', '诗', 'shi', '', NULL, '詠酒二首 一 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34985a03-b05c-4e90-89bc-ee208ee4a037', '詠酒二首 二', '詠酒二首 二', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["萬事銷沈向一杯，竹門啞軋爲風開。","秋宵睡足芭蕉雨，又是江湖入夢來。"]', '["万事銷沈向一杯，竹门啞軋爲风开。","秋宵睡足芭蕉雨，又是江湖入梦来。"]', '诗', 'shi', '', NULL, '詠酒二首 二 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8976102-538f-413b-befe-240d3c9e8da0', '蒼頡臺', '蒼頡台', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["觀跡成文代結繩，皇風儒教浩然興。","幾人從此休耕釣，吟對長安雪夜燈。"]', '["观跡成文代結繩，皇风儒教浩然兴。","幾人從此休耕釣，吟对长安雪夜灯。"]', '诗', 'shi', '', NULL, '蒼頡臺 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a121c97e-dab5-4caa-af60-0335913f93ed', '長城', '长城', '644b5ee8-e190-46c4-ab1e-ba18ff83659e', '唐', '["秦築長城比鐵牢，蕃戎不敢過臨洮。","雖然萬里連雲際，爭及堯階三尺高。"]', '["秦築长城比鐵牢，蕃戎不敢過臨洮。","雖然万里連云際，爭及堯階三尺高。"]', '诗', 'shi', '', NULL, '長城 汪遵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525f7715-adc4-4738-9cc9-bb546c153ae5', '過洞庭湖', '過洞庭湖', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["驚波常不定，半日鬢堪斑。","四顧疑無地，中流忽有山。","鳥高恆畏墜，帆遠却如閑。","漁父閑相引，時歌浩渺間。"]', '["驚波常不定，半日鬢堪斑。","四顧疑無地，中流忽有山。","鸟高恆畏墜，帆远却如闲。","漁父闲相引，时歌浩渺间。"]', '诗', 'shi', '', NULL, '過洞庭湖 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a8c311-344b-4e44-a1f8-3d19d3241d91', '登渭南縣樓', '登渭南縣楼', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["近甸名偏著，登城景又寬。","半空分太華，極目是長安。","雪助河流漲，人耕燒色殘。","閑來時甚少，欲下重憑欄。"]', '["近甸名偏著，登城景又寬。","半空分太华，極目是长安。","雪助河流漲，人耕燒色殘。","闲来时甚少，欲下重憑欄。"]', '诗', 'shi', '', NULL, '登渭南縣樓 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1c5531-71aa-4fe0-82aa-c01e6080fdc5', '送李頻之南陵主簿', '送李頻之南陵主簿', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["赴縣是還鄉，途程豈覺長。","聽鶯離灞岸，盪槳入陵陽。","野蕨生公署，閑雲拂印牀。","晴天調膳外，垂釣有池塘。"]', '["赴縣是還乡，途程豈覺长。","听鶯離灞岸，盪槳入陵陽。","野蕨生公署，闲云拂印牀。","晴天調膳外，垂釣有池塘。"]', '诗', 'shi', '', NULL, '送李頻之南陵主簿 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b2f378d-0ee5-4c99-a293-10ba7679a21c', '寫懷', '寫懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["汩沒與辛勤，全鍾在此身。","半生爲下客，終老託何人。","兩鬢關中改，千巖海上春。","青雲知有路，自是致無因。"]', '["汩沒與辛勤，全鍾在此身。","半生爲下客，終老託何人。","兩鬢关中改，千巖海上春。","青云知有路，自是致無因。"]', '诗', 'shi', '', NULL, '寫懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c077282f-8e6d-4007-bd29-e9befa1436bc', '過中條山', '過中條山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["徒爲經異岳，不得訪靈蹤。","日盡行難盡，千重復萬重。","雲垂多作雨，雷動半和鐘。","孤竹人藏處，無因認本峰。"]', '["徒爲經異岳，不得訪靈蹤。","日尽行难尽，千重复万重。","云垂多作雨，雷动半和鐘。","孤竹人藏处，無因認本峰。"]', '诗', 'shi', '', NULL, '過中條山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b067e07-e74c-4dcb-bc91-cd9abdf9149e', '早發洛中', '早發洛中', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["半夜發清洛，不知過石橋。","雲增中岳大，樹隱上陽遙。","塹黑初沉月，河明欲認潮。","孤村人尚夢，無處暫停橈。"]', '["半夜發清洛，不知過石橋。","云增中岳大，樹隐上陽遙。","塹黑初沉月，河明欲認潮。","孤村人尚梦，無处暫停橈。"]', '诗', 'shi', '', NULL, '早發洛中 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe871e6-6b82-4219-ab47-d0ba5d2f7020', '汝州郡樓望嵩山', '汝州郡楼望嵩山', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["不共衆山同，岧嶤出迥空。","幾層高鳥外，萬仞一樓中。","水落難歸地，雲離便逐風。","唯應霄漢客，絕頂路方通。"]', '["不共衆山同，岧嶤出迥空。","幾層高鸟外，万仞一楼中。","水落难归地，云離便逐风。","唯應霄漢客，絕頂路方通。"]', '诗', 'shi', '', NULL, '汝州郡樓望嵩山 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01fa2181-579a-4367-b5b9-520a4009dd86', '將歸江南留別友人', '將归江南留別友人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["連春不得意，所業已疑非。","舊國亂離後，新年惆悵歸。","雪開還楚地，花惹別秦衣。","江徼多留滯，高秋會恐違。"]', '["連春不得意，所業已疑非。","旧国亂離後，新年惆悵归。","雪开還楚地，花惹別秦衣。","江徼多留滯，高秋會恐違。"]', '诗', 'shi', '', NULL, '將歸江南留別友人 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e4dcb9-52a2-4c27-b0e4-b8fee1c7fb7e', '塞外書事', '塞外书事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["征路出窮邊，孤吟傍戍煙。","河光深蕩塞，磧色迥連天。","殘日沉鵰外，驚蓬到馬前。","空懷釣魚所，未定卜歸年。"]', '["征路出窮邊，孤吟傍戍煙。","河光深蕩塞，磧色迥連天。","殘日沉鵰外，驚蓬到马前。","空懷釣鱼所，未定卜归年。"]', '诗', 'shi', '', NULL, '塞外書事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc95c6cd-61e7-4de0-ac05-3b5a05cd3774', '日暮江上', '日暮江上', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["孤帆收廣岸，落照在遙峰。","南北渡人少，高低歸鳥重。","潮回沙出樹，雨過浦沉鐘。","漁父雖相問，那能話所從。"]', '["孤帆收廣岸，落照在遙峰。","南北渡人少，高低归鸟重。","潮回沙出樹，雨過浦沉鐘。","漁父雖相问，那能話所從。"]', '诗', 'shi', '', NULL, '日暮江上 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb826e50-cffe-4a96-a281-4b4fa7bd11aa', '客行', '客行', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["旅食唯草草，此生誰我同。","故園魂夢外，長路別離中。","人事萍隨水，年光鳥過空。","欲吟先落淚，多是怨途窮。"]', '["旅食唯草草，此生誰我同。","故园魂梦外，长路別離中。","人事萍隨水，年光鸟過空。","欲吟先落泪，多是怨途窮。"]', '诗', 'shi', '', NULL, '客行 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08b03b0a-2c77-4743-a064-3bd62c5cef8e', '送李員外知揚子州留務', '送李員外知揚子州留務', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["帝命分留務，東南向楚天。","幾程迴送騎，中路見迎船。","冶例開山鑄，民多酌海煎。","青雲名素重，此去豈經年。"]', '["帝命分留務，东南向楚天。","幾程迴送騎，中路见迎船。","冶例开山鑄，民多酌海煎。","青云名素重，此去豈經年。"]', '诗', 'shi', '', NULL, '送李員外知揚子州留務 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fddf3c33-1130-4929-ad5b-9826b36b5c2e', '春暮途次華山下', '春暮途次华山下', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["他皆宴牡丹，獨又出長安。","遠道行非易，無圖住自難。","離城風已暖，近岳雨翻寒。","此去知誰顧，閑吟祗自寬。"]', '["他皆宴牡丹，独又出长安。","远道行非易，無圖住自难。","離城风已暖，近岳雨翻寒。","此去知誰顧，闲吟祗自寬。"]', '诗', 'shi', '', NULL, '春暮途次華山下 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2fd26b-4016-452e-bd73-1eedba51a47a', '旅次滑臺投獻陸侍御', '旅次滑台投獻陸侍御', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["已是鴻來日，堪驚却背秦。","天遙三楚樹，路遠兩河人。","旅夢難歸隱，吟魂不在身。","霜臺欹冠豸，賴許往來頻。"]', '["已是鴻来日，堪驚却背秦。","天遙三楚樹，路远兩河人。","旅梦难归隐，吟魂不在身。","霜台欹冠豸，賴許往来頻。"]', '诗', 'shi', '', NULL, '旅次滑臺投獻陸侍御 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de2a7bdd-a37f-4f4e-a57a-a64e68300a0e', '重歸江南', '重归江南', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["無成歸故里，不似在他鄉。","歲月逐流水，山川空夕陽。","回潮迷古渡，迸竹過鄰墻。","耆舊休存省，胡爲止淚行。"]', '["無成归故里，不似在他乡。","歲月逐流水，山川空夕陽。","回潮迷古渡，迸竹過鄰墻。","耆旧休存省，胡爲止泪行。"]', '诗', 'shi', '', NULL, '重歸江南 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5674592-9a68-40d1-ad94-faf25941098e', '寄黔南李校書', '寄黔南李校书', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["從戎巫峽外，吟興更應多。","郡響蠻江漲，山昏蜀雨過。","公筵饒越味，俗土尚巴歌。","中夜懷吳夢，知經灩澦波。"]', '["從戎巫峽外，吟兴更應多。","郡响蠻江漲，山昏蜀雨過。","公筵饒越味，俗土尚巴歌。","中夜懷吳梦，知經灩澦波。"]', '诗', 'shi', '', NULL, '寄黔南李校書 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43bdd58d-99fd-4919-b981-6e700a096611', '東歸留辭沈侍郎', '东归留辞沈侍郎', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["一第久乖期，深心已自疑。","滄江歸恨遠，紫閣別愁遲。","稽古成何事，龍鍾負已知。","依門非近日，不慮舊恩移。"]', '["一第久乖期，深心已自疑。","滄江归恨远，紫閣別愁遲。","稽古成何事，龙鍾負已知。","依门非近日，不慮旧恩移。"]', '诗', 'shi', '', NULL, '東歸留辭沈侍郎 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94d5ff73-9ac9-49c0-aa0d-c1af4f8cd2c6', '題開明里友人居', '題开明里友人居', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["城中塵外住，入望是田家。","井出深山水，闌藏異國花。","風巢和鳥動，雪竹向人斜。","來往唯君熟，鄉園共海涯。"]', '["城中塵外住，入望是田家。","井出深山水，闌藏異国花。","风巢和鸟动，雪竹向人斜。","来往唯君熟，乡园共海涯。"]', '诗', 'shi', '', NULL, '題開明里友人居 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fbd1f60-13c5-4808-b12d-c4e21ee9923b', '遣懷', '遣懷', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["此生何處遂，屑屑復悠悠。","舊國歸無計，他鄉夢亦愁。","飛塵長滿眼，衰髪暗添頭。","章句非經濟，終難動五侯。"]', '["此生何处遂，屑屑复悠悠。","旧国归無計，他乡梦亦愁。","飞塵长满眼，衰髪暗添头。","章句非經濟，終难动五侯。"]', '诗', 'shi', '', NULL, '遣懷 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10e9b5ce-d0bf-4cff-8293-ca8128448804', '送龍州樊使君', '送龙州樊使君', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["曾見邛人說，龍州地未深。","碧溪飛白鳥，紅斾映青林。","土產唯宜藥，王租只貢金。","政成開宴日，誰伴使君吟。"]', '["曾见邛人说，龙州地未深。","碧溪飞白鸟，紅斾映青林。","土產唯宜藥，王租只貢金。","政成开宴日，誰伴使君吟。"]', '诗', 'shi', '', NULL, '送龍州樊使君 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d376e02-fa38-4fb4-84ed-a4141d1e7bef', '寄盩厔薛能少府', '寄盩厔薛能少府', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["滿縣唯雲水，何曾似近畿。","曉庭猿集慣，寒署吏衙稀。","冰色封深澗，樵聲出紫微。","時聞迎隱者，依舊著山衣。"]', '["满縣唯云水，何曾似近畿。","晓庭猿集慣，寒署吏衙稀。","冰色封深澗，樵声出紫微。","时闻迎隐者，依旧著山衣。"]', '诗', 'shi', '', NULL, '寄盩厔薛能少府 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9efcd3e-1207-42f9-a991-beaf17ec4808', '送李左丞巡邊', '送李左丞巡邊', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["狂戎侵內地，左轄去蕭關。","走馬衝邊雪，鳴鞞動塞山。","風收枯草定，月滿廣沙閑。","西繞河蘭匝，應多隔歲還。"]', '["狂戎侵內地，左轄去蕭关。","走马衝邊雪，鳴鞞动塞山。","风收枯草定，月满廣沙闲。","西繞河蘭匝，應多隔歲還。"]', '诗', 'shi', '', NULL, '送李左丞巡邊 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b3b3871-80c0-4313-b8cf-5d34f0b190ff', '題青山館', '題青山館', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["境概殊諸處，依然是謝家。","遺文齊日月，舊井照煙霞。","水隔平蕪遠，山橫度鳥斜。","無人能此隱，來往謾興嗟。"]', '["境概殊諸处，依然是謝家。","遺文齊日月，旧井照煙霞。","水隔平蕪远，山橫度鸟斜。","無人能此隐，来往謾兴嗟。"]', '诗', 'shi', '', NULL, '題青山館 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0c4519-736c-46fb-a080-6aaecf6c9d87', '鴈門關野望', '鴈门关野望', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["高關閑獨望，望久轉愁人。","紫塞唯多雪，胡山不盡春。","河遙分斷野，樹亂起飛塵。","時見東來騎，心知近別秦。"]', '["高关闲独望，望久轉愁人。","紫塞唯多雪，胡山不尽春。","河遙分斷野，樹亂起飞塵。","时见东来騎，心知近別秦。"]', '诗', 'shi', '', NULL, '鴈門關野望 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fbe45e8-bbff-4b65-81a7-c79680d9a894', '五原書事', '五原书事', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["西出黃雲外，東懷白浪遙。","星河愁立夜，雷電獨行朝。","磧迥人防寇，天空鴈避鵰。","如何非戰卒，弓劒不離腰。"]', '["西出黄云外，东懷白浪遙。","星河愁立夜，雷電独行朝。","磧迥人防寇，天空鴈避鵰。","如何非戰卒，弓劒不離腰。"]', '诗', 'shi', '', NULL, '五原書事 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54d95c1-02cc-468a-9e60-9f0710a9d381', '送從弟歸泉州', '送從弟归泉州', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["問省歸南服，懸帆任北風。","何山猶見雪，半路已無鴻。","瘴雜春雲重，星垂夜海空。","往來如不住，亦是一年中。"]', '["问省归南服，懸帆任北风。","何山猶见雪，半路已無鴻。","瘴杂春云重，星垂夜海空。","往来如不住，亦是一年中。"]', '诗', 'shi', '', NULL, '送從弟歸泉州 許棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4c364c-e867-405a-9877-dc8a7f077641', '留別故人', '留別故人', '9359b2e5-d3a8-48c4-979e-18471c9aeaad', '唐', '["殊立本不偶，非唯今所難。","無門閑共老，盡日泣相看。","鳥畏聞鶗鴂，花慚背牡丹。","何人知此計，復議出長安。"]', '["殊立本不偶，非唯今所难。","無门闲共老，尽日泣相看。","鸟畏闻鶗鴂，花慚背牡丹。","何人知此計，复議出长安。"]', '诗', 'shi', '', NULL, '留別故人 許棠 shi');
